-- =============================================================================
-- city_data Wikipedia leírások – 4/4. fájl
-- Települések: 771 (Szajol … Ősi)
-- Futtasd az előző batch(ek) után.
-- =============================================================================

UPDATE public.city_data AS c
SET panel_leiras = v.panel_leiras
FROM (
  VALUES
    ('Szajol', 'Szajol az Alföld közepén, Budapesttől 110 kilométer-re, Szolnoktól mintegy 10 kilométer-re keletre fekszik, a Tisza és egy hajdani morotvája közé beékelve. Északon a Holt-Tisza part határolja az ófalut, míg délen egészen a vasútvonalig érnek az újtelep lakott területei. Éghajlata száraz kontinentális, elsősorban forró, napsütéses nyár, hideg tél jellemzi.'),
    ('Szakadát', 'A dunántúli római uralom idején is megült hely. A honfoglalás után a Szák nemzetség veszi birtokába. A 12. században már egyházas hely. 1214-ben Merő János birtokában találjuk. Egy 1298-ban kelt oklevél templomáról tesz említést. A 14. század második felében Tikai István és Niko Miklós osztoznak a határ birtokában helyezkedik el.'),
    ('Szakcs', 'A település már az római korban lakott volt, Szakcs határában terült el az Iovia nevű település. A korábban csak írott forrásokból ismert város első nyomait az 1890-es években fedezték fel, a Szakcs lakott területétől délre eső, ma Felsőleperd–Gölösi-malom néven nyilvántartott régészeti lelőhelyen. 2000-ben légi felvételek elemzésével azonosították a mintegy 600 x 600 méteres területen elhelyezkedő települést, majd az első komolyabb ásatások 2016-ban kezdődtek.'),
    ('Szakmár', 'Kalocsa vonzáskörzetében helyezkedik el, a várostól légvonalban körülbelül 8, közúton mintegy 10 kilométerre kelet-északkeleti irányban. Északi külterületeinek jelentős része a Kiskunsági Nemzeti Park Miklapuszta nevű területrészéhez tartozik. A szomszédos települések: észak felől Dunapataj, északkelet felől Kiskőrös, kelet felől Kecel, délkelet felől Öregcsertő, dél felől Homokmégy, délnyugat felől Kalocsa, nyugat felől Uszód, északnyugat felől pedig Újtelek.'),
    ('Szaknyér', 'A falu az Őrségben, az Őrségi Nemzeti Park területén fekszik, Körmendtől 22 kilométerre délre, Őriszentpétertől 16 kilométerre keletre, Hegyhátszentjakabtól 1 kilométerre nyugatra. A falu a középkorban Szatmér, Szatmir alakban fordul elő az oklevelekben, ez valószínűleg a személynévi eredetű Szatmárral hozható összefüggésbe. Az Őrséghez tartozott. A 15. században is a Lévai Cseheké volt, majd a 15. század második felében az Újlakiaké lett.'),
    ('Szakoly', 'Elérhetőség vasúton: Vasútállomása nincs, a Nagykálló–Nyíradony-vasútvonalon legközelebb Balkányban (4 kilométer) volt, de ott 2007. március 4-én "ideiglenesen" megszűnt a forgalom. Nyírmihálydi állomása (az Apafa–Mátészalka-vasútvonalon) kb. 6 kilométer-re van. A településen a 4913-as számú országút halad át. Debrecentől 37 kilométer-re található, míg Nyíregyházától 35 kilométer-re.'),
    ('Szakonyfalu', 'A falu a 17. század közepéig más területen helyezkedett el. Jóval délebbre volt található, s belenyúlt a mai Apátistvánfalva és Kétvölgy területére. Az 1664-es szentgotthárdi csata idején a török sereg itt a Rába mellett foglalt hídfőállást, előzőleg a falut felégették, a lakosság elmenekült. A csata után visszatértek és az egykori hídfőnél építették fel újra falujukat.'),
    ('Szakácsi', 'Edelénytől északkeletre fekszik. Közigazgatási területén ágazik ki az előbbi útból a 26 133-as út, amely a zsákfalunak tekinthető Irotára vezet. Szakácsi nevét 1300-ban említették először az oklevelek Zakachy alakban írva. 1300-ban egy oklevél egy idevaló nemest említett, aki borsodi ügyben tanúskodott. A falu a török időkben elpusztult, de később újratelepült.'),
    ('Szakáld', 'A tiszaújvárosi kistérség északkeleti részén fekszik, a Sajó és a Hejő között. A térséget átszelő főutak mind elkerülik, ami nem kedvez a gazdasági életének. A közvetlenül határos települések: észak felől Muhi, északkelet felől Nagycsécs, kelet felől Sajószöged, délkelet felől Hejőbába, dél felől Hejőpapi, nyugat felől Hejőszalonta, északnyugat felől pedig Hejőkeresztúr.'),
    ('Szakály', 'A rómaiak az i. e. 1 század végén, Pannónia területén kelta-pannon törzseket találtak. Szakályban ilyen kelta település nyomaira bukkantak. László korában, 1273-ban a korabeli iratokban Szakály, Zakal néven szerepel. Szakállyal szemben, a mostani malom környékén terült el Csernéd, ahol már 1351-ben, majd 1399-től folyamatosan megyegyűlést tartották, egészen 1543-ig, a török betöréséig.'),
    ('Szalafő', 'Szalafő hét halmon épült, ún. „szeres település”, amelynek mindegyik dombja egy-egy „szer”: Alsószer, Csörgőszer, Felsőszer, Gyöngyösszer, Papszer és Templomszer, illetve Pityerszer. A falu őrzi a honfoglalás kori településszerkezetet. Nevét a határában eredő Zala folyóról kapta, melyet a helyiek „Szala” néven említenek.'),
    ('Szalapa', 'Önkormányzata Óhídon működik. A Keszthelyi-fennsík északi nyúlványánál, a Marcali-háton fekszik. A legközelebbi város Zalaszentgrót, 8 kilométerre helyezkedik el. A község mind Zalaszentgrót, mind Sümeg felől autóbuszon jól elérhető. Első ismert írásos említése 1265-ből való, ám ezt követően egészen 1430-ig nem szólnak róla a források. A településen ekkor csak nemesek éltek, birtokosai a Tekenyei, az Őri, a Fodor, a Csillag, a Forintos és a Szegedi családok voltak.'),
    ('Szalaszend', 'A Cserehát keleti, a Hernád völgyének pedig a nyugati oldalán fekszik, a Bélus-patak folyása mentén észak-déli irányban elnyúlva. Három, korábban különálló falu egyesülésével jött létre. A közvetlenül határos települések: észak felől Fulókércs, kelet felől Novajidrány, délkelet felől Méra, délnyugat felől Encs, északnyugat felől pedig Fáj. Csak közúton érhető el, Méra vagy Szalaszend érintésével, a 2626-os úton.'),
    ('Szalatnak', 'Szalatnak az ország déli részén elterülő középmagasságú Mecsek hegység északi részén fekszik. Vasúton elérhető a Dombóvár–Bátaszék-vasútvonalon, amelynek egy megállási pontja van itt, Szalatnak megállóhely. A falu területének tengerszint feletti magassága 220-230 méter között ingadozik. 1325: Zalathna néven találni az első, már megbízhatónak tűnő említést a faluról. 12-13 házas település, amely nem éli túl a török időket. 1725. szeptember 29-én Szalatnakra települő németek megkötötték az első letelepedési szerződést Baranyában.'),
    ('Szalkszentmárton', 'Budapesttől és Kecskeméttől egyaránt körülbelül 60 kilométer választja el. A település lapos határa valaha a Duna ártere volt. Az új Pentele híd átadása óta a község közúton mindössze 25 kilométerre van a térség legnagyobb városának számító Dunaújvárostól. A szomszédos települések: észak felől Tass, kelet felől Kunszentmiklós-Bösztörpuszta, dél felől Dunavecse, nyugat felől pedig Dunaújváros.'),
    ('Szalmatercs', 'Szécsénytől északkeletre fekszik, Endrefalva és Karancsság közt. A Novohrad-Nógrád UNESCO Globális Geopark települése. A községet érintő helyközi autóbuszvonalak az alábbiakː 1010, 3072, 3080, 3081, 3082. Szalmatercs nevét az 1332–1337 évi pápai tizedjegyzék említette először, tehát ekkor már egyházas hely volt. 1548-ban Szalmatercsy Mihály és Bebek Ferenc birtoka volt.'),
    ('Szalonna', 'Miskolctól 50 kilométerre, Szendrőtől 7 kilométer-re, míg Edelénytől 21 kilométer-re északra a Rakaca-patak széles völgyében, a Szalonnai-hegység déli széle alatt (a Szár-hegy déli nyúlványánál), a Rakaca-víztározó és a Bódva közelében terül el. A közvetlenül szomszédos települések: északkelet felől Martonyi, kelet felől Meszes, dél felől Szendrő, nyugat felől pedig Perkupa.'),
    ('Szalánta', 'Első írásos említése 1192-ből ismert. Az 1690-es években katolikus bosnyákok költöztek be. A faluban óvoda és általános iskola is működik. Pécs közelsége miatt jelenleg is fejlődő település. A Baranyai-dombságban, Pécs és Harkány között majdnem félúton fekszik, mindkettőtől nagyjából 12-13 kilométerre. A szomszédos falvak: észak-északkelet felől Pogány, kelet felől Szőkéd és Áta. délkelet felől Bisse, dél felől Túrony, nyugat felől Bosta, északnyugat felől pedig Kökény.'),
    ('Szamosangyalos', 'A környező települések közül Csenger 8,5, Ököritófülpös 13, Fehérgyarmat 30, Porcsalma 6, Pátyod pedig 3 kilométer távolságra található. Szamosangyalos az oklevelek szerint már az 1300-as években is jelentős hely lehetett, mivel 1381-ben már egyházát is említik az okiratok.'),
    ('Szamosbecs', 'Lakott területei és közigazgatási területének túlnyomó része a folyó jobb partján helyezkednek el, de egy kisebb határrésze a bal parti oldalon helyezkedik el, illetve tartozik hozzá egy sziget is. A közvetlenül határos települések: észak felől Csegöld, északkelet felől Csengersima, délkelet felől Komlódtótfalu, dél felől Csenger, nyugat felől Szamosangyalos – utóbbi kettő a folyó túlsó, bal partján –, északnyugat felől pedig Szamostatárfalva.'),
    ('Szamoskér', 'A Szatmári-síkságon fekszik, a Szamos folyó bal partján, a megyeszékhely Nyíregyházától mintegy 78 kilométerre keletre. A szomszédos települései: észak felől Kérsemjén, kelet felől Nábrád, dél felől Tunyogmatolcs, északnyugat felől pedig Szamosszeg. Csak közúton érhető el, Tunyogmatolcs vagy Szamosszeg érintésével, mindkét irányból a 4120-as úton. Szamoskér (Kér) Árpád-kori település.'),
    ('Szamosszeg', 'A Szatmári-síkság keleti csücskében, a Szamos és a Kraszna között fekszik, a megyeszékhely Nyíregyházától mintegy 72 kilométer távolságra. A szomszédos települések: észak felől Olcsvaapáti, kelet felől Panyola, délkelet felől Szamoskér, dél felől Tunyogmatolcs és Mátészalka, délnyugat felől Ópályi, nyugat felől Nagydobos, északnyugat felől pedig Olcsva.'),
    ('Szamossályi', 'Jánkmajtis 3,5 kilométer, Hermánszeg 2 kilométer, Szamosújlak 2,5 kilométer, Gyügye 9 kilométer, Fehérgyarmat 17,5 kilométer távolságra található. A település és környéke már ősidők óta lakott helynek számít, amit az itt talált kőkori leletek is bizonyítanak. Első ismert írásos említése 1181-ből való. Később 1277-ben, majd 1325-ben is említették, mint a Kaplony nemzetségbeli Dénes, illetve a Káta nemzetségbeli János birtokát. 1350-ben a Csaholyi család őse, Ábrahám fia Péter tulajdonába kerül. 1477-ben „Saly” néven említik.'),
    ('Szamostatárfalva', 'Lakott területei és közigazgatási területének túlnyomó része a folyó jobb parti oldalán helyezkednek el, de egy kisebb határrésze a bal parton található. Mindössze három települési szomszédja van: észak felől Csegöld, délkelet felől Szamosbecs, délnyugat felől pedig Szamosangyalos. A legközelebbi város Csenger, légvonalban kb. 4,5, közúton mintegy 8 kilométerre helyezkedik el.'),
    ('Szamosújlak', 'Szomszédai: észak felől Zsarolyán, északkelet felől Jánkmajtis, délkelet felől Szamossályi, dél felől Porcsalma, nyugat felől pedig Gyügye. Ez utóbbi a legközelebbi szomszédja, melytől alig 2 kilométer választja el. A megyeszékhely, Nyíregyháza 82, a környék más fontosabb települései közül Mátészalka 26, Fehérgyarmat 12, Csengersima 15, Kisar pedig 20 kilométerre található.'),
    ('Szanda', 'Ismert történelme közel 800 évet ölel fel, fénykorát a 15. században élte, amikor egy ideig városi rangot is viselt. A Cserhát belsejében, a Szanda-hegy északi lábánál fekszik. A Novohrad-Nógrád UNESCO Globális Geopark települése. A legközelebbi település Terény, mintegy 2 kilométerre északra helyezkedik el. Szanda Árpád-kori település. Nevét 1214-ben említette először oklevél Zunda néven. 1232-ben Scunda, 1279-ben és 1331-ben Zonda néven írták. 1214-ben II.'),
    ('Szank', 'A település a Duna-Tisza közén fekszik, a legközelebbi várostól, Kiskunmajsától 8 kilométerre északnyugatra. A szomszédos települések: észak felől Móricgát, északkelet felől Jászszentlászló, délkelet felől Kiskunmajsa, délnyugat felől Tázlár, északnyugat felől pedig Bócsa. A községgel kapcsolatos első ismert, írásos emlék szerint ,,Zank szállása" 1451-ben már templommal rendelkező település volt.'),
    ('Szany', 'Magyarország északnyugati részén, a Kisalföld déli peremterületén, a Rábaközben fekszik, a Rába folyótól 3 kilométerre északra, Csornától 18 kilométerre délre. A Rába vízgyűjtő területéhez tartozik. Határát átszelik a Szil–Sárdos-ér, a Vág–Sárdos-ér–Megág csatornák és a Makk-ér. Szép környezetben lévő öthektáros horgásztava a kavicsbányászat nyomán keletkezett.'),
    ('Szaporca', 'A Kelet-Ormánságban, a Dráva közelében fekszik, a folyótól mintegy 3 kilométerre, a Fekete-víz mellett. Kémes déli szomszédságában helyezkedik el, közel Cúnhoz és Tésenfához. A falu határában húzódik az EuroVelo nemzetközi kerékpárút-hálózat 13. számú, „Vasfüggöny” útvonalának horvát-magyar határ menti szakasza, amelynek itt ér véget a Drávasztáráról induló 4. számú etapja, és itt kezdődik a Harkányig tartó 5. etap.'),
    ('Szarvas', 'A Békési-síkon, Békéscsabától 47 kilométerre, a Hármas-Körös holtágának partján (kákafoki holtág) helyezkedik el. Közigazgatási területén van a Magyar Királyság (történelmi Magyarország) földrajzi középpontja, amelyet emlékmű jelöl a holt-Körös partján. A szomszédos települések: észak felől Mezőtúr, északkelet felől Gyomaendrőd, kelet felől Örménykút, délkelet felől Kardos és Csabacsűd, dél felől Eperjes, délnyugat felől Szentes, nyugat felől pedig Békésszentandrás.'),
    ('Szarvasgede', 'Gyöngyöstől északnyugatra, Balassagyarmattól délkeletre, Sziráktól keletre, Salgótarjántól délre, Kisbágyon, Csécse, Jobbágyi és Apc között fekvő település. A falu Jobbágyi felőli (keleti) végén pedig a 2128-as út ágazik Csécse-Kozárd felé. Szarvasgede a Csór nemzetség ősi birtoka volt, de e nemzetség tagjain kívül ugyanakkor más birtokosai is voltak. 1313-ban Csór Péter és Vágút János birtoka volt. 1326-ban I.'),
    ('Szarvaskend', 'A falu neve a 10. századi Kond vezér szálláshelyének emlékét őrzi, Kond nemzetségének totemállata ugyanis a szarvas volt. A Kemeneshát és a Vasi-Hegyhát (Őrség) találkozásánál, Körmendtől 6 kilométerre délkeletre fekszik. A szomszédos falvak: nyugaton 1,5 kilométerre Nagymizdó, keleten 2,5 kilométerre Döbörhegy és északkeleten 2,9 kilométerre Döröske.'),
    ('Szarvaskő', 'Magyarország egyik legszebb fekvésű települése. Szarvaskő Egertől 11 kilométer-re északra, Szilvásváradtól 17 kilométer távolságra délre fekszik, a Déli-Bükk nyugati pereme alatt elterülő völgykatlanban, az Eger-patak mentén. A kivételes szépségét a földrajzi adottságainak köszönheti. A közvetlenül határos települések: észak felől Mónosbél, északkelet felől Bélapátfalva, délkelet felől Eger, délnyugat felől Egerbakta, nyugat felől Bátor, északnyugat felől pedig Egerbocs.'),
    ('Szatmárcseke', 'Szomszédai a határ magyar oldalán: kelet felől Tiszakóród, délkelet felől Kölcse, dél felől Túristvándi, délnyugat felől Kömörő, nyugat felől Nagyar, északnyugat felől (a Tisza túlpartján) pedig Tarpa. Észak felől a kárpátaljai Badalóhoz (Бадалово), északkelet felől Haláborhoz (Галабор) tartozó területek határolják. A környék fontosabb települései közül Tiszabecs 18, Tiszacsécse pedig 11 kilométerre, a környék városai közül Vásárosnamény 29, Fehérgyarmat pedig 17 kilométer távolságra található.'),
    ('Szatta', 'A fő közlekedési útvonalak elkerülik, bár amióta a Szatta-Kerkafalva közötti egykori földutat szilárd burkolattal látták el, kisebb átmenő forgalom is zajlik a falun keresztül. A községet az Őrségre jellemző rétek, erdők ölelik körül. Az erdőkre leginkább jellemző a tölgy és az erdeifenyő. Az utóbbi évtizedekben nagy területeken lucfenyvest is telepítettek.'),
    ('Szatymaz', 'Szegedtől 12 kilométerre északnyugatra, a Szegedi Fehér-tó szomszédságában helyezkedik el. További szomszédai: észak felől Balástya, kelet felől Sándorfalva, nyugat felől Zsombó, északnyugat felől pedig Forráskút. Érinti még a község területét az 5423-as, az 5425-ös és az utóbbit Jánosszállással összekapcsoló 54 323-as út, déli határszélét pedig az 5428-as út is.'),
    ('Szava', 'Siklóstól északnyugatra helyezkedik el. A szomszédos települések: észak felől Szőke, északkelet felől Garé, kelet felől Csarnóta, dél felől Márfa és Diósviszló, nyugat felől Babarcszőlős, északnyugat felől pedig Ócsárd. A Drávaszög északnyugati végpontja. A vonalnak egy megállási pontja volt itt, Szava megállóhely. Szava és környéke ősidők óta lakott település.'),
    ('Szebény', 'Szebény a Baranyai-dombság keleti peremén található, ezen belül is a Geresdi-dombság egyik települése. A szomszédos települések: északkelet felől Véménd, kelet felől Palotabozsok, dél felől Görcsönydoboka, dél-délnyugat felől Szűr, északnyugat felől pedig Feked. A két legközelebbi város a 21 kilométerre fekvő Mohács és a 24 kilométerre lévő Bátaszék.'),
    ('Szederkény', 'A település a Karasica-patak jobb és bal partjára, egy völgybe épült. Változatos domborzata nagy hatással van a helyi éghajlatra. A falu főként szubmediterrán klímahatás alatt áll, a Földközi-tenger felől érkező enyhe, páradús légtömegek, valamint a Mecsek védő övezetének hatása miatt jellemzően enyhék a telek, koraiak a tavaszok, melegek a nyarak és hosszúak az itteni őszök.'),
    ('Szedres', 'Szekszárdtól 15 kilométerre északra, Pakstól 20 kilométerre délnyugatra fekszik. Több, a központjától kisebb-nagyobb mértékben elkülönülő településrésze van, mint például Apátipuszta, a központtól mintegy 1 kilométerre keletre, vagy Kajmádpuszta, a déli széle közelében. A közvetlenül határos települések: észak felől Tengelic, délkelet felől Fácánkert és Tolna, dél felől Szekszárd, délnyugat felől Sióagárd, nyugat felől pedig Medina.'),
    ('Szeged', 'Területe az újkőkor óta lakott, a rómaiak Partiscum néven alapították. A honfoglalás után a 10. században magyarok telepedtek le itt, és 1183-ban már a sószállítás központjaként említik. A 13. században kereskedelmi központtá vált, 1498-ban pedig szabad királyi város lett. A török uralom (1526–1686) után Szeged 1719-ben visszanyerte rangját. Az 1879-es árvíz szinte teljesen elpusztította, viszont nemzetközi segítséggel újjáépült, kialakítva mai városképét.'),
    ('Szegerdő', 'A közvetlenül határos települések: észak felől Tikos, északkelet felől Hollád, délkelet felől Somogysámson, délnyugat felől Sávoly, nyugat felől Főnyed, északnyugat felől pedig Vörs. Központja közúton csak a főúttól idáig húzódó 75 105-ös számú mellékúton érhető el. Szegerdő Magyarország egyik legfiatalabb települése. A Kéthelyhez tartozó Szegerdőtelep csak 1925-ben jött létre, amikor a sáripusztai Hunyady család itteni birtokain, egy erdőirtáson adott házhelyeket és egy–másfél hektár területű földeket cselédeinek.'),
    ('Szeghalom', 'A 15. század végén mezőváros volt, majd elnéptelenedett. 1711 óta folyamatosan lakott település, 1984 óta város. A Berettyó jobb partján fekszik, innen már csak pár kilométer, ahol a gyönyörű ártéri erdők kíséretében a Sebes-Körös és a Berettyó összefolyik. Ha pedig a folyóknak hátat fordítunk, az Alföld "tengersík" vidékét látjuk. A folyók szabályozásakor levágott kanyarulatok szép kirándulóhelyek és kedvelt horgászparadicsomok.'),
    ('Szegi', 'A Bodrog jobb partján fekszik, nem messze a folyó tiszai betorkollásától, a tokaji borvidéken. Lényegében csak két települési szomszédja van: észak-északkelet felől Szegilong, dél felől pedig Bodrogkisfalud. Külterületei a keleti határszélén, a Bodrogközben érintkeznek még Olaszliszka határszélével is. Ekkor önálló községgé alakult, ideiglenes neve Pusztaszeg lett, majd…'),
    ('Szegilong', 'A Bodrog folyó közelében, a folyó jobb parti oldalán fekszik, a tokaji borvidéken. A szomszédos települések: északkelet felől Olaszliszka, dél felől Szegi, északnyugat felől pedig Erdőbénye. Az előbbiek mellett nyugaton a határszéle egy rövid szakaszon érintkezik még az amúgy távolabb fekvő Bodrogkisfalud lakatlan külterületeivel is.'),
    ('Szegvár', 'A megye második legnagyobb községe. A Kurca és a Kórógy-ér találkozásánál fekszik. A legközelebbi települések a tőle délre található Mindszent (7 kilométer) és a tőle északra fekvő Szentes (8 kilométer) A megyeszékhelytől, Szegedtől légvonalban 35–40 kilométer-re fekszik.'),
    ('Szekszárd', 'Az ország legkevesebb lakosú, Tatabánya és Eger után a harmadik legkisebb területű megyeszékhelye. Területi kiterjedés szempontjából még a megyén belül is csak a negyedik helyen áll (Paks, Tamási és Dunaföldvár mögött). Borváros, kb. 4500 pincével. A Dél-Dunántúl egyik legjelentősebb városa, gazdag történelmi múltjával és különleges kulturális örökségével emelkedik ki a magyar városok sorából.'),
    ('Szeleste', 'A Gyöngyös-sík északkeleti peremén, a Kőris-patak közelében, Ölbő és Pósfa falvak szomszédságában fekszik, dombokkal határolt régen egyutcás falu. Sárvár felől a 8446-os úton közelíthető meg. Felsőszeleste főutcája országos közútként a 86 115-ös útszámozást viseli. A település első okleveles említése 1247-ből származik. Ekkor még két különálló falu volt, melyeket kezdetben Magyarszeleste és Németszeleste, majd a…'),
    ('Szelevény', 'Már az őskorban is lakott volt. A település többször teljesen kihalt, elöntötte már a Körös is, de a mai napig – a lehetőségeihez mérten – fejlődik a falu. Közlekedési szempontból kedvezőtlen földrajzi fekvése miatt nincs átmenő forgalom, turisták sem fordulnak jelentős számban, de rengeteg a „rejtett kincs” amely a település hírnevét öregbíthetné, például a horgászatot kedvelőknek a Körös holtágai, vagy maga a Körös.'),
    ('Szellő', 'Pécsváradtól délre fekszik, a Karasica-patak mellett. A szomszédos települések: észak felől Erzsébet, északkelet felől Kékesd, kelet felől Maráza, délkelet felől Liptód, dél felől Máriakéménd, délnyugat felől pedig Kátoly. Csak közúton közelíthető meg, a Szederkény és Pécsvárad közt húzódó 5608-as úton. Szellő és környéke már a honfoglalás előtt lakott hely volt, ezt igazolják a falu területén talált avar korból származó leletek is.'),
    ('Szemely', 'A Pécshez közeli település történeti régmúltja roppant változatos. A Szemelyi-patak a település közelében, attól keletre folyik. A megyeszékhelytől, Pécstől mintegy 10 kilométerre dél-délkeleti irányban fekszik. Különálló településrésze Szentkútpuszta, központjától mintegy 3,5 kilométerre északra helyezkedik el. A szomszédos települések: észak felől Nagykozár, északkelet felől Magyarsarlós, kelet felől Lothárd, délnyugat felől Egerág, északnyugat felől pedig Kozármisleny.'),
    ('Szemenye', 'A Kemenesháton található. Irtásfalu jellegéből adódóan határának két fő meghatározója az ökológiailag értékes Farkas-erdő, és a hangulatos szőlőhegy. A vasvári káptalan birtokaként először 1217-ben említik az oklevelekben, de határában a rómaikorból is kerültek elő emlékek. Neve a szomszédságában a 10. században már meglévő (Kaán) vezéri szálláshoz tartozó segédnép települését jelenti.'),
    ('Szemere', 'Közigazgatási határának több mint 5 kilométernyi szakasza egybeesik az államhatárral. A közvetlenül határos települések a határ magyar oldalán: kelet felől Pusztaradvány, dél felől Fulókércs, délnyugat felől Litka, nyugat felől Büttös, északnyugat felől pedig Kány. A határ túloldalán a legközelebbi település a közigazgatásilag Perény-Hímhez (Perín-Chym) tartozó Felsőlánc (Vyšný Lánec).'),
    ('Szendehely', 'Budapesttől 45, Váctól 11, Rétságtól 10 kilométerre fekszik. Különálló belterületei: Katalinpuszta és a Szarvasrét-lakópark. Külterületi településrészei közül említést érdemelhet Erdészlak. Németek alapították a községet. A váci püspökség ősi birtoka volt a környék, amit valószínűleg még Szent István adományozott az egyháznak. A környék neve valaha Szenthely volt – bizonyára a földbirtokos püspökség után – ami az idők során Szendehelyre módosult.'),
    ('Szendrő', 'A Bódva völgyében fekszik, túlnyomórészt annak keleti, bal partján, kisebb részben a jobb parti oldalon, a megyeszékhely Miskolctól mintegy 40 kilométerre északra. Különálló településrésze Csehipuszta, a közigazgatási területének északkeleti részén. A közvetlenül határos települések: észak felől Szalonna, északkelet felől Meszes, kelet felől Galvács, délkelet felől Abod, dél felől Szendrőlád, délnyugat felől Edelény, Izsófalva és Ormosbánya, nyugat felől Szuhogy és Alsótelekes, északnyugat felől pedig Varbóc és Perkupa.'),
    ('Szendrőlád', 'A Bódva völgyében, Edelénytől 6 kilométerre északra, Szendrőtől 8 kilométerre délre fekszik. Szendrőlád első írásos emlékei a 13. századból erednek. A község elnevezése az idők folyamán sokat változott. Eredeti neve Lád volt, amelyet vagy Szent László nevéről, vagy a Laad nemzetségről nyert. Birtokos családja Ládinak nevezte magát, éppúgy, mint Sajólád birtokosai.'),
    ('Szenna', 'A Volánbusz ózdi 7-es járata jár ide. Kialakulása az Ózdi Vasgyár szénigényének köszönhető. Korábban Urajhoz tartozott, de mivel összeköttetése Ózddal jobb volt, ezért 1909. november 11-én átcsatolták oda. (Maga Uraj 1978-ban lett a város része.) A bányászat az összes környékbeli bányához hasonlóan itt is megszűnt.[mikor?] Gyalay Mihály: Magyar igazgatástörténeti helységnévlexikon'),
    ('Szenta', 'Belső-Somogy déli részén fekszik, Csurgó keleti szomszédságában, a várostól 7 kilométerre. A további, közvetlenül határos települések: észak felől Kaszó, kelet felől Bolhás, délkelet felől Tarany, dél felől Berzence, északnyugat felől pedig Somogycsicsó. Csak kevés híja van annak, hogy nem határos dél-délkelet felől még Somogyudvarhellyel is. Mindkettő csak alsóbbrendű, önkormányzati utakon közelíthető meg.'),
    ('Szentantalfa', 'A település a Csicsói-medencében, más néven Nivegy-völgyben található, ez utóbbi elnevezés Szentantalfa középkori nevéből ered. A völgy szerkezetileg a Balaton-felvidék Balatonfüred és Badacsony közti szakaszára jellemző, a tóparti hegysor mögött kialakult márgás kőzetű medencék egyikének tekinthető. Első alkalommal a falu neve egy 1276-ban kiadott oklevélben szerepel.'),
    ('Szentbalázs', 'A közvetlenül határos települések: északkelet felől Kaposhomok, kelet felől Kaposkeresztúr, dél-délkelet felől Hajmás, délnyugat felől Cserénfa, északnyugat felől pedig Sántos. Észak felől nagyon kevés híja van annak, hogy nem határos még Taszárral is, délkelet felől pedig Gödre a legközelebbi település, de közigazgatási területe utóbbiak egyikével sem érintkezik.'),
    ('Szentborbás', 'Délnyugati határszéle több kilométeres hosszan egybeesik a magyar-horvát államhatárral is. Külterületeinek jelentős hányada a Duna–Dráva Nemzeti Park része. A határ magyar oldalán csak három települési szomszédja van: északnyugat felől Tótújfalu, északkelet felől Lakócsa, délkelet felől pedig Felsőszentmárton. A határ túloldalán a két legközelebbi település a horvátországi Budakóc (Budakovac) és Detkovac (Detkovac).'),
    ('Szentbékkálla', 'Közelében található a híres kőtenger is. A település elhelyezkedéséből nem csupán a különleges panoráma és sok természeti látnivaló adódik, hanem olyan viszonylagos éghajlati védettség is, melynek következtében évente mintegy kétezer órányit süt a nap. Viszonylag kis kiterjedésű határa körben erdős, dombos és csak dél felé nyitott, azonban ez utóbbi nagy része mocsaras.'),
    ('Szentdomonkos', 'Pétervásárától 12 kilométerre, Egertől 28 kilométer távolságra helyezkedik el. A falu ideiglenesen tényleges zsáktelepüléssé vált 2022. december elsejétől, mert a 25-ös főutat útépítés miatt lezárták a falu és a bekölcei elágazás között várhatóan 2025-ig. Jelenleg csak Tarnaleleszen át Egercsehi felől, illetve a 23-as főúton Bátonyterenye és Pétervására felől közelíthető meg autóval.'),
    ('Szentdénes', 'A falu neve 1949 előtt Szentdienes volt. Szigetvártól délkeletre, a legközelebbi várostól, Szentlőrinctől mintegy 9 kilométerre délnyugatra található. A szomszédos települések: északkelet felől Kacsóta, kelet felől Királyegyháza, dél felől Sumony, nyugat felől Rózsafa, északnyugat felől pedig Nagypeterd. Szentdienes (S.Dionysiusm Teleki) nevét az oklevelek 1287-ben Telwky néven említették.'),
    ('Szente', 'A Cserhátban található a Balassagyarmati-medence déli részén a 348 méter magas Cserhát csúcs alatt. A legközelebbi települések: Debercsény, Kétbodony. Vasúttal: Keleti pályaudvar-Magyarnándor, innen 5 kilométer gyalogosan Debercsényen át a település. A rétsági átszállások szervezése igen rossz, csak a buszsofőr jóindulatán múlik a csatlakozás elérése, illetve egy esetben nem lehet elérni.'),
    ('Szentegát', 'Szinte minden irányból nagy kiterjedésű, csatornákkal szabdalt mezőgazdasági területek határolják, Dencsházát kivéve minden környező lakott hely (Sumony, Okorág, Marócsa, Endrőc, Bürüs) légvonalban jelentős, átlagban is legalább 5 kilométeres távolságban fekszik a település központjától. Nyugati határában terebélyes erdőség található, amely természetvédelmi oltalom alatt áll (Szentegáti-erdő Természetvédelmi Terület).'),
    ('Szentendre', 'Elsősorban művészetével és kultúrájával ragadja magával a látogatókat. Szentendre a Dunakanyar kapujában, a Visegrádi-hegység és a Szentendrei-Duna találkozásánál, a Szentendrei-szigettel szemben, gyönyörű természeti környezetben található. Kedvelt kirándulóhely. A város az 1870-es évekig kisváros volt, alig érte el a négyezer fős lakosságszámot. Az akkori város lakóterülete ma mindössze két városrészt foglal magában, a Belvárost és a Szamárhegyet, bár ez utóbbi is csak a 20. század elején lett lakóterület.'),
    ('Szentes', 'Belterületét az egykor folyónak számító, ma már inkább csak csatornának tekinthető Kurca szeli ketté. Közigazgatási területe ugyanakkor messze északra felnyúlik, így a tiszai torkolata előtti, nagyjából 8-10 kilométeres szakaszán érinti a határát a Hármas-Körös is.'),
    ('Szentgotthárd', 'Szentgotthárd a legnyugatabbra fekvő város Magyarországon helyezkedik el. Az Alpok keleti nyúlványainak közelsége miatt a klímája szubalpin jellegű. Jelenleg Szentgotthárd a magyarországi szlovén nemzetiség központja. A városban Szlovénia konzulátust működtet. A három nemzet kultúráját, hagyományait és lakóit egyesítő település a magyar–osztrák–szlovén hármas határ közelében helyezkedik el.'),
    ('Szentgyörgyvár', 'Keszthely nyugati vonzáskörzetében helyezkedik el, a város központjától légvonalban 9, Hévíztől 5 kilométerre. Különálló településrészei Alsó- és Felsőmándpuszta, mindkettő a központjától több kilométerre északra helyezkedik el. A közvetlenül határos települések: észak felől Nemesbük, északkelet felől Felsőpáhok, kelet felől Alsópáhok, dél felől Sármellék, délnyugat felől Zalaapáti, nyugat felől Bókaháza, északnyugat felől pedig Zalacsány.'),
    ('Szentgyörgyvölgy', 'A falu felszíni vizeit a Szentgyörgyvölgyi-patak szállítja el. Szomszédos és közeli települések: nyugatra Velemér és Magyarszombatfa, északra Magyarföld, keletre Márokföld és Nemesnép. Déli szomszédja a már Szlovéniához tartozó Kebeleszentmárton (Kobilje). A szereket itt többnyire szegeknek nevezik. Szegei: Cséplak Asszonyfa Kógyár (Kolgyárszeg, Kolgyári fordulat) Kisszeg Tiborszeg Domjánszeg Cilinkó Csekeszer Farkasi (Alsó- és Felsőfarkasi) A mai faluközpont három szeg: Kisszeg, Tiborszeg és Domjánszeg összeépülésével alakult ki.'),
    ('Szentgál', 'Kiterjedésére jellemző, hogy legészakibb és legdélebbi pontjai között a légvonalban mért távolság nagyjából 19 kilométer, s a központját a legészakibb pontjától bő 13 kilométer választja el. Az erdőt, amely a falut teljesen körülvette és szinte elzárta a külvilágtól, a hosszú évszázadok során nagyon megritkították. Innen indul délnyugati irányban a községbe vezető 73 115-ös út, amely 3 kilométer után ér be a központba.'),
    ('Szentgáloskér', 'Kaposvártól északkeletre, Ráksi nyugati szomszédságában helyezkedik el. Központján a 6513-as út húzódik végig, amely Ráksitól indulva Mernye érintésével Somogyjádig húzódik, összekötve a 6505-ös és 6701-es utakat, valamint a 67-es főutat. Az 1536 évi adólajstromban Kery aliter pusztakér alakban fordult elő, de szerepelt az 1582-1583 évi adólajstromban is, és ekkor…'),
    ('Szentimrefalva', 'Sümegtől északra, Devecsertől nyugatra, Pápától délnyugatra, Veszprémgalsa délkeleti szomszédjában fekvő település. Főutcája a Csabrendektől Nemeskeresztúrig húzódó 7325-ös út. Szentimrefalva Árpád-kori település. Nevét az oklevelek először Villa Sarusd illetve Szentimresárosd néven említették, a Szentimrefalva nevét csak 1908-ba kapta, de Szent Imre tiszteletére emelt templomát már 1322-ben említették.'),
    ('Szentistván', 'A matyó népcsoport eredete vitatott: van, aki szerint a palócok rokonai (azokból kiszakadt töredék népcsoport), mások szerint a kabarok vagy a kunok leszármazottai lehetnek. Az Alföld északi részén, a Borsodi-Mezőség kistájon helyezkedik el, a 3-as főúttól és az M3-as autópályától délre, pár kilométerre. A települést keletről a Tardi-ér (régebbi nevén Orosz-ér) érinti.'),
    ('Szentistvánbaksa', 'Szerencstől északnyugatra fekszik, a Hernád mentén. Lakott területe és közigazgatási területének túlnyomó része a folyó bal partján terül el, de mintegy 0,7 négyzetkilométernyi terület tartozik hozzá a jobb parti oldalról is. A szomszédos települések: észak felől Nagykinizs, kelet felől Monok, dél felől Megyaszó, nyugat felől Aszaló, északnyugat felől pedig Halmaj.'),
    ('Szentjakabfa', 'Szentjakabfa a Nivegy-völgyben fekszik Balatoncsicsó és Óbudavár között. A völgy szerkezetileg a Balaton-felvidék Balatonfüred és Badacsony közti szakaszára jellemző, a tóparti hegysor mögött kialakult márgás kőzetű medencék egyikének tekinthető, nevezik Csicsói-medence néven is. Szentjakabfa nevét 1306-ban említette először oklevél, mint a Nivegy-völgyben fekvő települést.'),
    ('Szentkatalin', 'Pécstől északnyugatra, Okorvölgy északi szomszédjában fekvő zsáktelepülés. Szentkatalin és környéke ősidők óta lakott hely lehetett, határában gyakran kerülnek felszínre bronzkori és római korból való leletek. Nevét 1542-ben említik először az oklevelek Zenth Chaterina alakban helyezkedik el. A falu a török időkben is lakott maradt, lakossága azonban nagyon megritkult. 1750-ben német telepesek érkeztek a faluba.'),
    ('Szentkirályszabadja', 'Közigazgatási területének nyugati szélén, már a 73-as főúthoz közel fekszik Meggyespuszta nevű külterületi településrésze. Szentkirályszabadja ősi település, melynek területén és környékén már a újkőkorszak óta megtelepedtek az emberek, melyet az itt talált újkőkorszaki, bronzkori leletek bizonyítanak. Később a Római Birodalom idejéből is kerültek elő kisebb villamaradványok.'),
    ('Szentkozmadombja', 'Zalaegerszegtől 24 kilométerre délnyugatra, Lentitől 31 kilométerre északkeletre fekszik, a Zalai-dombság középső részén húzódó hegyháton. Vizeit a Bécsi- és a Szigeti-patak gyűjti össze. A közvetlenül határos települések: észak felől Zalatárnok, kelet felől Tófej, dél felől Rádiháza (Gutorfölde része), délnyugat felől pedig Gutorfölde. Belterülete azonban csak arról Zalatárnoknál letérve – Gutorfölde felé leágazva – érhető el, a 7545-ös úton.'),
    ('Szentliszló', 'Szentliszló nevét 1336-ban említették először az írásos források Scenthwynchlou formában. 1332-1337 között a pápai tizedjegyzék említette újra Sancti Wencezlai formában. Későbbi névváltozatai: 1443-ban Zenthvizió, 1552-ben Zenthlyzló, 1723-ban pedig Szent Liszló formában fordult elő. A 16. század első felében az alsólendvai Bánffy családnak volt birtoka, valamint Gombos János és Wenthei Gáspár nevéről is említés történt, akik jobbágyportával rendelkeztek a településen.'),
    ('Szentlászló', 'A legközelebbi város a 12 kilométerre fekvő Szigetvár, a megyeszékhely, Pécs 47 kilométer távolságra van a településtől. A közvetlenül határos települések: észak felől Boldogasszonyfa, kelet felől Almamellék, délkelet felől Mozsgó, délnyugat felől Szulimán, nyugat felől pedig Somogyhárságy. Néhány évtizede a 67-es valószínűleg még a falu főutcája is volt egyben, de hosszabb ideje már csak a belterület nyugati szélét érinti.'),
    ('Szentlőrinc', 'Horvátul a város hivatalos neve Selurinac. Több faluban azonban másként nevezték a várost: Selovrenac (szalántai), Selurince (drávakeresztúri), Selurac (szigetvári), Selerenac (drávasztárai). A Pécsi-síkság északi részén elhelyezkedő település Pécstől 20, Szigetvártól 16 kilométerre, a Mecseket a Zselictől elválasztó Bükkösdi-völgy torkolatában, a síkvidéki jellegű Ormánságtól északra fekszik.'),
    ('Szentlőrinckáta', 'Szentlőrinckáta Budapesttől 60 kilométer-re, keletre fekszik Nagykáta és Jászberény közelében. A település határában folyik a községet körbe öleli a Zagyva folyó. Említést érdemel még a falut keresztül szelő Mérges-patak, illetve a falu közelében folyó Ér-pataknak is nevezett Hajta patak. A település területéről származó, valamint a határoló községek gazdag régészeti leletanyagai tanúsítják azt, hogy a honfoglalást megelőzően a kedvező földrajzi viszonyok miatt már éltek itt különböző népek, ám első írott említése 1473-ban volt.'),
    ('Szentmargitfalva', 'Keletről a Körtvélyes-erdő határolja. Területén átfolyik a Szentadorjáni-patak, mely a Mura folyóba ömlik. Magyarország első olajkútja mely 1938-ban épült Budafapuszta határában, érdekessége, hogy a nyers olajat himba nélkül termeli. Béla király gyermeke Margit (Árpád-házi Szent Margit) 1242-ben itt született, a település nevét róla kapta. Onnantól a család a két nemesi…'),
    ('Szentmártonkáta', 'Az Alföld és a Gödöllői-dombság találkozásánál meghúzódó Tápió-vidék települése, Budapest központjától 55 kilométer-re. A közvetlenül határos települések: észak felől Tóalmás, délkelet felől Nagykáta, dél felől Tápióbicske, délnyugat felől Tápióság, nyugat felől pedig Tápiószecső. Szentmártonkáta a Káta nemzetség ősi birtoka volt. Első okleveles említése 1349-ből való.'),
    ('Szentpéterfa', 'Szombathelytől 19 kilométerre délnyugatra, Pornóapátitól 9 kilométerre délre fekszik, a Pinka bal partján, az osztrák-magyar határ mellett. A legközelebbi ausztriai (őrvidéki) település, Monyorókerék (Eberau) mindössze 3 kilométerre van tőle északnyugati irányban. Keleti határában ered a Hideg-kúti-patak. A község területe már a római korban lakott hely volt, mivel határában római sírokat és egyéb emlékeket találtak. 1221-ben Ecclesia S.'),
    ('Szentpéterfölde', 'Szentpéterfölde és környéke tájföldrajzi értelemben a Nyugat-Zalai dombság két kistája, a Dél-Göcseji-dombság és az Észak-Göcseji-dombság határán fekszik, erdőkkel ölelt festői környezetben. A megyeszékhely, Zalaegerszeg valamint Szlovénia egyaránt körülbelül 30-35 kilométerre található, északi illetve nyugati irányban. A szomszédos ország Rédics határátkelőhelyen keresztül közelíthető meg a leggyorsabban helyezkedik el.'),
    ('Szentpéterszeg', 'A Berettyó folyó mentén fekszik, közvetlenül Berettyóújfalu északkeleti szomszédságában. A további szomszédos települések: észak felől Derecske, északkelet felől Konyár, kelet felől Gáborján, dél felől Váncsod, északnyugat felől pedig Tépe. Déli határszélét érinti az M4-es autóút is, de annak a határai között nincs csomópontja, a legközelebbi fel- és lehajtási lehetőségek Berettyóújfalu északi, illetve Gáborján keleti külterületei között érhetők el.'),
    ('Szentpéterúr', 'Különálló településrészei Vörrű, a központjától egy kilométerre nyugatra, illetve Nemesszer, mintegy másfél kilométerre északra helyezkedik el. A közvetlenül határos települések: észak felől Nagykapornak és Tilaj, északkelet felől Zalacsány, kelet felől Gétye, délnyugat felől Zalaapáti, dél felől Pacsa, délnyugat felől Zalaigrice, északnyugat felől pedig Nemesrádó.'),
    ('Szenyér', 'A Marcali-hát déli végén, mellett fekszik, Böhönyétől bő 6 kilométerre észak-északnyugatra. A közvetlenül határos települések: észak felől Gadány, északkelet felől Mesztegnyő, dél-délkelet felől Böhönye, dél felől Nemeskisfalud, nyugat felől Tapsony, északnyugat felől pedig Nagyszakácsi. Közigazgatási területén, központjától jó egy kilométerre délre indul Tapsony-Nagyszakácsi-Somogyzsitfa felé a 6803-as út.'),
    ('Szepetnek', 'A településen polgárőrség működik. Délnyugati irányból a legközelebbi szomszédja a 6 kilométerre fekvő Semjénháza, dél-délkelet felől pedig a hasonló távolságra elterülő (közigazgatásilag Nagykanizsához tartozó) Bajcsa, de utóbbival nincs közúti összeköttetése. Határa igen nagy, zömében sík, kisebb részben dombos. A községen folyik át a Berki-patak.'),
    ('Szeremle', 'A Mohácsi-sziget északi részén fekszik, a Szeremlei-Dunának vagy Sugovicának is nevezett Holt-Duna-ág mellett. A közvetlenül határos települések: észak és kelet felől Baja, dél felől Bátmonostor, délnyugat felől Dunafalva, nyugat felől pedig Báta, a Duna túlpartján helyezkedik el. Már a bronzkorban is éltek itt emberek, ezt ékesen bizonyítja a falu alatt talált bronzkori urnatemető.'),
    ('Szerencs', 'A Zempléni-hegység déli lábánál, a Taktaköz peremén helyezkedik el. A város történelme gazdag és szorosan összefonódik a környék kulturális és gazdasági életével. Szerencs nevezetességei közé tartozik a szerencsi vár, mely a 16. században épült, ma pedig a város egyik jelképének számít. A várkastély nemcsak történelmi, hanem kulturális központként is funkcionál, hiszen múzeumnak és kiállításoknak ad otthont.'),
    ('Szerep', 'Különálló lakott településrésze Hosszúhát, a központtól 3-4 kilométerre nyugatra. Anonymus a Gesta Hungarorum 28. részében említ egy „Lutum Zerep”, vagyis Szerep-mocsár nevű helyet, melyet kapcsolatba hoznak a mai településsel, illetve Szerepmonostorral. A korabeli említések a Szerep megnevezés alatt három, jól elhatárolható dolgot értettek…'),
    ('Szergény', 'Celldömölktől északkeletre, a Marcal mellett, Kemeneshőgyész és Kemenesmagasi között fekvő település. A település és környéke ősidők óta lakott hely volt, amit a falutól nyugatra eső Szergényi-domb őskori leletei is bitonyítanak, de római korból való leletek is előkerültek a környéken. A helység mellett, a Marcal folyón levő révátkelőről egy 1323-ban kelt oklevelében történt említés, majd 1408-ban a falu nevét is említette egy oklevél…'),
    ('Szigetbecse', 'A Csepel-sziget déli részén, a Ráckevei-Duna holtága mellett fekszik, a fővárostól mindössze 48 kilométerre. A szomszédos települések: észak felől Ráckeve, kelet felől Dömsöd, dél felől Makád, nyugat felől pedig Lórév. Szigetbecse nevét 1217-ben említette először oklevél Beche néven helyezkedik el. A település névadója a Becse-Gergely nemzetség volt, akiknek ősei a későbbi III.'),
    ('Szigetcsép', 'Az észak-déli irányban közel 50 kilométeres hosszban elnyúló, de kelet-nyugati irányban itt alig 4-5 kilométer széles Csepel-sziget középső részén, a Ráckevei-Duna és a Duna között terül el, Budapesttől 30 kilométerre. Maga a település a közigazgatási területének keleti részén alakult ki, vagyis a mellékághoz fekszik közelebb, határának nyugati felében, a folyó főága felőli oldalon inkább csak mezőgazdasági területek sorakoznak.'),
    ('Szigethalom', 'A budapesti agglomerációhoz tartozó település, fontos tömegközlekedési csomópont. A Csepel-sziget középső részének felsőbb tájékán és a déli irányban kitáguló Csepeli-síkon, a fővárostól 12 kilométerre helyezkedik el. Kis területen átnyúlik a Ráckevei-Dunán Dunavarsány mellett. Északnyugat-délkeleti fekvésű, kertvárosias jellegű, tipikus úgynevezett sakktábla-szerkezetű település.'),
    ('Szigetmonostor', 'Szigetmonostorhoz tartozik Horány üdülőfalu, valamint a sziget teljes déli része, mintegy 12 kilométernyi észak-déli kiterjedésben. Szentendre és Leányfalu határvidékével, illetve Dunakeszivel forgalmas kompjárat köti össze. Előbbit a 11 307-es (a túlparton pedig a 11 308-as), utóbbit a 11 306-os (a túlparton pedig a 12 301-es) út szolgálja ki. Normál vízállásnál a település személyszállító révjáratokkal Gödről és Szentendre belvárosából is elérhető.'),
    ('Szigetszentmiklós', 'Az agglomeráció részeként az elmúlt évtizedekben dinamikusan fejlődött, mára jelentős lakóhely és gazdasági központtá vált. Földrajzi elhelyezkedése különleges, hiszen a település a Ráckevei-Duna partján fekszik, körülötte számos természeti érték található. A települést északról Budapest XXI. kerülete, keletről a Ráckevei-Duna, délről Szigethalom, nyugatról pedig Halásztelek határolja.'),
    ('Szigetszentmárton', 'A festői, sokszínű kis település története közel 750 éves múltra tekint vissza. Az észak-déli irányban közel 50 kilométeres hosszban elnyúló, de kelet-nyugati irányban itt alig 4 kilométer széles Csepel-sziget középső részén, annak keleti felében helyezkedik el. Kelet felől a Ráckevei-Duna határolja, melynek itteni, bő 5 kilométeres partszakasza mára szinte teljesen beépült.'),
    ('Szigetvár', 'A várost kettészeli az Almás-patak, amely szabályozása előtt gyakorta megáradt, s a környéket mocsaras ártérré változtatta. Barcstól és a horvát államhatártól 31, Pécstől 35, Kaposvártól 40 kilométer távolságra található.'),
    ('Szigetújfalu', 'Az észak-déli irányban közel 50 kilométer hosszan elnyúló, keresztirányban viszont alig néhány kilométer széles Csepel-sziget középső részén, annak a nyugati felében található, a Duna főága mellett. A szomszédos települések: északkelet felől Szigetcsép, kelet felől Szigetszentmárton, dél felől Ráckeve, nyugat felől pedig a folyó túlpartján fekvő Ercsi.'),
    ('Szigliget', 'A Balaton északi partján, Badacsony és Keszthely között fekvő félszigeten, számos vulkanikus dombon terül el a falu. Határában torkollik bele a tóba a Nyirádtól idáig húzódó Kétöles-patak. Májustól szeptemberig menetrend szerinti hajójárattal is elérhető, Badacsony, illetve Keszthely…'),
    ('Szihalom', 'A Rima-patak (más néven Eger-patak) mellett fekszik, sík vidéken, termékeny, kötött talajon. A közvetlenül szomszédos települések: észak felől Ostoros és Novaj, északkelet felől Mezőkövesd, délkelet felől Mezőszemere, dél felől Mezőtárkány, délnyugat felől Füzesabony, északnyugat felől pedig Maklár.'),
    ('Szijártóháza', 'Igazgatási szempontból a rédicsi körjegyzőséghez tartozik. Lakossága kevesebb, mint 50 fő, lakónépesség tekintetében Magyarország huszadik legkisebb települése. Néprajzi szempontból a Göcsejjel határos Hetés területéhez tartozik. Területe elsősorban sík vidék, melyek kisebb lankás kiemelkedések tarkítanak. A szomszédos települések a határ magyar oldalán: északkelet felől Zalaszombatfa, délkelet felől Rédics, nyugat felől pedig Gáborjánháza.'),
    ('Szikszó', 'A közvetlenül határos települések: észak felől Aszaló, kelet és délkelet felől Alsódobsza és Sóstófalva [utóbbi kettő a Hernád túlpartján fekszik, közúti kapcsolatban nem állnak a várossal], dél felől Onga, délnyugat felől Arnót és Sajópálfala, nyugat felől Sajóvámos, északnyugat felől pedig Alsóvadász.'),
    ('Szil', 'Magyarország északnyugati részén, a Kisalföld közepén, szinte pontosan a Rábaköz középpontjában fekszik, Csornától 16 kilométerre délre, közel egyenlő távolságra a Hanság mocsárvilágától és a Rába folyótól. Magyarkeresztúrral és az M86-os autóút ottani csomópontjával a 8605-ös út köti össze. Határszéleit érinti még délen a 8425-ös út, délnyugaton pedig a 8426-os út is.'),
    ('Szilaspogony', 'Cereddel, Zabarral és Istenmezejével mellékutak kötik össze. Döntően a Szilas- és az Ortvány-patak határozza meg a település fekvését. Pár kilométerre a falutól található magasabb hegycsúcs a „Kiskő”, és egy kicsit távolabb - Bárnához közelebb - fekszik a „Nagykő”. Szilaspogony a Novohrad-Nógrád UNESCO Globális Geopark települése. A települést 1405-ben már említi oklevél Pogon alakban írva. 1715-ben 5 és 1720-ban 4 magyar háztartást írtak benne össze. 1770-ben, az úrbéri…'),
    ('Szilsárkány', 'A település a Rábaköz középső részén, Csornától 9 kilométerre délre helyezkedik el. Szomszédai: Pásztori 2 kilométerre északkeletre, Rábacsanak 3 kilométerre délkeletre, Szil 5 kilométerre délre, Sopronnémeti 4 kilométerre nyugatra, Bogyoszló 7 kilométerre északnyugatra, és Csorna 9 kilométerre északra helyezkedik el. A falu szerkezete a közelmúltig útmenti, egyutcás, fésűs beépítésű volt.'),
    ('Szilvágy', 'A Zalaegerszeget Lenti térségével összekötő 7405-ös út mentén fekszik, Pórszombat keleti szomszédságában. Itt ér véget az előbbi útba becsatlakozva, 7 kilométer után a 7415-ös út is. Szilvágy nevét 1343-ban említették először az írásos forrásokban Ozyagh néven, a későbbiekben neve Alsó- és Felsőszilvágyként található. 1773-ban pedig nevét már Szilvágy alakban említették.'),
    ('Szilvás', 'A Mecsek és a Villányi-hegység között fekszik, Pécs déli agglomerációjában. Lakott területe a Szilvási-patak völgye mellett alakult ki, dombos vidéken. A szomszédos települések: észak felől Kökény, kelet felől Szalánta, délkelet felől Bosta, nyugat felől Szőke, északnyugat felől pedig Keszü. A megyeszékhely, Pécs felől az 58-as számú főúton közelíthető meg, amelyről Szalánta északi szélénél kell letérni az 5828-as útra helyezkedik el.'),
    ('Szilvásszentmárton', 'A Zselicben, dombok közt, Kaposvártól délnyugatra, Zselickisfalud nyugati szomszédjában fekvő település. Szilvásszentmárton nevét 1332 és 1337 között említették először a pápai tizedjegyzékben, majd 1496-ban Belchyzentmarton módon írták. 1554-ben a török kincstári adólajstromban is említették nevét Szilvás-Szent-Márton írásmóddal. A településnek az 1910-es adatok szerint 365 lakosa volt.'),
    ('Szilvásvárad', 'A település Lillafüred mellett az egyik legismertebb bükki üdülőhely. A közeli Szalajka-völgy a Bükki Nemzeti Park része, természetvédelmi terület. Szilvásvárad igen régi település. A Bükk hegység környékén már a kőkori ember lakott: az Istállós-kői-barlangban az ásatások 35–40 000 éves leleteket hoztak napvilágra. A vaskorszakban jelentek meg a község területén a szkíták, majd a kelták. 1962-ben szkíta sírokat fedeztek fel egy út építése közben.'),
    ('Szilágy', 'Pécstől keletre, Pécsváradtól délre fekszik. Szilágy a pécsváradi apátság jobbágyfaluja volt. Nevét a pécsváradi apátság alapítólevele 1015-ben már említette Zylag néven. Az 1015-ös alapítólevél szerint I. István király földet és népeket adott Szilágy faluban a monostornak. 1276-ban birtokosai Tanch fia János ispán és rokona, Egyed voltak. A településnek ekkor már temploma is volt.'),
    ('Szin', 'A Jósva patak mentén fekszik, az Aggteleki-karszt délkeleti részén, Aggtelektől 15, Edelénytől 29 kilométerre. Bár alig néhány kilométernyire fekszik a magyar-szlovák országhatártól, közigazgatási területének nincs határszakasza, mert az államhatár magyar oldala az Aggteleki-karsztnak ezen a vidékén részben Aggtelekhez, részben Szögligethez tartozik.'),
    ('Szinpetri', 'Az Aggteleki Nemzeti Park délkeleti határán található, a Jósva patak mentén. Legközelebbi szomszédai Szin 3 kilométerre keletre, Tornakápolna és Varbóc 4 kilométerre dél felé, Jósvafő pedig mintegy 6 kilométerre nyugati irányban helyezkedik el. Közel fekszik a magyar-szlovák országhatárhoz, de azzal nem érintkezik: az Aggteleki-karszt ezen vidékén az államhatár magyar oldala részben Aggtelekhez, részben Szögligethez tartozik.'),
    ('Szirmabesenyő', 'A Miskolc vonzásterületén elhelyezkedő, dinamikusan fejlődő település az utóbbi időben több kulturális és gasztronómiai esemény szervezője és lebonyolítója volt. A Bükk-vidék keleti részén, a Sajó nyugati partja mellett fekszik, a megyeszékhely Miskolctól 4 kilométerre északra. A község és környékének átlagos tengerszint feletti magassága 115-120 méter.'),
    ('Szirák', 'Szirák a Cserhát dombjai között a Bér-patak völgyében, a fővárostól 65-70 kilométerre északkeletre épült. A Novohrad-Nógrád UNESCO Globális Geopark települése. Szirák vidéke az ősidőktől kezdve lakott hely. Ezt bizonyítják a Magyar Nemzeti, illetve a Palóc Múzeumban található kőkorszaki, bronzkori és avar kori leletek. A 19. század végén a régészek egy 69 sírból álló alán temetőt is feltártak itt.'),
    ('Szob', 'A Dunakanyarban, a Duna bal partján, az Ipoly torkolatánál fekszik, közvetlenül a szlovák határ mellett, több szempontból is igen előnyös földrajzi helyen. A közvetlenül határos települések: észak felől Márianosztra, északkelet felől Kóspallag, kelet felől Nagymaros, délkelet felől Zebegény, dél felől a Duna túlpartján fekvő Pilismarót, nyugat felől a már Szlovákiához tartozó Helemba (Chľaba), északnyugat felől pedig Ipolydamásd.'),
    ('Szokolya', 'A Dél-Börzsönyben található. Úgy tartják, a terület a középkori királyok kedvelt vadászhelye, az itteni Vár-hegy tövében fekvő kis tó partja pedig egykor Mátyás király neje, Beatrix királyné fürdőhelye volt. Évszázadok múltán az itteni rétre Sierstoff gróf épített kastélyt, melyben ma kastélyszálló található. Egykor nevezték Szokolya-huta néven is, ugyanis a közeli Vasbánya-hegyen ércbányászat folyt és a kitermelt vasércet ezen a tájon dolgozták fel.'),
    ('Szolnok', 'Itt van továbbá a Tisza egyik legfontosabb átkelőhelye. Elhelyezkedése a Zagyva torkolatánál, a Tisza-parton, az Alföld szívében évszázadok óta fontos kulturális és gazdasági útkereszteződéssé tette. Körülbelül 66 000 lakossal rendelkezik, ezzel pedig Magyarország tizenkettedik legnépesebb települése, továbbá az Észak-Alföld harmadik legnépesebb települése.'),
    ('Szombathely', 'Szombathely a Nyugat-Dunántúl régióban helyezkedik el. Magyarország legrégibb városa, amely colonia – azaz városi rangját, még alapítójától, Claudius római császártól kapta, elsőként Pannoniában, a "nyugat királynőjének" is nevezik. Az ország tizedik, a Dunántúl negyedik és a Nyugat-Dunántúl második legnépesebb települése, a harmadik legsűrűbben lakott megyeszékhely, az Alpokalja legnépesebb települése.'),
    ('Szomolya', 'Az Északi-középhegységben, ezen belül az Egri-Bükkalja déli lábainál helyezkedik el. Mezőkövesdtől 12 kilométerre észak-északnyugatra, Egertől 18 kilométerre keletre fekszik. A Kánya-patak völgyében terül el, a vízfolyás két oldalán. Határának déli felét az Alföldre emlékeztető, sík részek jellemzik, északi fele dombosabb. Területén sok kőzetféleség fellelhető, ezek közül talán a legfontosabb a vulkáni eredetű riolittufa, de van a határában homokbánya és terméskő-bánya is.'),
    ('Szomor', 'A Gerecse hegység és a Zsámbéki-medence között fekszik, Gyermelytől 3, Máriahalomtól 6, Epöltől, Zsámbéktól és Bajnától egyaránt 8-8, Esztergomtól 27, Tatabányától 24 kilométer távolságra. A település és vidéke már ősidők óta lakott helynek számít, környékén szinte minden idetelepedett nép, kultúra nyomára rátaláltak. A községhez tartozó Somodorpuszta helyén az 1800-as években egy majdnem teljes négykerekű római kocsit találtak, amely a Magyar Nemzeti Múzeumba került.'),
    ('Szomód', 'Tata 3, Dunaszentmiklós 5, Neszmély 12 kilométer távolságra található. A körülbelül kétezer lelket számláló Szomód a rézkortól folyamatosan lakott település. Neve a Zomol személynévből alakult d-képzővel. A legjelentősebb ókori kultúra a rómaiaké volt, erről feliratos kövek tanúskodnak. Az akkor Zumuld alakban szereplő községet 1225-ben említik először oklevelek, ekkor II.'),
    ('Szorgalmatos', 'Előbbitől északra, utóbbitól délre helyezkedik el. Budapesttől 220 kilométerre keletre fekszik, míg a megyeszékhelytől, Nyíregyházától 30 kilométerre nyugatra, Tokajtól 16 kilométerre délre, Debrecentől pedig 60 kilométerre északra. A Tisza folyótól mintegy 8 kilométer távolságban helyezkedik el. Közigazgatásilag 2002. október 20-ig Tiszavasvárihoz tartozott.'),
    ('Szorosad', 'Központján a Nagykónyi-Somogyacsa között húzódó, a 61-es főutat a 6505-ös úttal összekötő 6508-as út halad végig. Utóbbiból északi irányban, Kára-Miklósi-Zics-Kapoly felé a 6516-os út ágazik ki. Földrajzilag a Somogy-Tolnai dombsághoz tartozik, a Koppány-völgy északi oldalán emelkedő dombon épült. Közeli városok Tamási és Tab. Délről erdő határolja, a környező falvakkal együtt egységes falusi képet ad.'),
    ('Szuha', 'Budapest felől a település közúton legegyszerűbben az M3-as autópályán, a 21-es és a 23-as főutakon közelíthető meg. A sztrádáról Hatvannál kell letérni, a 21-esről pedig Kisterenyénél kell kelet felé fordulni. Nemti központja után érjük el a Szuhára vezető utat, amely országos közútként a 24 109-es számozást viseli. Első írásos említése 1441-ben, „Zoha” alakban fordult elő.'),
    ('Szuhafő', 'A környező települések a határ magyar oldalán: északkelet felől Aggtelek és Trizs, délkelet felől Zádorfalva (5 kilométer), délnyugat felől pedig Gömörszőlős. A határ túloldalán a legközelebbi település Hubó (Hubovo) és Tornalja (Tornaľa). A legközelebbi városok: Putnok 19 és Kazincbarcika 26 kilométerre helyezkedik el. Szuhafő környékét a 13. században a Miskolc nemzetség birtokolta.'),
    ('Szuhakálló', 'A Borsodi-dombság keleti peremén, a Szuha-patak völgyében fekszik 140 méteres magasságban, Miskolctól 25 kilométerre északra, Kazincbarcikától 5 kilométer távolságra. Egyes források szerint a kallózó, ványoló vízimalomra vezethető vissza a név, amit a kender feldolgozása során használtak. Első írásos említése 1317-ből származik, Carlon, Karlou, Karlo alakban helyezkedik el.'),
    ('Szuhogy', 'Észak felől Alsótelekes (4 kilométer), északnyugat felől Felsőtelekes (5 kilométer), dél felől Ormosbánya (légvonalban 6, közúton 10 kilométer). A legközelebbi városok: kelet felől Szendrő (4 kilométer), nyugat felől pedig Rudabánya (5 kilométer). Szuhogy természeti értékekben változatos. A Rudabányai-hegység és a Bódva-völgy földrajzi kistájak között helyezkedik el.'),
    ('Szulimán', 'Földrajzi értelemben a Zselichez tartozik. Közigazgatási területének nyugati szélét érinti a Somogyapáti-Vásárosbéc közti 66 125-ös út is. A falu neve, a hiedelmekkel ellentétben nem I. Szulejmán oszmán szultánt idézi: eredetileg Szőlőmál volt, ami „szőlővel beültetett hegyoldal”t jelent. A község neve először a 15. század elején fordul elő írásos alakban, Zelewmalként írva.'),
    ('Szulok', 'A megye déli részén fekszik, Barcstól 14 kilométerre északkelet felé. a Lad-Barcs közti 6623-as út mentén. Szulokból autóval kevesebb, mint egy óra alatt el lehet érni Barcsra, Nagyatádra, Kaposvárra, Szigetvárra és Pécsre is. Szulok település neve a III. Béla királytól a székesfehérvári János lovagok részére kiállított megerősítő levélben is szerepelt.'),
    ('Szurdokpüspöki', 'A Mátra hegység lábánál, a Zagyva völgyében fekszik, ott ahol a folyó völgye a hegyek közül kilépve kiszélesedik. Keletről a Mátra nyugati nyúlványa (Muzsla 805 méter, Nagy-Koncsúr 604 méter, Kis-Koncsúr 595 méter, Isten-fa-tető 442 méter), délről a Nagy-hársas (509 méter), nyugatról pedig a Cserhát hegység dombokká szelídülő lankái határolják. Szomszédos települések: Jobbágyi, Pásztó, Gyöngyöspata.'),
    ('Szágy', 'A Zselic baranyai részén, egy észak-déli fekvésű völgyben helyezkedik el. Írásos emlékben először 1554-ből szerepelt Aszágy formában, 1799-ből már a Szagy ismert. Az aszú és az ág szavak összetételéből alakult ki a falumegnevezés. Az előtag értelme száraz, míg az utótagé folyóág. A régészek a Szent István-forrásnál római leletekről, így sírkövekről is tudnak.'),
    ('Szákszend', 'Szákszend Szák és Szend települések egyesülésével jött létre 1984-ben. Okleveles említése: 1281 Zaak, 1326 Zak. 1326-ban a Csák nemzetség birtokolta, s a királynak adományozta. 1541-ben még 6 porta után adózott, de két év múlva elpusztult. A 18. században már az Esterházy-család birtoka. Az uradalomnak halastava, vízimalma, fűrészüzeme volt.'),
    ('Szálka', 'Két völgyben fekszik, a szekszárdi dombvidék déli részén, erdős vidéken. A szomszédos települések: észak-északkelet felől Szekszárd, délkelet felől Alsónána, dél felől Mórágy, délnyugat felől Mőcsény, nyugat felől pedig Grábóc. A környező települések közül Mőcsény 5, Grábóc 6, Bátaapáti 9 kilométerre található, a két legközelebbi város Szekszárd és Bonyhád, mindkettő egyaránt 12-12 kilométerre fekszik.'),
    ('Szántód', 'A part azon részén fekszik, ahol a legszűkebb és legmélyebb a tó. A falu túlnyomórészt a Szántód és Tihany közt közlekedő kompjairól, lenyűgöző kilátásáról a Tihanyi-félszigetre és a Szántódpusztai Turisztikai és Kulturális Központról (amely falumúzeum („skanzen”)) híres. Mindössze 13,4 kilométer-re fekszik Siófoktól, a környék nagyvárosától, 65,8 kilométer-re Somogy megye székhelyétől, Kaposvártól és 117 kilométer-re Budapesttől.'),
    ('Szápár', 'Belterületének déli szélén halad el a Zirc és Mór között húzódó 8216-os út, amelybe itt torkollik bele, 18 kilométer megtétele után, déli irányból, Várpalota felől a 8213-as út. Főutcája a 8213-as út egyenes folytatásaként, de már önkormányzati útként induló, majd a Szapári-ér keresztezése után keletnek forduló Kossuth Lajos utca. Szápár a Szapáry család ősi lakhelye volt.'),
    ('Szár', 'A község Bicske körzetében, a Vértes és a Gerecse hegységek közötti fennsíkon, a Vértes peremvidékén helyezkedik el 22,63 km²-en, jellegzetesen falusias környezetben. Ezen a területen már az őskorban is éltek emberek, később kelták, rómaiak, hunok és régi magyarok, ahogy azt a temetkezési helyek tanúsítják. A megyer törzs szálláshelyéhez tartozott.'),
    ('Szárazd', 'A település a Tolnai-Hegyháton, két domb között helyezkedik el. Közelében folyik a Kapos, amelybe innen nem messze folyik bele a Koppány. Zsákfalunak tekinthető, közúton ugyanis csak a 63 122-es számú mellékúton érhető el, amely a 6313-as útból ágazik ki Gyönk északi határában, Gerenyáspuszta külterületi településrész mellett. Vonattal elérhető a Budapest–Pécs-vasútvonalon, amelynek egy megállási pontja van itt, Szárazd megállóhely.'),
    ('Szárföld', 'Magyarország északnyugati részén, Győrtől és Soprontól is mintegy 45-45 kilométerre helyezkedik el, Csorna és Kapuvár között nagyjából félúton. Előbbitől 9, utóbbitól 7 kilométerre helyezkedik el. A falu nevének eredetét a hagyomány eltérően magyarázza.'),
    ('Szárliget', 'Vonattal és busszal Tatabánya, Bicske és Budapest is elérhető közelségben van. E térség ősidők óta lakott, kelták, rómaiak, hunok éltek ezen a helyen. Az 1900-as évek elején a település mai területét felparcellázták és rokkant-nyugdíjasoknak, tisztviselőknek értékesítették.'),
    ('Szárász', 'Szárász nevét az oklevelek 1332-1337 között említették először egy adóösszeírásban. Ekkor a tolnai főesperességhez tartozott és Szárászt is a templomos falvak között sorolták fel. 1382-ben nevét Zaraz alakban írták. A török időkben Szárász is lakott maradt, nem néptelenedett el teljesen, neve sem szerepelt az elnéptelenedett falvak között, tehát valószínűleg 1688-1703 között, a felszabadító harcok során, vagy azt követően fogyatkozott meg lakossága.'),
    ('Szászberek', 'Korábban Alsó- és Felsőszászberek néven Besenyszög külterülete volt. A közvetlen szomszédos települések: észak felől Jászalsószentgyörgy, északkelet felől Jászladány, kelet felől Besenyszög, dél felől Zagyvarékas, délnyugat felől Újszász, északnyugat felől pedig Jászboldogháza. Az autóbuszközlekedés szolgáltatója a Volánbusz, melynek a Szolnok-Jászberény útvonalon közlekedő járatai e települést is kiszolgálja.'),
    ('Szászfa', 'Encstől 25 kilométer távolságra fekszik, a Cserehát nyugati részén, a Rakaca-patak völgyében, a Szalonna és Krasznokvajda között húzódó 2613-as út mentén. Semmi köze sincs a Magyarországra beöltözött németek szász nevéhez, sem a ’fa’ utótagnak a ’falu’ szó sok helynévben megfigyelhető rövidüléséhez. A 13. században nem telepedtek le itt szászok, nem volt szász birtokosa sem.'),
    ('Szászvár', 'Földrajzilag a Baranyai-hegyhát része a Mecsek keleti lábánál, a Völgységi-patak mellett. A település környéke már a kőkorszakban is lakott volt, de első írásos említésével csak a 13. század első felében keletkezett oklevelekben találkozunk. A községről a középkori dokumentumokban először Zaas, Zaz vagy Zaass (1334-es pápai tizedjegyzék) alakban írva olvashatunk, majd egy 1393-ban keletkezett oklevél már Szászt mint a pécsi püspöki birtok egyik hűbéres faluját, illetve annak plébánosát „Mihály szászi plébánost” említi.'),
    ('Szátok', 'A Cserhát nyugati részén, Tereske és Romhány között terül el. A település első ismert okleveles említése 1255-ből maradt fent, ekkor Zatuc néven jegyezték fel a nevét. Az egykori Felső-Szátok a 14. században is lakott hely volt. 1383-ban két Szátok helységről is megemlékeznek az oklevelek. 1423-ban Kis-Szátokról van adatunk. A két Szátok közül az egyik a középkorban az esztergomi érsek birtoka volt. 1433-ban Kis-Szátok a Rhédei és a Felsőromhányi családok birtoka volt.'),
    ('Százhalombatta', 'Százhalombatta Budapesttől 27 kilométerre, délnyugati irányban, a Duna folyam nyugati (azaz jobb) partján, a Mezőföld északi csücskében, az Érd–Ercsi-hátságon helyezkedik el. A Benta (Bara)-patak itt torkollik a Dunába. (2009-2011 között került sor a patakmeder rehabilitációjára.) Az első nyomtatott térképi ábrázolása Lázár-deák térképe 1528-ból, ahol a latin Centum colles alakban szerepel.'),
    ('Szécsisziget', 'A falu a Zalai dombság Mura és Zala folyók völgyei által közrefogott területen, a Közép-Zalai dombságon, a Kerka folyó partján helyezkedik el, Lentitől 10 kilométerre, nem messze a szlovén határtól. A Cserta a falu közelében torkollik a Kerkába, amely itt töri át a zalai dombvidék meredek délnyugati nyúlványait a Lenti-Lendvai-hegy között, s köti össze a Lenti-síkságot a Muraközzel.'),
    ('Szécsénke', 'A Cserhát magaslatai közt fekszik. A közvetlenül határos települések: észak felől Kisecset, kelet felől Becske, délkelet felől Nógrádkövesd, délnyugat felől Legénd, északnyugat felől pedig Kétbodony. A legközelebbi város Romhány, mintegy 7,5 kilométerre nyugat-északnyugati irányban helyezkedik el. Csak közúton érhető el, Nógrádkövesd vagy Kétbodony érintésével, a 2116-os úton.'),
    ('Szécsény', 'Balassagyarmat és Salgótarján közt félúton. 1962-től része Pösténypuszta, 1963-tól Benczúrfalva (az egykori Dolány) is. A Novohrad-Nógrád UNESCO Globális Geopark települése. Természeti szépségeivel, történelmi látnivalóival és kulturális hagyományaival a régió fontos szereplője. A középkorban királyi birtok volt, először 1219-ben említik. A környező vidéken jelentős szerepet játszott mint a nemesi családok és az egyházi intézmények központja.'),
    ('Szécsényfelfalu', 'Az Északi-középhegységben, az Észak-Cserhát területén fekszik, Budapesttől mintegy 100, Szécsénytől 7 kilométerre észak-északkeletre, a megyeszékhelytől, Salgótarjántól pedig nagyjából 20 kilométerre nyugat-északnyugatra, a Kő-hegy lábánál. A falut átszeli a Szécsényfelfalui-patak, és a határában folyik a Pilinyi-patak. A Novohrad-Nógrád UNESCO Globális Geopark települése.'),
    ('Székely', 'Északkelet felől a legközelebbi település Berkesz, de közigazgatási területeik nem érintkeznek. Határszélét nyugaton érinti még a 3836-os út is. Neve az egykori székely lakosságú gyepűvédő őrség emlékét őrzi. Az Árpád-kori település neve 1284-ben már említve volt a Zichy okmánytárban őrzött egyik oklevelében Villa Zekul néven. 1316-ból már ismerjük birtokosait is, akik a Hontpázmány nemzetséghez tartozó Bánki Lőkös fiai voltak. 1324 és 1331 között a Balogsemjén nemzetségbeli…'),
    ('Székelyszabar', 'Mohácstól nem messze északnyugatra fekszik. A szomszédos települések: északkelet felől Görcsönydoboka, kelet felől Mohács, dél felől Lánycsók, nyugat felől Kisnyárád, északnyugat felől pedig Himesháza. Az először 1389-ben Zabar néven említett település a törökök kiűzését követően Károly főherceg birtoka lett, ezért akkor Hercegszabar volt a neve. A Szabar helynév alapjául a Sobor személynév szolgált.'),
    ('Székesfehérvár', 'Földrajzi nagytájak találkozásánál fekszik: nagyobb részben az Alföld részét képező Mezőföld északnyugati csücskében, a Sárréten, kisebb részben a Dunántúli-középhegységben, a Velencei-hegységben található, három hegység lábánál, közel a Velencei-tóhoz, a Balatonhoz és Budapesthez. Az egyik leggazdagabb múltú magyar város: a középkori Magyar Királyság egyik fővárosa, királyi székhely és koronázóváros.'),
    ('Székkutas', 'Békésbe esik a legközelebbi város is, a mintegy 12 kilométerre fekvő Orosháza. Hódmezővásárhely, a térség másik nagy városa 18 kilométerre fekszik tőle. Északi szomszédai Nagymágocs és Árpádhalom, kelet felől Orosháza és Kardoskút a határosai, délkeleti szomszédja Békéssámson, dél és nyugat felől hódmezővásárhelyi külterületek övezik, északnyugatról pedig Derekegyházzal határos.'),
    ('Szólád', 'Balatonszárszótól délre 4 kilométerre fekszik. Szőlőtermő területei a Balatonboglári borvidék részét képezik. Szólád neve 1229-ben szerepelt először az oklevelekben, ekkor a székesfehérvári káptalan birtokai között sorolták fel. Nevét 1233-ban említették ismét az oklevelek, ekkor már lelkésze is volt. Később az 1332-1337. évi pápai tizedjegyzékben is előfordult. 1409-ben az elhalt Gordovai Fancs János itteni birtokait említették az oklevelek.'),
    ('Szögliget', 'Miskolctól 60 kilométerre északra helyezkedik el, egy völgykatlanban, a magyar–szlovák határtól 4 kilométerre délre. Belterületét átszeli a környező hegyekben eredő Ménes-patak. A közvetlenül határos települések: északkelet felől Bódvaszilas, kelet felől Bódvarákó, dél-délkelet felől Perkupa, dél-délnyugat felől pedig Szin. Nyugat felől az amúgy messze fekvő Aggtelek külterületeivel határos, északon pedig a határszéle több kilométeres szakaszon egybeesik az országhatárral.'),
    ('Szúcs', 'A Mátra és a Bükk-vidék között, egy kis völgyben található. A közvetlenül határos települések: észak felől Bekölce, kelet felől Egercsehi, délkelet felől Egerbocs, délnyugat felől Fedémes, nyugat felől Tarnalelesz, északnyugat felől pedig Szentdomonkos. Szúcs nevét 1349-ben említette először oklevél, mint Bellyényi Laczk fia István birtokát, aki a birtokot a Bél nemzetségbeli Bökény fia Tamásnak adta zálogba 12 aranyforintért.'),
    ('Szügy', 'Balassagyarmat a környék legfontosabb városa. Más fontosabb, környező települések közül Érsekvadkert 18, Bercel 20, Szécsény 22, Romhány 24, Rétság 28, Salgótarján és Pásztó pedig egyaránt 50-50 kilométer távolságra fekszik innen. Közúton Budapestről Vác érintésével Balassagyarmaton át érhető el a legegyszerűbben, mintegy 80 kilométernyi utazással.'),
    ('Szőc', 'A Bakony Kisalföldre lehúzódó nyúlványán helyezkedik el. Északkeletről Halimba, nyugati irányból Nyirád, míg délkeletről Taliándörögd határolja. Az Ajkát Nyiráddal összekötő 7315-ös úton közelíthető meg. Az út a kis község lakott területének északi peremén halad végig. Területének fele a veszprémi püspökség uradalmához tartozott, másik fele a Dobosi család tulajdona volt.'),
    ('Szőce', 'Központja a főútról Rimány községrészénél letérve érhető el, a 7463-as számú mellékúton, az elágazástól mintegy 3 kilométerre. Az Őrségben elhelyezkedő település első okleveles említése 1286-ból származik. Szőce neve valószínűleg a falu, falucska jelentésű szláv selce szóból ered. A falutól északra vezet az ún. Kerá út (Király út), a Magyarországról Itáliába tartó középkori út.'),
    ('Sződ', 'A Pesti-hordalékkúpsíkság keskeny északi nyúlványa és a Gödöllői-dombság határán helyezkedik el, Budapesttől mintegy 30 kilométerre északra. Az északnyugati irányba eső Sződligettől pedig a Sződ–Rákos-patak választja el. Sződ (Zeud, Zewd, Sceud) neve személynévi eredetű, mely a régi magyar „sző” vagyis fehéres, szőke szóból ered. Sződ és környéke az őskor óta lakott helynek számít.'),
    ('Sződliget', 'A Dunakanyar délkeleti részén, a Vác–Pesti-Duna-völgyben, a váci Duna-ág bal partján helyezkedik el. A keleti határában a Pesti-hordalékkúpsíkság keskeny északi nyúlványa húzódik. Délre tőle Göd, északra Vác városa terül el, a délkeleti irányba eső Sződtől pedig a Sződ–Rákos-patak választja el. A községet az alábbi helyközi autóbuszjáratok érintik: 300, 343, 344, 345, 371 Sződliget nevének első ''sző'' tagja a sző, vagyis fehéres, szőke szóból származik, míg második része a Sződ határában keletkezett ligetes lakóövezetre utal…'),
    ('Szőke', 'Pécs déli agglomerációjában helyezkedik el. Külterületei északi és déli irányban is igen kiterjedtek, így hét településsel is határos. E szomszédos települések: észak felől Keszü, kelet felől Szilvás, délkelet felől Bosta, dél felől Garé, délnyugat felől Szava és Ócsárd, nyugat felől pedig Regenye. Közúti kapcsolata azonban jelenleg csak Szilvással és Regenyével van.'),
    ('Szőkedencs', 'Szőkedencs nevét az 1332–37. évi pápai tizedjegyzék említi először, Dench alakban helyezkedik el. Egy 1444-es oklevélben Budauaridench (olvasd: Budaváridencs) néven szerepel, ekkor ugyanis az óbudai káptalan birtoka. Az 1550. évi adólajstrom Varga-Dencs alakban említi. Ekkor Thorkos Péter, Véssey László és Sallér György a földesura, míg a szomszédos Fazekas-Dencs Nádasdy Tamásé.'),
    ('Szőkéd', 'Pécs délkeleti vonzáskörzetében fekszik, Egerág és Áta szomszédságában. Utóbbi teljesen zsáktelepülésnek tekinthető, de Szőkéd is csak e két település valamelyikén keresztül érhető el. A Baranyai-dombság településén feltárt Baden-péceli és halomsíros kultúrák is bizonyítják: a környék természeti adottságai kedvezőek a megtelepedésre. Alátámasztja ezt a környéken találhatói hat településrom is, amelyek különböző időszakok emlékeit rejtik.'),
    ('Szőlősardó', 'Az Aggteleki-karszt és a Rudabányai-hegység között elnyúló Rét-patak völgyében, a Galyaság közepén, a Vaskapu-hegy északi lábánál, félúton Perkupa és Égerszög között található. 1548 (1549?): Zewlews Ardoo.'),
    ('Szőlősgyörök', 'A település szőlő- és borgazdasági szempontból a Balatonboglári borvidék részét képezi. Szőlősgyörökről 1327-ből maradt fenn az első okleveles adat, ekkor a helység lelkészét említették. Neve az 1332–1337. évi pápai tizedjegyzékben Gereg, Goreg alakokban volt írva. 1465 és 1492 között az Ujlaki család birtokában volt, az 1536. évi adólajstrom szerint pedig már Móré László volt a földesura.'),
    ('Szűcsi', 'A Mátra délnyugati részén fekszik, Gyöngyöstől 14 kilométerre nyugat-északnyugatra. A közvetlenül határos települések: északkelet felől Gyöngyöspata, délkelet felől Nagyréde, dél felől Ecséd, délnyugat felől Rózsaszentmárton, északnyugat felől pedig Jobbágyi. A település határában késő bronzkori szórványleletek és honfoglalás kori régészeti emlékek kerületek elő.'),
    ('Szűr', 'Pécstől keletre fekszik, a Csele-patak mellett. A szomszédos települések: észak felől Feked és Szebény, délkelet felől Görcsönydoboka, dél felől Himesháza, északnyugat felől pedig Geresdlak. Közúti kapcsolata csak Szebénnyel és Himesházával van. A falu nevét csak 1542-ben említette először oklevél. A török időkben ez a falu is elnéptelenedett. Szűr a 18. században német telepesekkel népesült újra helyezkedik el.'),
    ('Ságvár', 'A Dunántúl egyik legrégebben alapított települése, közel kétezer éve lakják a területet. Erdei tanösvényei, hangulatos elhelyezkedése és a Balatonhoz való közelsége miatt a mai napig népszerű hely. Siófoktól légvonalban mindössze 4 kilométer-re délre, Kaposvártól 60 kilométer-re északkeletre, Veszprémtől 30 kilométer-re délkeletre, a Balaton partjától mindössze 10 kilométer-re helyezkedik el.'),
    ('Ságújfalu', 'Ságújfalu a Novohrad-Nógrád UNESCO Globális Geopark települése. A települést az alábbi helyközi autóbuszjáratok érintik:1010, 3072, 3080, 3081, 3082. Ságújfalu mintegy 700 éves múltra tekint vissza. Helyén azonban már évezredekkel ezelőtt is éltek emberek. Bizonyítják ezt a Várhegyen talált őskori urnák, a Bátka legelőn felfedezett bronzkori tárgyak, a késő avar kori sírok, a késő bronzkori régészeti leletek, urnatemetők nyomai.'),
    ('Sály', 'A Bükk-vidék, azon belül a Miskolci-Bükkalja kistájon, a Sályi-patak völgyében, a 3-as főúttól 6 kilométerre fekszik. Csak közúton érhető el, Bükkábrány felől a 3-as főútból kiágazó 25 115-ös számú mellékúton. Sály és környéke a bronzkor óta lakott vidék. A falu nevét először 1348-ban említették oklevelek. A környező domb- és hegytetőkön máig egykori romok, föld- és kőépítmények maradványai látszanak, vagy sejthetőek.'),
    ('Sámod', 'Sámod kis ormánsági zsákfalu, lényegében egyutcás település, Vajszlótól néhány kilométerre keletre helyezkedik el. Legközelebbi szomszédai nyugatról Baranyahídvég, kelet felől pedig Adorjás. Déli és északi irányból jobbára lakatlan mezőgazdasági területek határolják. Az Árpád-kori település nevét 1244-ben említették először az oklevelek Samud néven helyezkedik el.'),
    ('Sámsonháza', 'Salgótarjántól délnyugatra, Bátonyterenyétől nyugatra fekvő település, Tar és Nagybárkány között, a Cserhát keleti szélén. A Novohrad-Nógrád UNESCO Globális Geopark települése. A község a folyó két partján terül el, itt ömlik bele nyugat felől az ún. Meleg víz-forrás-ból táplálkozó patak.[1] A falu nevét a 12. századi névadási szokásoknak megfelelően a község egykori birtokos urától vagy annak megegyező nevű leszármazottjáról kapta.'),
    ('Sándorfalva', 'Az 5-ös főútról Szatymaz felől közelíthető meg, a 4525-ös úton helyezkedik el. A település szomszédai délről Szeged, keletről Algyő és Hódmezővásárhely, északról Dóc, nyugatról Szatymaz és Balástya. Keletről 1 kilométer hosszban a Tisza sodorvonala a közigazgatási határ. Sándorfalva Magyarország földrajzi kistájai közül a Dorozsma–Majsai-homokhát és a Dél-Tisza-völgy találkozásánál fekszik.'),
    ('Sántos', 'Valamikor tipikus egy utcás község volt, ma 3 utcája van. A 66-os útra épült a Fő utca, a falu déli végénél erről az utcáról nyílik a kelet-nyugati fekvésű Magyar utca (korábban, a „keresztelése” előtt Csutás utcának csúfolták, mivel az utcát szilárd burkolat nem fedte, a megfelelő közlekedés érdekében kukoricacsutával fedték le). A falu északi végén nyílik az Új utca.'),
    ('Sáp', 'A szomszédos települések: északon Földes, keleten Berettyóújfalu, délen Bihartorda, délnyugaton Bihardancsháza és Nagyrábé, északnyugaton Báránd. Központján a Debrecentől Bihartordáig húzódó 4805-ös út vezet végig, közúton csak ezen érhető el, Földes vagy Bihartorda érintésével. A korabeli oklevelek 1264-ben említik először a falut. A régi forrásokban neve Saap, Saáp alakban fordul elő, egyes térképeken még a XIX. század végén is így szerepel.'),
    ('Sárazsadány', 'Sárospataktól 9 kilométerre délnyugatra fekszik, Vámosújfalu és Bodrogolaszi között, közvetlenül a Bodrog partján. Sárazsadány a Magyar Történelmi borvidék, vagy más néven Tokaj-hegyaljai borvidék része. Sára és Bodrogzsadány egyesítéséből jött létre 1949-ben. Sára (Bodrogsára) nevét 1398-ban említették először oklevélben, ekkor Debreő István-nak és fiainak birtoka volt. 1444-ben a Perényi és a Pálóczy család birtoka volt. 1500-ban Perényi Imre nádoré, aki 1502-ben a terebesi pálosoknak adományozta…'),
    ('Sárbogárd', 'A Dunántúl legnagyobb területű települése. A város mai központjának, Bogárdnak az első említése 1323-ból való, földesura, Bogárdi István besenyő nemes volt. Még a 14. században jelent meg egy másik (szintén besenyő) település, Tinód is, amely ma a város része. Az 1969. július 1-jén Sárszentmiklóssal egyesült település 1970-ben kapott nagyközségi, 1986. január 1-én pedig városi rangot.'),
    ('Sáregres', 'Határában folyik a Sárvíz és a Sárvíz-malomcsatorna, valamint itt terül el az előbbi két vízfolyást mintegy 20 kilométer hosszan kísérő, néhol több kilométer széles sárréti mocsárvilág (illetve az azt magába foglaló Rétszilasi-tavak Természetvédelmi Terület) legdélebbi része is. Székesfehérvár felől közúton legkönnyebben a -as főúton érhető el a település, ez esetben Cecéig kell menni, ott nyugatra fordulni a -es főúton, majd kb. 2 kilométer után északnak fordulni a 6307-es mellékúton.'),
    ('Sárhida', 'A Zalai-dombság területén, a Göcsej tájegységben fekszik, a Felső-Válicka-patak völgyének nyugati oldalán. Mindössze négy településsel határos közvetlenül: északi szomszédja Bocfölde, az északkeleti Csatár, kelet felől Pölöskével szomszédos, dél és nyugat felől pedig Bak községhez tartozó területek határolják. A legközelebbi város a megyeszékhely Zalaegerszeg, körülbelül 10 kilométerre északra helyezkedik el.'),
    ('Sárisáp', 'Esztergom 20, Tokod 9,5, Tát 8, Piliscsaba 16, Nagysáp 10, Bajna 14 kilométer távolságra található. A település nevének Sár előtagja a falu mellett folyó Öreg-patak egykori Sár nevéből származik. A Sáp szó a Bár-Kalán nemzetség ősi birtokának neve volt. A két szó összekapcsolásából alakult ki a település későbbi neve. A település és környéke már a kőkorszak óta lakott hely volt.'),
    ('Sárkeresztúr', 'Domborzati viszonyait tekintve a Sárvíz-völgytől keleti irányban enyhén emelkedő. A lejtőszerű emelkedés egészen a sárosdi határig tart. Itt húzódik az a dombél, amely a sárkeresztúri és a sárosdi határt elválasztja. Ennek a dombélnek a magassága 130-140 méter között váltakozik. A határ legmélyebb pontja 95 méter. A Nádor-csatorna melletti rész eléggé mocsaras, így esős években a földek itt terméketlenek.'),
    ('Sárkeszi', 'A község Székesfehérvártól körülbelül 13 kilométerre, Sárszentmihálytól 3 kilométerre, Nádasdladánytól 5 kilométerre, Szabadbattyántól 9 kilométerre, Csórtól 7 kilométerre, Ősitől 9 kilométerre fekszik. Várpalota körülbelül 18 kilométer, Mór pedig mintegy 30 kilométer távolságra található. Keszi neve az oklevelekben 1274-körül tűnik fel először. A falu nevét ekkor Kesu- ként írták.'),
    ('Sármellék', 'Területén található a Hévíz-Balaton nemzetközi repülőtér. A Balatontól nyugatra, a Kis-Balaton melletti síkságon terül el, de északi részét már érintik a Zalai-dombság keleti nyúlványai is. A közvetlenül határos települések: észak felől Alsópáhok, északkelet felől Keszthely, kelet felől Fenékpuszta (Keszthely része), dél felől Zalavár, délnyugat felől Esztergályhorváti, nyugat felől Zalaapáti, északnyugat felől pedig Szentgyörgyvár.'),
    ('Sárok', 'Mohácstól délre, Villánytól délkeletre helyezkedik el, közvetlenül a horvát határ mellett. A szomszédos települések a határ innenső oldalán: észak felől Bezedek, délnyugat felől Ivándárda, nyugat felől pedig Lippó. Keleti és déli irányból a községhatár egybeesik az államhatárral, arrafelé a legközelebbi szomszédos település a horvátországi Főherceglak (Kneževo).'),
    ('Sárosd', 'Sárosd centrumától 3 kilométerre fekszik, északkeleti irányban Tükröspuszta településrész, melynek lakónépessége 2011-es adatok szerint 54 fő, a lakások száma 19 volt. Ugyancsak különálló településrésze – sőt a középkorban még önálló, egy időben mezővárosi címet is birtokló település – volt Jakabszállás, a központtól körülbelül 2 kilométerre dél-délnyugati irányban.'),
    ('Sárospatak', 'A történelmi forrásokban gyakran Pataknak nevezett város fontos kulturális központ, bájos történelmi település és népszerű turisztikai célpont is egyben. Többek között itt volt a Rákóczi fejedelmek rezidenciája. Bizonytalan források szerint itt születhetett Árpád-házi Szent Erzsébet, bár ennek színhelyét mások Pozsonyba teszik.'),
    ('Sárpilis', 'Közúton, az ország távolabbi részei felől az M6-os autópályán érhető el a legkönnyebben a település, a sztrádáról a bátaszéki csomópontnál, vagy az Őcsény–Decs–Szekszárd dél-leágazásnál lehajtva. A központján azonban csak az 5113-as út halad keresztül, azon érhető el északi szomszédja, Decs felől éppúgy, mint a térséget átszelő 56-os főútról, Várdombnál keletnek fordulva.'),
    ('Sárrétudvari', 'A Nagy-Sárrét központi részén fekszik. Szomszédai: északkelet felől Báránd, kelet felől Biharnagybajom, dél felől Füzesgyarmat, délnyugat felől Kertészsziget, nyugat felől Szerep, északnyugat felől pedig Püspökladány. A régészeti leletek arról tanúskodnak, hogy a község területén már i. e. 5000 évvel is éltek emberek. Itt hagyták jellegzetes temetkezési helyeiket a rézkor végén (i…'),
    ('Sárszentlőrinc', 'A Mezőföldön, a Sió mellett található. Közeli települések északra 10 kilométerre Pálfa, keletre 4 kilométerre Nagydorog, délre 8 kilométerre Kajdacs, délnyugatra 9 kilométerre Udvari, északnyugatra 7 kilométerre Nagyszékely és Kisszékely. Sárszentlőrinc régóta lakott területen fekszik, már az Árpád-korban is plébániai székhely volt. A pap neve 1334 óta ismert: Egidius Sancti Laurentii.'),
    ('Sárszentmihály', 'A megyeszékhelytől, Székesfehérvártól légvonalban körülbelül 5-6 kilométerre található, a Sárvíz-csatorna mentén. Tengerszint feletti magassága 112 méter. A községhez tartozik Sárpentele is, ami zsákfalunak tekinthető: csak a másfél kilométer hosszú 72 103-as úton érhető el, ami a 7201-esből ágazik ki, annak 2+500-as kilométerszelvényénél, észak-északnyugati irányban, a falutól délre eső külterületen.'),
    ('Sárszentágota', 'A környező települések közül Káloz 8, Aba 9, Sárbogárd 13, a megyeszékhely Székesfehérvár és Kőszárhegy egyaránt 26-26, Baracs 29, Alap 33,5, Sukoró 37, Siófok pedig 47 kilométer távolságra található. Mindössze négy közvetlen települési szomszédja van: észak felől Sárkeresztúr, kelet felől Nagylók, dél felől Sárbogárd, nyugat felől pedig Káloz. Közigazgatási területét egy rövid szakaszon érinti a 6305-ös út is, de azzal csak egy önkormányzati fenntartású, alsóbbrendű út kapcsolja össze a település lakott területeit.'),
    ('Sárvár', 'Vendégéjszakák tekintetében Magyarország 12. legnépszerűbb települése (2022-es adat). Sárvár a Rába partján fekszik, a Kemeneshátnál. A megyeszékhelytől, Szombathelytől 24, Soprontól 55, Pápától 42, a Balatontól 60 kilométer-re fekszik. 2016-ban Sárvárt az „Európai Reformáció Városa” tiszteletbeli címmel tüntette ki az Európai Evangélikus Egyházak Közössége.'),
    ('Sáránd', 'A község Debrecen városkörnyéki településeinek körébe tartozik. Debrecen távolsága (13 kilométer) meghatározta és ma is befolyásolja a település életének alakulását. A közlekedési kapcsolatai jók, a kis távolság, megfelelő járatsűrűségű tömegközlekedési hálózat lehetővé tette a Debrecennel való széles körű kapcsolatot. A szomszédos települések: észak felől Mikepércs, kelet felől Hajdúbagos, dél felől Derecske, nyugat felől pedig Hajdúszoboszló.'),
    ('Sáta', 'A megye nyugati részén található, Ózdtól mintegy 15 kilométerre délkelet felé. Az Upponyi-hegység nyugati peremén helyezkedik el, a Csernely-patak mellékvölgyében, környezetében jelentős erdővel. A közvetlen szomszédos települések: észak felől Borsodbóta, délkelet felől Nekézseny, délnyugat felől Csokvaomány, nyugat felől Farkaslyuk, északnyugat felől pedig Ózd.'),
    ('Sátoraljaújhely', 'Sátoraljaújhely híres borvidék, és 2002 óta a Tokaj-hegyaljai történelmi borvidék kultúrtáj részeként a világörökség része. Sátoraljaújhely városa Észak-Magyarországon, a Zempléni-hegység északkeleti peremén, a szlovák határ közelében helyezkedik el. A város földrajzilag három jelentős tájegység találkozásánál található: a Bodrogköz, a Hegyköz és a Hegyalja „kapujában”.'),
    ('Sátorhely', 'Területe sík, a Duna második terasza. A szomszédos települések: kelet felől Kölked, dél felől Udvar, délnyugat felől Majs, nyugat felől pedig Nagynyárád. Észak felől a legközelebbi település Mohács városa, de közigazgatási területeik (kevés híján) nem érintkeznek. A település elődje valószínűleg Sátorhelytől délre, a Borza-patak mentén állhatott valahol.'),
    ('Sávoly', 'A Marótvölgyi-csatorna hídján áthaladó műút egy kettős kanyarral Sávolyra visz bennünket. A csatornában a víz nagyon lassan halad, mert mostanában új feladatot kapott: nem érheti el a Zala folyót, hanem a Kis-Balaton II. tározójának a bölcsője lesz. A mély, lápos, mocsaras terület, amely a Marcali-háttól nyugatra eső somogyi táj legmélyebb pontja, valaha a Jankó-tó otthona volt, ma azonban sás lepi el, itt-ott egy-egy liget néhány fával.'),
    ('Sé', 'Kis- és Nagy-Sé falvak egyesítésével jött létre. Szombathelytől mintegy 5 kilométerre nyugatra fekszik, az Arany-patak mentén. Lakott területét a vízfolyás két különálló részre osztja, a történelmi faluközpont az Északsé nevet viseli, a jóval kisebb Délsé településrész későbbi kialakulású, ennek megfelelően bővelkedik újabb építésű házakban. Közigazgatási területe érdekes módon közel téglalap alakú, melynek kelet-nyugati irányú kiterjedése alig haladja meg az egy kilométert, ezzel szemben észak-déli irányú kiterjedése nagyjából 5,5 kilométer.'),
    ('Sénye', 'Zsáktelepülés, közúton csak egy bő 2 kilométeres, szőlővel borított dombok között kanyargó bekötőúton közelíthető meg, amely Zalaszentlászló északi határában ágazik ki a 7336-os útról és a 73 201-es számozást viseli. Lőrinte birtokát, majd 1340-ben, a Lőrentei család birtokaként.Később a Báthoryak, a Nádasdyak, Zrínyi Miklós is birtokolta, de a török is megadóztatta, majd a Széchenyi grófoké lett.'),
    ('Sényő', 'Az ország távolabbi részei felől a legegyszerűbben a 4-es, illetve a 403-as főutakon közelíthető meg, nyírturai letéréssel. Sényő neve személynévből ered, azonban csupán a 14. század elejétől fogva említik. 1320-ban bukkant fel először, illetve keletkezett az az oklevél, amelyben Károly Róbert megerősítette a Kállayak egyik ősét birtokjogában, és ekkor említődik először településünk neve.'),
    ('Sérsekszőlős', 'A szomszédos települések: Tab, Lulla, Torvaj, Zala és Bálványos. A mai település területén már a késő avar korban is éltek emberek: erre bizonyítékul az itt megtalált temető szolgál, ahol egy gyermeksír feltárásakor gyöngyök és ékszerek is előkerültek, valamint egy I. Berengár itáliai király idejéből származó pénzérme is. A mai falu két részből keletkezett: az egyik korábban Zala községhez tartozott és Szőllőspusztának hívták.'),
    ('Sóly', 'Egyes feltevések szerint a környéken történt az az ütközet, amely Géza magyar fejedelem halála után eldöntötte az utódlás kérdését István és Koppány között, a mai településen több emlékmű is utal erre a kapcsolatra. A Balaton-felvidéknek a Bakony hegységgel találkozó törésvonalában, Veszprém és Várpalota között félúton, Hajmáskértől délre, a 8-as főúttól déli irányban néhány száz méterre találjuk a szép fekvésű kis települést.'),
    ('Sóshartyán', 'Sóshartyán a Cserhát északi lábánál, Salgótarjántól 15 kilométerre délnyugatra fekvő kistelepülés, a Novohrad-Nógrád UNESCO Globális Geopark települése. . A község középkori eredetű, a terület azonban lényegesen régebbről lakott. Régészeti feltárások során már a neolit korból találtak itt tárgyi emlékeket („parlagi ková”-nak nevezett kis kovapenge), de feltártak egy bronzkori urnatemetőt, továbbá vaskori leletre is bukkantak.'),
    ('Sóskút', 'Az Érd-Sóskúti-fennsík és az Etyeki-dombság találkozásánál helyezkedik el, a Benta-patak völgyében, Biatorbágy és Tárnok között félúton. Határja jeles termésű, vagyonnyai külömbfélék" (Magyar Országnak leírása, 1799). Fényes Elek szerint: "tót falu, Székes Fejér vmegyében, Pest vmegye szélén, 1397 kath. , 8 zsidó lak. Kath. paroch. szentegyházzal. Határa hegyes, erdős.'),
    ('Sóstófalva', 'Sóstófalva Észak-Magyarországon található úgynevezett zsáktelepülés. Az ősfalu a Hernád folyó völgyében terült el, de a gyakori áradások miatt kb. 2 kilométer-re távolabb, a völgyet határoló domb túloldalára települt az 1880-as években. További közeli nagyváros Miskolc. Mindkét várostól egyaránt 21 kilométer-re van. A települést kelet, észak és nyugat irányból összefüggő domb veszi körül, déli irányban a völgy a szomszédos Újcsanálos felé nyitott.'),
    ('Sósvertike', 'Sellyétől néhány kilométerre délre fekszik, az Ormánság délnyugati részén. További szomszédai: délkelet felől Zaláta, délnyugat felől Drávasztára, nyugat felől pedig Drávaiványi. A falu belterülete két nagyobb, egymással nagyjából párhuzamos utcából áll, ezek közül a főutca, helyi nevén a „nagysor” – ahol a református templom és a faluház is áll, és ahova a faluba vezető út is beérkezik – Petőfi Sándor, míg a másik, keskenyebb utca Kossuth Lajos nevét viseli.'),
    ('Sótony', 'Szombathelytől 33 kilométerre, a Rábától 4 kilométerre keletre, Sárvár közvetlen déli szomszédságában található. Az ország távolabbi részei irányából a 8-as vagy a 834-es főutak érintésével közelíthető meg.'),
    ('Söjtör', 'Régi, jellegzetes szalagfalu-szerkezete a 20. század eleje óta mellékutcákkal is bővült. A község keleti oldalán jellegzetes zalai dombvidék húzódik, nyugati oldalán lapályos mezők és legelők találhatók. A közvetlenül határos települések: északkelet felől Pölöske, délkelet felől Hahót, dél felől Pusztamagyaród, délnyugat felől Pusztaszentlászló, nyugat felől Tófej, északnyugat felől pedig Baktüttös és Bak.'),
    ('Söpte', 'A Gyöngyös-sík északnyugati részén, Szombathelytől 6 kilométer-re északkeletre, a Kozár patak mellett fekszik. A szomszédos települések: északkelet felől Vasasszonyfa, kelet felől Salköveskút és Vassurány, dél felől Szombathely, nyugat felől Gencsapáti, északnyugat felől pedig Pusztacsó. Közigazgatási területe észak felől pontszerűen érintkezik még Kőszegpaty déli határszélével is.'),
    ('Söréd', 'A község neve nagy valószínűséggel Sarolt, Géza fejedelem feleségének nevéből származik. Béla aranybullás oklevele, amelyben a település Soruuld néven szerepel. A Soruuld (Sarolt) török eredetű személynév, jelentése fehér menyét. Az írásos emlékek 1152-ben Serold, 1566-ban Sered, 1685-ben Seréth néven említik a falut, amely az utóbbi időpontban elvégzett összeírás szerint ekkor már lakatlan volt.'),
    ('Súr', 'A falu a Súri-patak és a Kőrisberki-ér völgyében és a vízfolyásoktól keletre húzódó halmokon fekszik, egy erdőkkel, legelőkkel, szántókkal övezett festői dombvidék közepén. Távolsága a környék városai közül Mórtól 16, Kisbértől 18, Zirctől pedig 21 kilométer. A településhez tartozik a központtól délnyugatra, 3 kilométerre található Súr-Szőlőhegy. A falu központjától mintegy másfél kilométerre északkeletre, a Fekete-berki vízfolyás völgyében horgásztó található.'),
    ('Sükösd', 'A Dunavölgyi-főcsatorna mellett fekszik, a Dunától mintegy 6 kilométer-re, Bajától 12 kilométer-re észak-északkeleti irányban. A szomszédos települések: északról Dusnok, keletről Nemesnádudvar, délről Érsekcsanád. Az 1521-ben Sykesd írásmóddal említett Ósükösd területén feküdt hajdan az egész falu, a Dunához jóval közelebb, mint most. Mivel a környék mocsaras volt, a kalocsai érsek átköltöztette a falut a magaspartra a 19. században, s így alakult ki a mai falu.'),
    ('Sülysáp', 'Tápiósáp és Tápiósüly egyesülésével jött létre. A Gödöllői-dombság és a Monor–Irsai-dombság határán helyezkedik el, az Alsó-Tápió völgyében, Budapesttől 25 kilométer-re keletre. Szép földrajzi fekvésű környezetben fekszik, területét szelíd dombok és jó termőföldek, halastavak, továbbá az Alsó-Tápió és a Sápi-patak teszik változatossá. Külön néven nevezett településrésze még Szőlősnyaraló, mely a belterület északkeleti részén található, a vasúttól északra.'),
    ('Sümeg', 'Számos történelmi emlék és műemlék található itt. Legismertebbek a sümegi vár, a püspöki palota, Kisfaludy Sándor szülőháza és a határában feltárt őskori kovakőbánya. Sümeg környéke már a bronzkor óta lakott terület. A 19. század végén egy, a Római Birodalom idejéből származó római katonai tábor és több akkori ház maradványait találták meg itt, ezek leletei jelenleg a városi múzeumban találhatók.'),
    ('Sümegcsehi', 'A településen polgárőrség működik. Autóbusszal elsősorban Sümeg és Kisgörbő felől elérhető, de rendszeres összeköttetésben áll Zalaszentgróttal, Zalaegerszeggel és Keszthellyel is. Sümegcsehi első említése 1357-ből való. Birtokosa 1945-ig kizárólag a veszprémi püspökség. A homokos földeken a termelés igen nehézkes volt, a lakosság csak a szűk megélhetését biztosíthatta belőle.'),
    ('Sümegprága', 'Délről lombos erdő, szőlő és gyümölcsös öleli körül, panorámája az Alpok havasait is láttatja. Éghajlata erősen befolyásolt a Kisalföld felől érkező óceáni légtömegek és a Balaton mikroklímájának melegítő hatása által. A község múltjára vonatkozó okmányok, régi iratok és plébániai anyakönyvek az 1748. évi nagy tűzvészben megsemmisültek, így csak néhány szegényes levéltári adat maradt az utókorra helyezkedik el.'),
    ('Süttő', 'Keleti szomszédja a 4 kilométerre fekvő Lábatlan, a nyugati pedig a 6 kilométerre lévő Neszmély, de déli irányban messze kiterjedt külterületei révén határos még az amúgy 9 kilométerre keletre elhelyezkedő Nyergesújfaluval, valamint a több mint 10 kilométerre délre fekvő Héreggel és Tardossal is. Északnyugati és északkeleti szomszédai – Dunamocs (Moča) és Karva (Kravany nad Dunajom) – már a folyó túlsó, szlovákiai partján helyezkednek el.'),
    ('Tab', 'Tab a Külső-Somogy dombvidékének központi települése, a Kis-Koppány partján helyezkedik el. Huszonnégy tartozik a vonzáskörzetéhez. A Balatontól délre, Siófoktól mintegy 25 kilométerre terül el, az északi szélesség 46,7 és a keleti hosszúság 18,0 fokán található. Közigazgatási területéhez három puszta tartozik: Csabapuszta, Gyurgyókapuszta és Ugajpuszta.'),
    ('Tabajd', 'Alcsútdoboz 3,5, Vál 5, Felcsút 9, Kajászó 10, Baracska pedig 14,5 kilométer távolságra található innen. A település és környéke már az ókorban is lakott hely volt, amit az itt talált, római korból származó leletek is bizonyítanak. Szomszéd: Vál, "Vale", jelentése: vízfolyás, patak, völgy, etruszk és Latin nyelven, olaszul is! Az Ókori Római Birodalom, és Nyugat-Római Birodalom idején Tabajd községet valószínűleg "Tebald" néven nevezték, innen ered a későbbi középkori, és jelenkori elnevezés.'),
    ('Tagyon', 'A Balaton-felvidéken, Nagyvázsonytól délre, Zánka és Szentantalfa közt fekvő település. A község területe szerkezetileg még a Balaton-parti "riviérához" tartozik, bár közvetlen tóparti szakasszal a falu határa nem rendelkezik. Itt indul a Balaton-felvidék ezen szakaszára jellemző, a tóparti hegysorba benyúló, márgás felszínű medencék egyike, a négy település (Balatoncsicsó, Óbudavár, Szentantalfa, Szentjakabfa) közigazgatási területére kiterjedő Csicsói-medence.'),
    ('Tahitótfalu', 'A Szentendrei-Duna választja két részre, a szentendrei-szigeti Tótfalura és a Visegrádi-hegység lábánál húzódó Tahira, a kettőt a Szentendrei-szigetre vezető egyetlen közúti híd, a Tildy híd köti össze. A környező településeken előkerült gazdag leletek tanúsága szerint a terület már az őskor óta lakott volt. A rómaiak korában a birodalom határaként a térség nagy jelentőséggel bírt katonai-védelmi szempontból.'),
    ('Taksony', 'Népszerű horgász-, csónakázó- és nyári üdülőhely. A Csepeli-sík és a Pesti-hordalékkúpsíkság határán, a Ráckevei-Duna bal partján, a budapesti agglomeráció dél-pesti részén, a főváros közigazgatási határától mintegy 10 kilométerre délre helyezkedik el. A szomszédos települések: északkelet felől Dunaharaszti, kelet felől Alsónémedi, délkelet felől Bugyi, dél felől Dunavarsány, nyugat felől pedig Szigetszentmiklós.'),
    ('Taktabáj', 'Mai elnevezését 1953-ban kapta, addig egyszerűen Báj volt a neve. A Taktaközben fekszik, a Tisza jobb parti oldalán, a folyótól néhány kilométernyi távolságra északra. A közvetlenül határos települések: észak felől Tarcal, kelet felől Csobaj, nyugat felől pedig Prügy, valamint egy rövid szakaszon érintkezik még a területe a folyó túlsó partján fekvő Tiszadadáéval is.'),
    ('Taktaharkány', 'Neve összetett eredetű: első tagja a déli határában húzódó Takta folyótól ered, míg a Harkány egy ősi, Árpád-kori személynévből származik. A település földesurai a 18. századtól kezdve a zsidó származású Harkányi bárók voltak, egészen a 20. század közepén lezajlott államosításig.'),
    ('Taktakenéz', 'A Tisza jobb partján helyezkedik el, a Taktaközben. A közvetlenül határos települések: észak felől Taktaszada, északkelet felől Prügy, délkelet felől Tiszadada, délnyugat felől Tiszadob (utóbbi kettő a folyó túlparti oldalán található), északnyugat felől pedig Taktaharkány. A 2011-es népszámlálás során a lakosok 91,2%-a magyarnak, 20,7% cigánynak mondta magát (8,8% nem nyilatkozott.'),
    ('Taktaszada', 'Szerencstől dél-délnyugatra, a valamikori Takta folyó, ma már csak csatorna mentén található, a harangodi dombság keleti részén, a tokaji Kopasz-hegytől légvonalban 8,5 kilométerre. A községhez tartozó termőföldek melyek a harangodi oldalon találhatóak nagyon jó minőségűek, a Taktán túliak inkább legelőnek alkalmasak, szárazabb években a gabona szépen terem itt is.'),
    ('Takácsi', 'Pápa városától 8 kilométerre északra fekszik. A legközelebbi települések: északra Gyarmat, keletre pedig Vaszar. Területe nagyobb részt síkság, de vannak dombos részei is. A falun keresztülfolyik a Gerence-patak. Valószínűleg a késő bronzkorban, mintegy 2500-3000 évvel ezelőtt éltek itt emberek.'),
    ('Taliándörögd', 'A Déli-Bakony hegyvidékén, a Kab-hegy és az Agár-tető között helyezkedik el. A közvetlenül határos települések: észak felől Halimba, északkelet felől Öcs, kelet felől Pula, kelet-délkelet felől Vigántpetend, délkelet felől Kapolcs, dél felől Monostorapáti, nyugat felől Sáska, északnyugat felől pedig Szőc. Csak kevés híja van annak, hogy nem határos észak felől még Ajkával, délnyugat felől pedig Hegyesddel is.'),
    ('Tamási', 'A Szent Tamásról elnevezett, hozzávetőlegesen 8000 fős település mindössze 30 kilométerre található délre a Balatontól. A települést − mely 1984 óta visel városi rangot − a római korban alapították, a központban található katolikus templom pedig az ókori templom romjaira épült. Az 1525−1665 közötti időszakban a területet a betörő törökök foglalták el.'),
    ('Tanakajd', 'A Gyöngyös-sík délkeleti részén, a Gyöngyös-patak mellett fekszik, a megyeszékhely Szombathelytől 10 kilométerre délkeletre. A közvetlenül határos települések: észak felől Vép, északkelet felől Bozzai, délkelet felől Vasszécseny, dél felől Sorkifalud, nyugat felől pedig Táplánszentkereszt.'),
    ('Tapolca', 'Tapolca a Balaton-felvidék nyugati szélén, a Tapolcai-medence közepén helyezkedik el. A várost körülölelik a Tapolcai-medence bazalthegyei. Ahol az egykori Pannon-tenger vizéből lerakódott üledékekre szétfolyt a bazalt, megvédte azokat a szél és víz koptató munkájától. Így alakultak ki a térszín egykori magasságát „tanúsító”, kúp vagy koporsó alakú tanúhegyek.'),
    ('Tapsony', 'A 7-es fóútról Holládon letérve ugyanezen az úton érhető el, Nagyszakácsin keresztül. Az autóbuszok főként az iskolához és a munkahelyekhez igazodnak. Tapsony jellegzetesen sugaras szerkezetben épült. A falu központja a Széchenyi tér, innen ágazik szét 6 utcája. A leghosszabb több mint két kilométer. A főtéren található a polgármesteri hivatal, a vegyesbolt, a művelődési ház, a világháborús emlékművek, valamint kissé arrébb a templom is.'),
    ('Tar', 'A Zagyva völgyében fekszik, Pásztó és Mátraverebély között. Keletről a Mátra, nyugatról a Cserhát magaslatai veszik körül. A Novohrad-Nógrád UNESCO Globális Geopark települése. Elérhető vasúton is, a Hatvan–Somoskőújfalu-vonalon helyezkedik el. Vasútállomása közvetlenül a 24 105-ös út mentén található.'),
    ('Tarany', 'Nagyatád délnyugati szomszédságában fekszik, a várostól mintegy 8 kilométerre. A szlovénok (vendek) már a 17. században megtelepedtek itt. A vend nyelvet még jó néhány idős ember beszélte a 21. század elején is, mostanra az utódaik már csak pár szót ismernek az ősi nyelvből. Nevét először a 15. században említették először az oklevelek mint a vránai perjelség birtokát Későbbi földesurai között szerepelt többek között Török Bálint, Zrínyi György, majd Tirunetti Herkules Lajos és a Festetics család.'),
    ('Tarcal', 'Czuczor Gergely és Fogarasi János a település nevének eredetét Turzol, kun fejedelemig, illetve a mongol Turcsighol (kémlelő stb.) kifejezésre vezeti vissza. A Névtelen Jegyző megszólítás e helyen is Anonymusra vonatkozik. „A Névtelen Jegyző szerént Tarczal városa vagyis az ezt északról fedező hegy Turzol kún vezértől vette nevezetét, kit Árpád a föld kikémlése végett küldött, és a föntebbi hegyre legelső lovagolt fel.'),
    ('Tard', 'A település szoros kapcsolatot tart fenn az Alfölddel és a Bükkel, ez a két nagy tájegység határozza meg domborzatát, állatvilágát és növényzetét. Típusa: szalagtelepülés. Néhány kaptárkő és a Tatárdomb a határában van. A Bükki Nemzeti Park peremvidéke. 15 kilométer távolságban két horgásztó és 25 kilométer távolságban a Tisza-tó található. A falu mezőgazdasági művelésre kiváló öntéstalaj, réti talaj, csernozjom, magas humusz- és kalciumtartalommal.'),
    ('Tardona', 'Csak közúton érhető el, Kazincbarcika és Dédestapolcsány felől, mindkét irányból a 25 127-es számú mellékúton. Első írásos említése 1240-ből származik. Legkorábbi ismert birtokosa a Kán nemzetségből származó Gyula bán volt, melyre címerállata az oroszlánra emlékeztet. A Turduna alakban írt nevű település valószínűleg a közeli dédesi vár tartozéka volt.'),
    ('Tardos', 'Tardos a Gerecse-hegység közepén, annak ölelésében fekvő település. Tatabánya 14, Tata 12, Süttő 13,5, Dunaalmás pedig 15 kilométerre található. Legközelebbi szomszédja Vértestolna, amitől alig három kilométer választja el. Első írásos említése 1217-ben történt Turdos alakban helyezkedik el. Egyrészben a Karakó vár faluja volt, melyet Imre király 1204-ben az esztergomi káptalannak adományozott márványfejtésre, de II.'),
    ('Tarhos', 'Természetföldrajzi szempontból a Körös menti sík délkeleti részén, a Kettős-Körös jobb oldalán fekszik. Szomszédai: észak-északkelet felől Vésztő, kelet-délkelet felől Sarkad, dél felől Doboz, nyugat felől Békés, északnyugat felől pedig Bélmegyer. Nagyon kicsi a híja annak, hogy északkeleti irányból ne érintkezzék a határszéle Okány közigazgatási területével is.'),
    ('Tarján', 'A lakosság harmada sváb származású, akik őrzik hagyományaikat. Érinti a települést a Szomortól Gyermelyen át idáig vezető 1123-as és az innen Tatáig húzódó 1128-as út is. Külterületi településrésze a mintegy 4 kilométerre délre található Tornyópuszta. A település és környéke már a rómaiak idején is lakott volt, amit a nagyszámú e korból származó itt talált lelet is bizonyít.'),
    ('Tarjánpuszta', 'A településtől északra helyezkedik el országunk egyik nevezetessége, a Pannonhalmi Bencés Főapátság. A községnél fakad a Pándzsa-ér, mely a Ravazd alatti Béla-kút vízével siet Győr felé a Rábába. Tarjánpuszta címere álló, kék színű, hegyes talpú pajzs. A pajzs alján zöld halmon három természetes színű fenyőfa áll. A pajzs jobb felső sarkában öt vörös szív lebeg, a bal felső sarkában 1086-os évszám látható.'),
    ('Tarnabod', 'A közvetlen szomszédos települések: észak felől Kompolt, északkelet felől Kál, kelet felől Erdőtelek, dél felől Boconád, nyugat felől pedig Tarnazsadány. Délkelet felől a legközelebbi település Heves városa, északnyugat felől pedig Nagyút, de közigazgatási területei (kevés híján) egyikével sem határosak. Csak közúton érhető el, Boconád vagy Kál felől, a 3204-es és a 3207-es utat összekötő 32 108-as számú mellékúton.'),
    ('Tarnalelesz', 'Tőle nyugatra Bükkszenterzsébet, északkeletre Szentdomonkos fekszik szomszédos településként. Lelez néven említik először írásban egy 1280-ban kelt oklevélben helyezkedik el. Az 1330-1337. évi pápai tizedjegyzékben is szerepel Lelez néven helyezkedik el. A török 1540-ben elpusztította, de néhány évvel később újjáépült. Hódoltsági terület lett. Az 1500-as évek közepétől kezdve 1945-ig többek között az Istenmezei, Nádasdy, Daróczy és Lórántffy családok voltak a birtokosai. 1910-ben 1684 magyar lakosa volt, melyből 1670 római katolikus volt.'),
    ('Tarnaméra', 'Gyöngyös és Heves városok között helyezkedik el, Budapesttől 100 kilométerre, Egertől 45 kilométerre. A közvetlen szomszédos települések: észak felől Tarnazsadány, kelet felől Boconád, délkelet felől Heves, dél felől Jászszentandrás, délnyugat felől Erk, nyugat felől pedig Zaránk. Északnyugat felől a legközelebbi település Nagyfüged, de a közigazgatási területeik (kevés híján) nem határosak.'),
    ('Tarnaszentmiklós', 'A szomszédos települések: észak felől Átány, északkelet felől Kömlő, délkelet felől Kisköre, délnyugat felől Pély, északnyugat felől pedig Hevesvezekény. Kelet felől a legközelebbi település Tiszanána, de a közigazgatási területeik nem érintkeznek. A község külterületeinek jelentős része – beleértve a falu központját övező területek szinte teljes egészét is – a Hevesi Füves Puszták Tájvédelmi Körzethez tartozó, természetvédelmi oltalom alatt álló terület.'),
    ('Tarnaszentmária', 'A falu a mai Észak-Magyarországon, a Mátra délkeleti oldalán, a Tarna teraszos völgyében fekszik a 2415-ös és a 24 128-as utak találkozásánál. A község tengerszint feletti magassága 260 méter. A község földjeinek talaját elsősorban réti talajok alkotják. Van a környékén kő- és kavicsbánya is. A községhez a legközelebbi nagyváros Eger, amelytől 17 kilométer-re nyugati irányban található. 1903-ig Szentmária volt a község neve.'),
    ('Tarnazsadány', 'Gyöngyöstől délkeletre, Hevestől északnyugatra fekszik, a Tarna mentén. A közvetlen szomszédos települések: észak felől Nagyút, északkelet felől Kompolt, kelet felől Tarnabod, délkelet felől Boconád, dél felől Tarnaméra, délnyugat felől Zaránk, nyugat felől pedig Nagyfüged. Első okleveles említése – Sodan néven – 1301-ben történt.'),
    ('Tarnaörs', 'A közvetlen szomszédos települések: észak felől Erk, kelet felől Jászszentandrás, délkelet felől Jászapáti, dél felől Jászdózsa, északnyugat felől pedig Jászárokszállás és Visznek. Első írásos említése egy 1264-ben kiadott oklevélben történik T.Wrs névalakban Ekkor nyerte adományul a települést az Aba nemzetségből való II. Kompolt, kinek Péter és Pál nevű fiait 1291-ben III.'),
    ('Tarpa', 'A híres „kuruc” település Nyíregyházától mintegy 72 kilométerre északkeletre helyezkedik el, a Beregi-síkságon, a Tisza ölelésében, a Kárpátok lábai és az Alföld találkozásánál, közvetlenül az ukrán határ mellett. Egykor jó kereskedelmi útvonal mentén feküdt, s csak Trianon után szorult periférikus helyzetbe. A közvetlen szomszédos települések: észak felől Beregsurány, kelet-délkelet felől Szatmárcseke, délkelet felől Nagyar, dél felől Tivadar, délnyugat felől Gulács, nyugat felől Hetefejércse, északnyugat felől pedig Márokpapi.'),
    ('Tarrós', 'Nevét eredeztetik a tarló szavunkból, más felfogás szerint Árpád fejedelem legidősebb fiának, Tarhosnak a nevéből. Az 1475-ös okiratban már Tarros néven említik. Az 1554-es egyházi összeírásnál található Tarrlós Bálint neve. A német temető feltárásakor találtak olyan csontvázat, amely ülő helyzetben, zsugorítva volt elhelyezve, ez arra utal, hogy a sír kő-, vagy bronzkori.'),
    ('Tass', 'A településnél ered mesterséges kivezetéssel a Kiskunsági-főcsatorna a Ráckevei-Duna-ágból, illetve a Ráckevei-Duna a Tassi-zsilipen keresztül - szintén mesterségesen és felduzzasztással - a Dunába torkollik. A Csepeli-síkon, Budapesttől hozzávetőlegesen 60 kilométerre délre helyezkedik el, a Duna főága és a Ráckevei-Duna találkozása közelében, a Duna balparti oldalán.'),
    ('Taszár', 'Taszár vasútállomása a Dombóvár–Gyékényes-vasútvonalon mintegy 2 kilométerre fekszik a község központjától délnyugati irányban. A Taszár szó szláv eredetű, eredeti jelentése famunkát, illetve ácsmunkát végezni. Ha minden áron magyarra akarnánk lefordítani, ácsok falva lenne a jelentése. Az első levéltári adatunk Taszárról Szent István idejéből való, aki előírta, hogy minden tíz falunak kötelezően templomot kell építenie.'),
    ('Tata', 'Az „Élővizek városa” és 2010-ben a biodiverzitás magyarországi fővárosa lett, így ismerve el a város kötődését a természeti értékekhez. A Dunántúl északi részén, a Kisalföld és a Dunántúli-középhegység találkozásánál helyezkedik el, a Gerecse és Vértes hegységeket elválasztó Tatai-árok Győr–Tatai-teraszvidékre nyíló északnyugati kapujában, az Által-ér folyásánál.'),
    ('Tatabánya', 'A Gerecse és a Vértes között helyezkedik el, ami meghatározza természeti környezetét és fekvését. Jelentős ipari központ, valamint fontos közlekedési csomópont Budapest és Győr között. A település mai formájában 1947-ben jött létre több korábbi település – Alsógalla, Felsőgalla, Bánhida és Tatabánya – egyesítésével. Fejlődése szorosan összefügg a szénbányászattal, amely a 19. század végétől kezdve meghatározta a város gazdaságát és arculatát.'),
    ('Tataháza', 'A Bácskai-löszháton fekszik, Bajától 28, Bácsalmástól 6 kilométerre, a Bácskában. A közvetlenül határos települések: észak felől Jánoshalma, kelet felől Mélykút, dél felől Bácsalmás, nyugat felől pedig Mátételke. Északnyugaton pontszerűen határos még Felsőszentivánnal is. Nyugati határában húzódik az Illancs térségében eredő Mátételki-Kígyós csatorna (a Kígyós-főcsatorna egyik mellékága), mely szárazabb nyarak idején elveszti vizét.'),
    ('Tatárszentgyörgy', 'Területét északon Dabas, északkelet felől Táborfalva (teljes hosszúságában egy néhány km széles katonai lőtér mentén) határolja. A község a Duna-Tisza közén, azon belül a Duna–Tisza közi homokhátság peremén található, mely nyugatról a Duna mentén elnyúló Csepel-solti síksággal, északról pedig a Pesti-síksággal érintkezik. A 17. század óta a falu képe sokat változott, de eredeti jellegzetességeit, kettős keresztutcás, fésűs beépítésű szerkezetét – az északkeleti tengelyében kiszélesedő torkú utcával – máig megőrizte.'),
    ('Tekenye', 'Zalaszentgróttól 4 kilométerre keletre, Türjétől pedig 2 kilométerre délkeleti irányban fekszik. Zsáktelepülés, közúton csak Zalaszentgrót irányából érhető el, a 7353-as útból kiágazó, pontosan 4 kilométer hosszú, 73 202-es számú mellékúton. A községet kedvező természeti adottságok jellemzik. A települést félkör alakban körülvevő dombokon zártkertek, szőlők találhatók, kevés erdővel.'),
    ('Teklafalu', 'A község lényegében egyutcás falu, mely Szigetvártól délnyugatra helyezkedik el, Drávafok és Kétújfalu között, lakott területe csaknem két kilométernyi hosszan nyúlik el észak-déli irányban. Teklafalu helyén az 1800-as évek elejéig egy Tiltvány nevű puszta állt.'),
    ('Telekgerendás', 'Közigazgatási határa 7237 hektárnyi területre terjed ki. További szomszédai: dél felől Csabaszabadi, délnyugat felől Gerendás, nyugat felől Csorvás, északnyugat felől pedig Kétsoprony. Negyedik tanácselnöke és első polgármestere Gyebnár János volt, aki 29 éven át töltötte be ezeket…'),
    ('Teleki', 'A szomszédos települések: Szólád, Kötcse, Nagycsepely és Rádpuszta. A település szőlőtermő területei a Balatonboglári borvidék részét képezik. Neve a telek főnév –i képzős származéka. A szó régen földművelésre, növénytermesztésre alkalmas területet is jelentett. Első említése 1211-ből való, amelyben a Tihanyi apátság birtokai közt szerepel, akkori írásmód szerint Villa Theluky.'),
    ('Telki', 'Telki a budapesti agglomeráció nyugati szektorában, Budapesttől 21 kilométerre, Budakeszitől 9 kilométerre nyugatra helyezkedik el, a Zsámbéki-medence északkeleti peremén, a Budajenői-patak völgyében. A fővárostól a Budai-hegység koszorúja, a tőle északabbra fekvő Nagykovácsitól e hegységnek a legmagasabb része (a Nagy-Kopasszal) választja el. Közvetlen (vele belterületen is határos, szinte a településsel teljesen összeépült) szomszédja Budajenő, közelebbi másik településszomszédja a mintegy 5 kilométer távolságra déli irányban található Páty.'),
    ('Telkibánya', 'Az Árpád-kori királyi bányák leghíresebbje található itt. Észak-Magyarországon, a Zempléni hegyvidék (Eperjes–Tokaji-hegység) középső részében, a Hegyközben fekszik, a szlovák határ közelében. Tengerszint feletti magassága 403 méter. A közvetlenül határos települések: észak felől Pányok, északkelet felől Füzér, kelet felől Nyíri, délkelet felől Regéc, délnyugat felől Fony, nyugat felől Gönc, északnyugat felől pedig Zsujta és Abaújvár.'),
    ('Tengelic', 'Pakstól délnyugatra kb. 15 kilométerre fekszik a Duna és a Sárvíz között, utóbbihoz közelebb. Több egymástól földrajzilag elkülönülő településrész alkotja. A közvetlenül határos települések: észak felől Nagydorog és Pusztahencse, északkelet felől Paks, kelet felől Dunaszentgyörgy, délkelet felől Fadd és Tolna, dél felől Fácánkert és Szedres, délnyugat felől Medina, nyugat felől Kölesd, északnyugat felől pedig Kajdacs.'),
    ('Tengeri', 'A szomszédos települések: észak felől Baksa, kelet és dél felől Hegyszentmárton, délnyugat felől Bogádmindszent, északnyugat felől pedig Téseny. A kelták által is lakott terület volt. A középkorban Baksai Izsép faluja terült el itt, tehát a szomszédos Baksa falu része volt. Első írásos említése Tengeren alakban 1428-ból ismert. A magyar lakosságú település a török korban sem pusztult el. 1851-ben Fényes Elek így írt a faluról: Tengerin, magyar falu, Baranya vmegyében, dombos fekvéssel, ut. p.'),
    ('Tengőd', 'Neve besenyő eredetű, a Tenguld szó gazdagságot jelent. Árpád-kori népességének középrétege katonáskodó, lóháton, jellegzetes nomád harcmodorban harcoló csoportokból állt, halottaikat is így temették el, melyről a Tengődön és Hékutpusztán feltárt sírok tanúskodnak. A település 1000 körül királyi birtok volt, egyik részét István király adományozta a szakcsi főesperességnek, a másikat a pécsi püspökségnek, majd 1138-ban II.'),
    ('Tenk', 'Kristó Gyula gyűjtötte össze a középkori Magyarországon élő nem magyar népekről szóló írásos emlékeket, ezek között megtalálható a besenyő Tenk tulajdonnév. A közvetlen szomszédos települések észak felől Erdőtelek, délkelet felől Átány, délnyugat felől pedig Heves. Arculatát gyönyörű ősparkok és a portákat, utakat elárasztó virágok jellemzik. A lakosok, portájuk rendben tartásával, gondozásával és virágosításával aktívan közreműködnek a településkép kialakításában.'),
    ('Terem', 'Ez a cikk a helyiségről szól, a településhez lásd: Terem (település). A terem nagy, magas, több-kevesebb dísszel kiállított fedett helyiség, ünnepélyek, hangversenyek, táncmulatságok, bankettek, előadások, stb. megtartására. A terem rendeltetése szerint a neve is más és más. Így megkülönböztettünk dísz-, hangverseny-, tánc-, ebédlő-, ülés-, olvasó-, stb. termet.'),
    ('Tereske', 'Tereske (-monostor, Tót-) Árpád-kori település. Nevét 1219-ben említette először oklevél Triskai alakban írva, majd 1255-ben Triske, Tottriske, 1274-ben Tottreske írásmóddal. Erről tanúskodik az altemplommal és eredeti freskókkal rendelkező román kori templom is. E kolostor a 13–15. században még fennállott. Nyomai a községhez tartozó Dennek-pusztai erdőben még ma is láthatók.'),
    ('Teresztenye', 'Vonattal a Sajóecseg–Hídvégardó-vasútvonalról Perkupa megállóhelyen kell leszállni, ahonnan Volán-járattal lehet eljutni Teresztenyére helyezkedik el. A falu az Aggteleki-karsztvidékhez tartozó Galya-fennsík lábánál fekszik, a hegylábfelszínen kialakult mélyedésben. Itt tör felszínre a Teresztenyei-forrásbarlangból (Kinizsi-barlang), egy állandó vízhozamú forrás.'),
    ('Terpes', 'Mindössze három környező településsel határos: északkelet felől Bükkszékkel, dél felől Szajlával, északnyugat felől pedig Kisfüzessel. Lakott területe Szajla-Újteleppel teljesen összenőtt. Határszélét érinti még a Bükkszékre vezető 24 123-as út is. Határában vandál temetőt tártak fel. 1409-ben Trebes, 1466-ban Therpes névalakban említik az oklevelek.'),
    ('Terény', 'Jó állapotban megőrződött, a nógrádi paraszti hagyományokra jellemző építkezési stílusban épült házainak nagy száma, valamint a településen található jó néhány múzeum és kiállítóhely miatt a térség fontos idegenforgalmi célpontja. Balassagyarmattól 20 kilométer-re, a Szanda-patak völgyében található község, amely a Novohrad-Nógrád UNESCO Globális Geopark települése..'),
    ('Teskánd', 'Közvetlenül Zalaegerszeg mellett fekszik, a 7405-ös út mentén. Első említése 1271-ből származik Tuskánd néven, ebből később Töskánd lett. Nevének eredete egy török személynévből származik. Egerszeg várához tartozott. 1728-ban Teskánd ákosházi Sárkány Gábornak, nemes Patay Istvánnak és boldogfai Farkas János özvegyének, sidi Sidy Dorottyának az örökölt és tényleges birtoka. 1925-ben körjegyzőséget kapott.'),
    ('Tetétlen', 'A közvetlen szomszédos települések: északkelet felől Hajdúszovát, délkelet felől Földes, délnyugat felől Báránd, északnyugat felől pedig Kaba. Csak közúton érhető el, Nádudvar-Kaba és Földes felől is a 3407-es. Címerének formája pajzs-veret, az alapja egy pontig ívelt. Zöld alapon a heraldikai jobb oldalon három búzakalászt, a bal oldalon ezüstös aratósarló visel.'),
    ('Tevel', 'A szomszédos települések: északkelet felől Murga és Kéty, délkelet felől Kisdorog, dél felől Nagyvejke, délnyugat felől Závod, nyugat felől Mucsi, északnyugat felől pedig Hőgyész. Nagyon kevés híja van annak, hogy nem határos észak felől még Kalaznóval is. Tevel és környékének első fontosabb régészeti leletei az újkőkorszakból származnak: ezek egy ismeretlen földművelő nép sírjai illetve edénytöredékei.'),
    ('Tibolddaróc', 'A Miskolci-Bükkalja területén, a Kácsi-patak völgyében helyezkedik el, Egertől (a legrövidebb erdei úton) 26, Miskolc pedig (légvonalban) 15 kilométer távolságra. A szomszédos települések: észak felől Kács, északkelet felől Sály, kelet felől , Vatta, délkelet felől Bükkábrány, dél felől Mezőnyárád, délnyugat felől Tard, nyugat felől pedig Cserépváralja.'),
    ('Tiborszállás', 'Határszéle délkelet felől egybeesik a magyar-román államhatárral. A környék fontosabb települései közül Fábiánháza 9,5, Nagyecsed 12, Mérk 9, Vállaj pedig 10 kilométer távolságra található. A közvetlen szomszédos települések a határ magyar oldalán: észak felől Nagyecsed, északkelet felől Tyukod, dél felől Mérk, északnyugat felől pedig Fábiánháza. A határ túloldalán a legközelebbi település Börvely (Berveni), míg a legközelebbi nagyobb település, a romániai Nagykároly (Carei).'),
    ('Tihany', 'Magyarország egyik legszebb fekvésű települése, látványos táji és természeti adottságokban bővelkedő község a Balatonba nyúló Tihanyi-félszigeten helyezkedik el. A község központjában áll a Tihanyi Bencés Apátság, amelyet 1055 -ben alapított I. András magyar király, aki az apátság kriptájában lett eltemetve. Az apátság alapító okirata a magyar nyelv első fennmaradt szórványemléke, amelyet a Pannonhalmi Bencés Főapátságban őriznek.'),
    ('Tikos', 'A Balatontól légvonalban 8 kilométerre, gépjárművel, vagy kerékpárral 14 kilométerre délre, Marcalitól északnyugatra, Főnyed és Hollád közt fekvő település. A mai Tikos Árpád-kori település. Nevét 1299-ben említette először oklevél Tykus alakban írva. A 14. század közepén Fejéregyházi György birtoka volt, akinek leányát I. Lajos király 1368-ban fiúsította. 1405-ben thapsoni Anthymus János (fl. 1368–1423) nyerte Fejéregyházi Katics asszonytól, majd 1406-ban Berzenczei Lóránt fia, György kapta meg.'),
    ('Tilaj', 'Különálló településrésze Tilajújhegy, a központjától bő 2 kilométerre északra helyezkedik el. A közvetlenül határos települések: észak felől Almásháza, északkelet felől Ligetfalva, kelet felől Zalacsány, dél felől Szentpéterúr, nyugat felől pedig Nagykapornak. Nagyon kevés híja van annak, hogy nem határos északnyugat felől még Padárral is. A főútról Tilaj a 73 236-os, Tilajújhegy pedig a 73 233-as számú bekötőúton érhető el.'),
    ('Timár', 'A község lakott területe a folyó bal parti oldalán fekszik, de közigazgatási területének közel 5 négyzetkilométernyi, lakatlan – leginkább mezőgazdasági hasznosítású – része a Tisza jobb partjára esik. A település nevét már 1067-ben mint a szabolcsi várhoz tartozó birtokot említi oklevél, és a várat kiszolgáló tímárok lakhelyét. nevét ekkor még Vense alakban írták.'),
    ('Tinnye', 'Piliscsabával az 1133-as út, nyugati szomszédjával, Únnyal, illetve azon keresztül Csolnokkal és Doroggal az 1106-os út köti össze. A települést a jövőben az M1-es autópályát Esztergommal összekötő M100-as autóút (korábbi tervezési nevén R11-es gyorsút) fogja tehermentesíteni. Az autóút építését 2022-ben elhalasztották.'),
    ('Tiszaadony', 'A közvetlenül szomszédos települések: észak felől Tiszakerecseny, kelet felől Barabás, dél felől Tiszavid, délnyugat felől Aranyosapáti, északnyugat felől pedig Újkenéz (utóbbi kettő a Tisza túlsó, bal partján fekszik). A legközelebbi nagyobb város Vásárosnamény, nagyjából 14 kilométerre délre helyezkedik el. Tiszaadony (Adony) nevét az oklevelek 1290-ben említették először, Odon néven helyezkedik el.'),
    ('Tiszabecs', 'Közigazgatási határszélén lép be a Tisza (a 744,5 folyamkilométernél) Magyarország területére. Szomszédai a határ magyar oldalán: nyugat felől Milota, délnyugat felől Sonkád, dél felől Botpalád, délkelet felől pedig Uszka. Északkelet felől a legközelebb település a már Ukrajnához tartozó Tiszaújlak (Вилок).'),
    ('Tiszabercel', 'A megyeszékhelytől, Nyíregyházától északra, légvonalban mintegy 23 kilométerre található. Belterülete a Tisza bal parti oldalán fekszik, de néhány négyzetkilométernyi külterület tartozik hozzá a folyó jobb parti oldaláról is. A közvetlen szomszédos települések: észak felől Györgytarló, északkelet felől Tiszakarád, kelet felől Paszab, dél felől Buj, nyugat felől pedig Gávavencsellő.'),
    ('Tiszabezdéd', 'A község nevezetes az ott talált honfoglalás kori tarsolylemez miatt. Egyedülálló módon a bőrtarsoly is viszonylag épen megmaradt. A szomszédos települések: észak felől Győröcske, észak-északkelet felől Záhony, északkelet felől Zsurk, kelet felől Tiszaszentmárton, délkelet felől Eperjeske, dél-délkelet felől Mándok, dél felől Tuzsér, délnyugat felől (a Tisza túlpartján) pedig Zemplénagárd.'),
    ('Tiszabura', 'A község a Tisza folyásirányának bal partján fekszik, a Tisza-tótól délre. Északi határszéle közelében található a kiskörei Tisza-híd bal parti hídfője. Hozzá tartozik különálló településrészként Pusztataskony, mely a központjától mintegy 6 kilométerre északkeletre helyezkedik el. A község története a régmúlt…'),
    ('Tiszabábolna', 'A Tisza partján, a Súlymos-főcsatorna torkolatánál fekszik. Tömegközlekedéssel Mezőkövesd és Mezőcsát felől a Volánbusz 4010-es járatával közelíthető meg. A mai Magyarország területén három Bábolna ismert (Bihar, Borsod, Komárom vm.) Mindhárom a Koppány (Katapán) nemzetségbeli Bábolnai család birtoka volt, így az adatok szétválasztása nehéz, olykor önkényes.'),
    ('Tiszabő', 'A közvetlenül szomszédos települések: észak felől Tiszagyenda, kelet felől a Kendereshez tartozó Bánhalma, dél felől Fegyvernek, délnyugat felől Nagykörű, északnyugat felől pedig Kőtelek, e két utóbbi s Tisza túlsó, jobb parti oldalán. Tiszaroff, Fegyvernek, a Tisza jobb partján pedig Kőtelek. Legészakibb külterületei nagyrészt a 2009-ben átadott tiszaroffi árapasztó tározó területéhez tartoznak.'),
    ('Tiszacsege', 'Polgártól 30 kilométerre dél-délnyugatra, Tiszafüredtől 30 kilométer-re északkeletre, a Hortobágyi Nemzeti Park északnyugati kapujában található. Nagymajor nevű, különálló városrésze a központtól légvonalban 7, közúton csaknem 10 kilométerre délre helyezkedik el. Mindkét említett város felől a 3315-ös úton érhető el, Balmazújvárossal és Debrecennel a 3316-os út kapcsolja össze.'),
    ('Tiszacsermely', 'A Zempléni-hegység és az Alföld határánál található, a Bodrogközben, Sárospataktól mintegy 20 kilométerre keletre. Csermely nevű településrésze közvetlenül a Tisza gátjánál ér véget. A gáttól a Tisza mintegy 500 méterre folyik. A nyugati szomszédságában fekvő Tiszakaráddal egy számozatlan, alsóbbrendű út köti össze. Arról az útról közelíthető meg a felső-tiszai térség legnagyobb egybefüggő folyóparti partifecske-telepe is, amely a környék kevés különleges látnivalói közé tartozik.'),
    ('Tiszacsécse', 'A Szatmári-síkságon fekszik, közvetlenül az ukrán határ mellett, a Tisza bal partján. A határ magyar oldalán csak két szomszédja van: kelet felől Milota, nyugat felől pedig Tiszakóród. Észak felől a túlparton fekvő, közigazgatásilag Ukrajnához tartozó Vári (Вари) és Csetfalva (Четфалва) települések határolják. A legközelebbi város a határ magyar oldalán Fehérgyarmat, melytől mintegy 20 kilométerre keletre fekszik.'),
    ('Tiszadada', 'A közvetlenül határos települések: észak felől Taktakenéz, Prügy és Taktabáj, északkelet felől Csobaj − mind a négy eddigi a Tisza túlpartján −, kelet felől Tiszalök, délkelet felől Tiszavasvári, délnyugat felől pedig Tiszadob. A község területén talált régészeti leletek is bizonyítják, hogy már a Kr.e. IV. évezredben a neolitkorban is megélhetést nyújtott őseinknek, az itt talált, a Bükki kultúra idejéből való leletek tanusága szerint.'),
    ('Tiszaderzs', 'A közvetlen szomszédos települések: észak-északkelet felől Tiszafüred és Tiszaszőlős, kelet felől Tiszaszentimre, délnyugat felől Abádszalók, északnyugat felől pedig Újlőrincfalva. Csak közúton érhető el: Tiszafüred-Tiszaszőlős és Abádszalók felől a 3216-os, Tiszaszentimre felől pedig a 3218-as úton. Derzs már a honfoglalás után nem sokkal benépesült.'),
    ('Tiszadob', 'A megyeszékhely Nyíregyházától 42, Tiszavasváritól 21, Tiszalöktől 17,5 kilométer távolságra található. Tiszadob és környéke már a honfoglalás előtt is lakott hely volt. A környékén végzett ásatások során bronzkori leletek, szarmata temető nyomai kerültek felszínre, a falu határában pedig az itt húzódó Csörsz árka és egy földvár nyomaira bukkantak.'),
    ('Tiszadorogma', 'Tömegközlekedéssel Mezőkövesd és Mezőcsát felől a Volánbusz 4010-es járatával közelíthető meg. Tiszadorogma (Dorogma) Árpád-kori település. Nevét már 1200 körül említette oklevél Drugma néven helyezkedik el. Későbbi névváltozatai: 1320-ban Dorogma, 1328-ban Durugman, Durugma, Doregma, Doregna, Dorogina. Révje már Anonymus honfoglalás…'),
    ('Tiszaeszlár', 'Tokajtól délre fekszik, a Tisza bal (keleti) partján. A legközelebbi szomszédja a tőle északra fekvő Tiszanagyfalu. További határos települések: kelet felől Nyírtelek, délkelet felől Nagycserkesz, délnyugat felől Tiszalök, nyugat felől pedig a Tisza túlpartján fekvő Tiszaladány. A török eredetű, honfoglalás kori úz népnévből képzett helynév…'),
    ('Tiszaföldvár', 'Tiszaföldvár az Alföldön, a Közép-Tisza-vidékhez tartozó Nagykunság kistájegységében, Szolnoktól délre, a Közép-tiszai Tájvédelmi Körzet alsó szakaszán a Tisza folyó középső szakaszán, annak bal partján, a Tiszazug északi részén fekszik. A várostól legközelebb északra Martfű, délre Cibakháza, keletre Mezőhék található. Budapesttől kb 130 kilométer-re található.'),
    ('Tiszafüred', 'A Tisza-tó turisztikai régió központja, a „Tisza-tó fővárosa”. Határának északi csücske egyben a megye legészakibb pontja is. Éghajlata kontinentális, a forró, száraz nyarat általában hideg tél követi. Ezen a tájon legmagasabb a napsütéses órák száma, az átlagos csapadék mennyiség 480–500 mm. A természeti adottságok közül kiemelkedő, hogy a város és térsége igen gazdag élővizekben helyezkedik el.'),
    ('Tiszagyenda', 'A Nagykunság délnyugati részén helyezkedik el, a Tisza-tó vonzáskörzetében. A közvetlenül szomszédos települések: észak felől Tiszabura, kelet felől Kunhegyes, délkelet felől Kenderes-Bánhalma, dél felől Tiszabő, nyugat felől pedig Tiszaroff. Határában elszikesedő, löszös területeket, löszös fedett buckákat láthatunk. Legnyugatibb külterületei nagyrészt a 2009-ben átadott tiszaroffi árapasztó tározó területéhez tartoznak.'),
    ('Tiszagyulaháza', 'Domborzata ártéri szintű síkság, kis lejtéssel a Tisza irányába. Talajtakarója jellemzője túlnyomóan réti talaj, helyenként szikes. A Tisza a falu nyugati szélénél folyik, kisebb vízfolyás a Király-ér. A közvetlenül határos települések: észak felől Tiszadob, délkelet felől Újtikos, dél felől Polgár, nyugat felől pedig Tiszaújváros. A Közép-Tisza mentén terjeszkedő Andrássy-birtok egyik majorsági központja volt.'),
    ('Tiszaigar', 'A további, közvetlenül határos települések: kelet felől Kócsújfalu (Tiszafüred része), dél felől Tiszaörs, délnyugat felől Tiszaszentimre, nyugat felől pedig Tiszaszőlős. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. Tiszaigar Árpád-kori település, mely egykor a Tomaj nemzetség Abádi ágának ősi birtoka volt.'),
    ('Tiszainoka', 'Az Alföldön, a megye délnyugati sarkában, a Tiszazugban, a Tisza bal partján fekszik, Szolnoktól mintegy 40 kilométerre. A szomszédos települések: Tiszakürt, Cserkeszőlő, Nagyrév és Cibakháza. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. A község mellett drótköteles komp és révész segítségével lehet átkelni a Tiszán Tiszakécskére. A kompon személy, illetve motorkerékpár és kerékpár szállítása lehetséges.'),
    ('Tiszajenő', 'Szolnoktól mintegy 23 kilométerre dél-délnyugatra fekszik, a Tisza jobb partján. A szomszédos települések: észak felől Tiszavárkony, kelet felől Vezseny, délnyugat felől Tiszakécske Tiszabög nevű településrésze, nyugat felől pedig Jászkarajenő. Közigazgatási területe dél-délkelet felől érintkezik Tiszaföldvár, Cibakháza és Nagyrév területével is, de ez utóbbi három település a folyó túlsó partján terül el.'),
    ('Tiszakanyár', 'A Rétközben, Dombrád kisváros mellett, attól északkeletre, a Tisza mellett, annak bal partján fekvő település. A szomszéd települések: észak felől Ricse, északkelet felől Szabolcsveresmart, kelet felől Kékcse, dél felől Pátroha, délnyugat felől Dombrád, nyugat-északnyugat felől pedig Cigánd. Közigazgatási területe délkelet felől egy ponton érintkezik Rétközberencs határszélével is.'),
    ('Tiszakarád', 'Régebben kompjáratok kötötték össze a túlparti Ibránnyal és Tiszatelekkel is, de manapság már e kompátkelőknek is alig van nyomuk a folyó partjain. 1976-ig a Bodrogközi Kisvasút is érintette a települést. Tiszakarádot 1411-ben említik először az oklevelek Karád néven helyezkedik el.'),
    ('Tiszakerecseny', 'A szomszédos települések a határ magyar oldalán: észak felől Mátyus, délkelet felől Barabás, dél felől Tiszaadony, nyugat felől Újkenéz, északnyugat felől pedig Mezőladány. A határ túloldalán a két legközelebbi település Hetyen (Гетен) és Papitanya (Мaле Попово). A legközelebbi nagyobb város Vásárosnamény, mintegy 25 kilométerre délre helyezkedik el.'),
    ('Tiszakeszi', 'A Taktaköztől délnyugatra húzódó Borsodi-ártér térségében helyezkedik el. Mezőcsáttól 8 kilométer-re délkeletre, Tiszatarjántól délre, a Tisza partján található. Zsáktelepülésnek tekinthető, mivel közúton csak a Mezőcsát–Tiszaújváros közti 3313-as útból kiágazó 33 106-os számú mellékúton érhető el. A Keszi török eredetű szó: az ótörök Kesak (darab), s ennek töve a kes (vág).'),
    ('Tiszakécske', 'Az Alföldön, a Duna–Tisza közi homokhátságon, a Pilis–Alpári-homokhát Tisza jobb partjáig érő délkeleti csücskében, a teljes közigazgatási területével a folyó partja mentén helyezkedik el. Az országos főutak elkerülik Tiszakécskét, csak négy és öt számjegyű közutak húzódnak a területén.'),
    ('Tiszakóród', 'Tiszabecs 11 kilométer, Milota 8 kilométer, Tiszacsécse 5 kilométer, Szatmárcseke 9 kilométer, Vásárosnamény 38 kilométer, Nagyar 17 kilométer, Fehérgyarmat 24 kilométer távolságra található. A falutól nyugati irányban található a Túr folyó. Itt ömlik a Túr vize a Tiszába. A hely érdekessége, hogy a sokszor nagyon magas vízállású Tisza miatt a Túr folyó vizét néhány méter magas, úgynevezett bukógáton keresztül engedik a Tiszába, hogy magas vízállásaikor a Tisza vissza ne duzzassza a Túr vizét, ami így vízesésként ömlik le.'),
    ('Tiszakürt', 'Az Alföldön, a Tiszazugban, a Tisza bal partján fekszik, Jász-Nagykun-Szolnok megye délnyugati sarkában, a megyeszékhelytől, Szolnoktól kb. 45 kilométer-re. A szomszédos települések: észak felől Tiszainoka, kelet felől Cserkeszőlő, dél felől Csépa, délnyugat felől Tiszasas, nyugat felől Tiszaug, északnyugat felől pedig Tiszakécske. Az említett utak azonban a belterületeit dél felől elkerülik, azokon csak a 4514-es és 4515-ös utak húzódnak keresztül.'),
    ('Tiszaladány', 'Határában három tájegység találkozik. Területének északi része mély fekvésű, déli része pedig, különösen a Tisza mentén dombos. Mai arculata a pleisztocén–holocén folyamán alakult ki, formálásában döntő tényező a víz és a szél volt. A 19. században a Tisza szabályozása során a Taktaköz peremén több, mint hat kanyarulatot vágtak le a folyóból helyezkedik el.'),
    ('Tiszalök', 'A térség jelentősebb települései közül Tiszavasvári 7,5, Hajdúnánás 20, Tiszaeszlár 10,5, Rakamaz 23,5, a megyeszékhely Nyíregyháza pedig 25,5 kilométer távolságra található. Közigazgatási területe kelet-nyugati irányban meglehetősen hosszan elnyúlik, legkeletibb és legnyugatibb határszélei közt a távolság csaknem 18 kilométer.'),
    ('Tiszalúc', 'A nagyközséget északról Taktaharkány, keletről a Tisza (azon túl Tiszadob), délről Kesznyéten, Girincs és Köröm, nyugatról pedig Hernádnémeti, Bőcs és Berzék határolják. Tengerszint feletti magassága 124,24 méter, legmagasabb része a Messzelátó domb (156 méter), legalacsonyabb helye a Vadvizes és a Sárrét (96 méter).'),
    ('Tiszamogyorós', 'Az Észak-Nyírségben, a Tiszakönyöknek nevezett tájon fekszik, a Tisza bal parti oldalán. A folyó áradásaitól mindig is sokat szenvedett falu 1864-ben költözött a jelenlegi, negyedik helyére. A szomszédos települések: kelet felől Lónya, dél felől Benk, nyugat felől Mándok, északnyugat felől pedig Eperjeske. Közúton csak Mándok vagy Lónya érintésével érhető el, a 4113-as úton.'),
    ('Tiszanagyfalu', 'Tiszanagyfalu a Nyíri-Mezőségben fekszik. A Nyíri-Mezőség a Nyírségtől nyugatra eső terület, mely a Hajdúhát északi részére és a Tisza-mente egy kisebb szakaszára terjed ki. Az itt megtelepült hat helység - Tiszadada, Tiszadob, Tiszaeszlár, Tiszalök, Tiszavasvári és Tiszanagyfalu – néprajzát tekintve (is) elüt a szomszédos területektől. Jellemzőjük a majd mindenütt kialakult kétbeltelkesség.'),
    ('Tiszanána', 'A Tisza jobb parti oldalán helyezkedik el, a folyótól, illetve a Tisza-tótól mintegy 6 kilométerre. Déli határvonala a folyó sodorvonalát követi − a Tisza-part közelében létesült a községhez tartozó üdülőterület, Dinnyéshát −, északnyugati határában pedig viszonylag nagy terület tartozik a Hevesi Füves Puszták Tájvédelmi Körzethez. A szomszédos települések: északkelet felől Sarud, dél felől Abádszalók, délnyugat felől Kisköre, északnyugat felől pedig Kömlő.'),
    ('Tiszapalkonya', 'A település lakott területe közvetlenül a Tisza jobb partján fekszik, Tiszaújváros központjától 4-5 kilométerre. Közigazgatási területének viszont csak a kisebb része helyezkedik el a jobb parton, nagyobb része a folyó bal, hajdúsági partján terül el. Bal parti területrésze lakatlannak tekinthető, ott jobbára csak mezőgazdasági területek találhatók.'),
    ('Tiszapüspöki', 'Tiszapüspöki a Tisza bal partján, Szajol szomszédságában, Törökszentmiklóstól 8 kilométer-re északnyugatra található. Belterülete vonatkozásában azonban a község zsákfalunak tekinthető, mivel kiépített közúton csak egy irányból érhető el, az előbbi csomópontból kiinduló 32 127-es számú mellékúton. Tiszapüspöki és a környező területek már az ősidők óta lakott terület.'),
    ('Tiszaroff', 'A Tisza mellett fekszik, a Tisza-tó térségétől nem messze délnyugati irányban, a folyó egy nagy méretű – mintegy 14 kilométeres szakasza alatt bő 180 fokos irányváltást leíró – kanyarulatának ölelésében. A község szinte teljes területe a bal parti oldalon helyezkedik el, területének csupán csekély hányada (egy holtág által közrefogott, kevesebb, mint 2 négyzetkilométernyi része) esik a jobb parti oldalra.'),
    ('Tiszarád', 'A megye északnyugati részén helyezkedik el, a Rétközben, Nyíregyházától mintegy 20 kilométerre északra. A közvetlen szomszédos települések: észak felől Tiszatelek, kelet felől Vasmegyer, dél felől Kemecse, nyugat felől pedig Nagyhalász. Tiszarád (Rád) nevét az oklevelek 1445-ben említették először, ekkor már mai nevén helyezkedik el. Birtokosa ekkor a Kemecsey család volt.'),
    ('Tiszasas', 'Szomszédai: észak felől Tiszaug, északkelet felől Tiszakürt, kelet felől Csépa, dél felől Csongrád, nyugat felől pedig (a folyó túlsó partján) Tiszaalpár. Sokan úgy gondolják, hogy neve a madárnévből keletkezett, ám valójában…'),
    ('Tiszaszalka', 'A közvetlenül szomszédos települések: kelet felől Vámosatya, dél felől a Vásárosnaményhoz tartozó Gergelyiugornya, délnyugat felől Kisvarsány és Nagyvarsány, nyugat felől Gyüre (utóbbi három a Tisza túlsó, bal partján), északnyugat felől pedig Tiszavid. A térség fontosabb települései közül Vámosatya 6, Gelénes 8,5, Beregdaróc 15,5, Vásárosnamény pedig 7,5 kilométer távolságra található.'),
    ('Tiszaszentimre', 'A Tisza-tótól délkeletre fekszik, Tiszafüredtől 14 kilométerre délre, Abádszalóktól pedig 10 kilométerre kelet-északkeleti irányban. A közvetlen szomszédos települések: észak felől Tiszaszőlős, északkelet felől Tiszaigar, kelet felől Tiszaörs, délkelet felől Kunmadaras, dél felől Tomajmonostora, délnyugat felől Abádszalók, nyugat-északnyugat felől pedig Tiszaderzs.'),
    ('Tiszaszentmárton', 'A megye északi szélén helyezkedik el, közvetlenül az ukrán határ mellett, a Tisza bal partján. A szomszédos települések a határ magyar oldalán: észak felől Zsurk, dél felől Eperjeske, nyugat felől Tiszabezdéd, északnyugat felől pedig Záhony. A határ túloldalán a legközelebbi települések: északkelet felől Eszeny, kelet felől pedig Szalóka. Csak közúton érhető el, Zsurk vagy Eperjeske érintésével, a 4115-ös úton.'),
    ('Tiszasziget', 'A mai település központi része egy szigetszerű kiemelkedésen jött létre nem messze a Tisza és a Maros összefolyásától, azok egykori kanyarulataival körülölelve – erről a sajátos helyzetéről kapta jelenkori nevét is –, a mai területéhez tartozó egyes lakott helyek ugyanakkor egykoron a Tisza túlpartjához tartoztak.'),
    ('Tiszaszőlős', 'A legközelebbi város Tiszafüred, mintegy 8 kilométerre északra, míg a megyeszékhely, Szolnok 78 kilométer távolságra található. A szomszédos települések észak felől Tiszafüred, kelet felől Tiszaigar, nyugat felől Tiszaderzs, délnyugat felől pedig Tiszaszentimre helyezkedik el. Nyugat és északnyugat felől Újlőrincfalvához tartozó külterületek határolják.'),
    ('Tiszasüly', 'Határszélét nyugaton érinti még a 3225-ös és a 3226-os út is. 1311-ben egy egyházi dézsmaösszeírás említette a települést először Sw, Swl, Swlh néven helyezkedik el. Ebben az időszakban, a 14. század elején a falu és környéke egy nógrádi nemes, bizonyos Fogarasi Gergelyé volt, aki fiúutód híján két lányára, Erzsébetre és Amáliára örökítette sülyi birtokait. 1325-ben a falu Tiszaroffal együtt az Aba nemzetségbeli Kompolthy András, fia Péter, fia István birtokába került 1250 aranyforint ellenében.'),
    ('Tiszatardos', 'Tokajtól mintegy 10 kilométerre délre fekszik, a Taktaközben. Teljes belterülete és külterületének nagy része is a Tisza jobb parti oldalára esik, de egy kisebb területrésze a folyószabályozások következtében a mai bal parti oldalra került. Mindössze három településsel határos: északkeleti szomszédja Tiszaladány, nyugat felől Csobajjal szomszédos (mindkettőtől nagyjából 3-3 kilométer távolságra helyezkedik el), déli határszéle pedig a folyó túlsó partján található Tiszalök területével érintkezik.'),
    ('Tiszatarján', 'Mezőcsáttól keletre, Tiszakeszitől északra található. Zsáktelepülésnek tekinthető, mert bár a közigazgatási területén áthalad a Mezőcsát–Tiszaújváros közti 3313-as út, belterülete csak az abból kiágazó 33 107-es számú mellékúton érhető el. A község nevében fellelhető a Tarján honfoglaló törzs neve, régészeti leletek tanúsága szerint korábban ez a terület szkíta és más népek lakóhelyéül szolgált.'),
    ('Tiszatelek', 'Lakott településrészei mind a folyó bal parti oldalán helyezkednek el, de közigazgatási területének egy csekély hányada, mintegy 2 négyzetkilométernyi része a túlparti oldalra esik. Ott részben természetvédelmi oltalom alatt álló ártéri erdők, részben mezőgazdasági hasznosítású területek találhatók.'),
    ('Tiszatenyő', 'Vasúton 17, közúton 27-30 kilométerre van Szolnoktól. A település környékén megtalálták mind a körösi, mind a hatvani kultúra nyomait, így a vidék már az ősidőktől kezdve bizonyítottan lakott. A települést (ami akkor tulajdonképpen még csak egy uradalmi major volt cselédházakkal) és egy kolostort írásos források először csak 15. században említik meg.'),
    ('Tiszaug', 'A Tisza bal partján fekvő település, Lakitelektől keletre és Csongrádtól északra, amelynek vannak határrészei a folyó túlsó partján is. Régóta fontos tiszai átkelőhely. Szomszédai: észak felől (a jobb parton) Tiszakécske Kerekdomb településrésze, északkelet felől Tiszakürt, délkelet felől Csépa, dél felől Tiszasas, délnyugat felől Tiszaalpár, nyugat felől pedig Lakitelek (utóbbi kettő úgyszintén a jobb parton).'),
    ('Tiszavalk', 'Tömegközlekedéssel Mezőkövesd és Mezőcsát felől a Volánbusz 4010-es járatával közelíthető meg. Neve puszta személynévből keletkezett magyar névadással. Az alapját adó szó szláv eredetű, a szláv nyelvekben előfordul több változata is pl. a cseh Vlk, a lengyel Wilk. A név előzménye a farkas jelentésű ószláv Bolk. Tiszavalk a Tisza-tó északi csücskében elhelyezkedő ősi település, már a történelem előtti időkben is lakott volt, határában még feltáratlan – feltételezések szerint – Közép-Európa legnagyobb kiterjedésű bronzkori telephelye.'),
    ('Tiszavasvári', 'Mai nevét 1952-ben kapta Vasvári Pálra emlékezve, de tulajdonképpen 1950-ben jött létre Bűdszentmihály és Tiszabűd egyesítésével. A két település már korábban, 1941 és 1946 között is egyesítve volt Bűdszentmihály néven. Közelében található a tájvédelmi területté nyilvánított Fehér-szik. A közvetlenül határos települések: észak felől Tiszalök és Szorgalmatos, kelet felől Nagycserkesz, délkelet felől Hajdúdorog, dél felől Hajdúnánás, délnyugat felől Polgár, nyugat felől Újtikos, északnyugat felől pedig Tiszadob és Tiszadada.'),
    ('Tiszavid', 'A szomszédos települések: észak felől Tiszaadony, északkelet felől (a már közvetlenül az ukrán határ mellett fekvő) Barabás, kelet felől Vámosatya, délkelet felől Tiszaszalka, délnyugat felől Gyüre, nyugat felől pedig Aranyosapáti. A térség fontosabb települései közül Vásárosnamény 12,5, Tiszaadony 7, Tiszaszalka 2, Vámosatya 8, Gelénes pedig 10,5 kilométer távolságra található.'),
    ('Tiszavárkony', 'Tiszavárkony a Tisza jobb partján fekszik. A szomszédos települések észak felől Tószeg, kelet felől (a Tisza túlpartján) Rákóczifalva, délkelet felől Vezseny, dél felől Tiszajenő, nyugat felől pedig Jászkarajenő. A település központján a Szolnok és Tiszakécske térségét összekötő 4625-ös út halad végig, ezen érhető el mindkét említett város irányából.'),
    ('Tiszaörs', 'Tiszafüredtől 14 kilométer-re délkeletre helyezkedik el. A közvetlenül határos települések: északkelet felől Kócsújfalu (Tiszafüred különálló városrésze), kelet felől Nagyiván, dél felől Kunmadaras, nyugat felől Tiszaszentimre, északnyugat felől pedig Tiszaigar. A régészeti leletek tanúsága szerint a magyarok már a honfoglalás korában megszállták Tiszaörs környékét, s ott tartósan meg is telepedtek.'),
    ('Tiszaújváros', 'A Leninváros név ide irányít át. A Leninváros nevet 1919-ben rövid ideig Pesterzsébet is viselte. Közigazgatási területének egy kisebb része a Tisza túlsó oldalán, a bal parton fekszik, de az a területrész lakatlannak tekinthető. Területe 46,04 km² Tiszaújváros kedvező földrajzi fekvéssel bír, összekapcsoló szerepet…'),
    ('Tisztaberek', 'Szomszédai: észak felől Botpalád, kelet felől Kishódos, dél felől Rozsály, délnyugat felől Gacsály, nyugat felől pedig Túrricse. Külterületei messze elnyúlnak északra a lakott területeitől, így északnyugat felől határos még Csaholccal és Sonkáddal is. Legközelebbi szomszédja Túrricse mintegy 3-4 kilométerre helyezkedik el. A környék más települései közül Rozsály 5, Méhtelek 9,5, Zajta 11, Gacsály 8, Császló pedig 12,5 kilométer távolságra található.'),
    ('Tivadar', 'A Tivadar férfinév a Teodor név magyar alakja. Fejlődési alakja: Teodor, Tiodor, Tiadar, Tivadar.[forrás?] Női párja: Teodóra helyezkedik el. Fedor: a Teodor név orosz alakja. (helyesebben: Fjodor – Фёдор, egyházi alakja: Feodor - Феодор) Teodor: görög eredetű férfinév, a jelentése Isten ajándéka. Tódor: a Teodor magyar rövidülése. Az 1990-es években a Tivadar igen ritka, a Fedor, Teodor és a Tódor szórványos név volt, a 2000-es években nem szerepelnek a 100 leggyakoribb férfinév között.'),
    ('Tokaj', 'A Tokaji borvidék névadó települése, amiben nemcsak a bortermelésben és -kereskedelemben játszott szerepe, hanem stratégiai, közlekedési csomóponti fekvése is szerepet játszik. A Taktaköz keleti peremén, a megye székhelyétől, Miskolctól mintegy 54 kilométerre keletre helyezkedik el, a Tokaji borvidéken, a Tisza és a Bodrog összefolyásánál, a Kopasz-hegy lábánál.'),
    ('Tokod', 'Közeli nagyobb települések még Nyergesújfalu 12,5 kilométerre északnyugatra és Esztergom 8,5 kilométerre északkeletre helyezkedik el. Környéke már ősidők óta lakott helynek számít. Területén bronzkori, római és honfoglalás kori leletek kerültek elő. Itt találták meg a késő római korból származó, 120×140 méter területű, 1,5 méter falátmérőjű, 11 kerek toronnyal rendelkező ún.'),
    ('Tokodaltáró', 'Tokod központjával a 10-esből a két település határvonala közelében kiágazó 1118-as út köti össze. A település nevének előtagját egy Tokod nevű vitézről kapta a fennmaradt hagyományok szerint. Nevének utótagja az itt folyt bányászatra utal. Tokodaltáró és környéke ősidők óta lakott hely volt. Területén bronzkori, és sok római kori, valamint honfoglalás kori leleteket találtak.'),
    ('Tokorcs', 'Kemenesalja középső részén, a Cinca-patak mellékén, nem messze a Ság-hegytől és Celldömölk várostól találhatjuk az alig több mint 550 lakosú községet. Határa túlnyomórészt sík vagy enyhén hullámos, mezőgazdasági terület. Délre, a Cinca mentén található a határ legalacsonyabban fekvő része, míg észak-északnyugat felé a felszín fokozatosan emelkedik, és a peremén szőlőhegyekkel, gyümölcsösökkel, majd feljebb erdőkkel borított Cser fennsíkjába olvad át.'),
    ('Tolcsva', 'Tolcsva Magyarország északkeleti részén, Tokajhegyalja középső területén, a Bodrogba folyó Nagy-Tolcsva-patak két oldalán fekszik, Szerencs és Sátoraljaújhely között, 25–25 kilométer távolságra. Öt hegyaljai szőlőtermelő településsel határos. Szomszédai: északon és északnyugaton Erdőhorváti, keleten és délkeleten Sárazsadány, dél-délnyugaton Olaszliszka, nyugaton Erdőbénye, délen Vámosújfalu.'),
    ('Told', 'Természetföldrajzi szempontból a Bihari-sík középső vidékén, a Kutas-főcsatorna partján fekszik. Told nevét 1275 körül említette először oklevél Thold néven helyezkedik el. A falu már a 14. század elején egyházas hely volt. Birtokosai sokáig a Told nemzetségből származó Toldiak vagy Tholdiak ősi birtoka volt. A Toldy családnak Told (Puszta-Told) és Szalonta vidékén voltak birtokai, melyek közül az utóbbit 1515-ben szerezte meg a szomszédos Pata, Kölesér, Őssi helységekkel együtt.'),
    ('Tolmács', 'Tolmács nevét a honfoglalás után egy évszázaddal a Kárpát-medencébe települt egyik besenyő törzsről, a talmácsokról kapta. Az Árpád-korban a Szent János Lovagrendnek volt erődített rendháza a mai Kálváriadomb területén, erre vonatkozó okleveles adat 1274-ből van. Ekkor még nem létezett mai helyén a falu, az csak a 14. században települt oda. A falu 1393-ban a Losonczy család birtokában volt.'),
    ('Tolna', 'Tolna városrésze Mözs, amelyet 1989-ben csatolták Tolnához helyezkedik el. Ez az elmúlt évtizedek egyik utolsó magyarországi településegyesítéseként történt. Közel 11 ezer fős lakosságával a megye ötödik legnépesebb települése. A 16. században ideiglenesen a három részre szakadt Magyar Királyság területén az egyik legnagyobb településsé vált, jelentőségét a tizenöt éves háborúig megőrizte.'),
    ('Tolnanémedi', 'A Tolnai-Hegyhát északi csücskében, a Sió és a Kapos találkozásától délre helyezkedik el. Északon Igarral, északkeleten Simontornyával, nyugaton, délnyugaton Pincehellyel, délkeleten Kisszékellyel és Nagyszékellyel határos.A közeli városok Simontornya (7 kilométer) és Tamási (18 kilométer). Szekszárd 60 kilométer-re, Siófok 60 kilométer-re van. A bronzkorból származó 138 darabos kincslelet a régészek körében világszerte ismert hellyé tette a községet.'),
    ('Tomajmonostora', 'A Tisza-tó vonzáskörzetében fekszik, a Nagykunság középső részén. A közvetlenül szomszédos települések: észak felől Tiszaszentimre, kelet felől Kunmadaras, nyugat felől pedig Abádszalók. Déli irányban a legközelebbi település Kunhegyes, de a közigazgatási területeik nem határosak. A Tomaj férfinév régi magyar személy- illetve nemzetségnévből ered. Jelentése vitatott, talán hallgatag, mogorva.'),
    ('Tomor', 'Szikszótól északra, Edelénytől keletre fekszik, a Vadász-patak mellett. A legközelebbi települések: észak felől Lak, délkelet felől Monaj, nyugat felől pedig Hegymeg, melyekkel az Edelénytől Monajig húzódó 2616-os út köti össze. Továbbá kelet felől Kupa, amely felől földúton érhető el. Határos még északkelet felől Felsővadásszal, délnyugat felől pedig Hangáccsal is, de ezekkel nincs közvetlen közúti kapcsolata.'),
    ('Tompa', 'Tompa közel ötezer lelket számláló, nagy forgalmú nemzetközi közúti határátkelővel rendelkező város a Bácskai-síkvidéken, Bács-Kiskun megye déli részén. A kiskunhalasi kistérséghez tartozik, mintegy 28 kilométerre délre fekszik Kiskunhalastól. A szomszédos települések a határ magyar oldalán: észak felől Kisszállás, kelet felől Kelebia, délnyugat felől Csikéria, nyugat felől pedig Mélykút.'),
    ('Tompaládony', 'Három többé-kevésbé elkülönülő településrésze Pórládony, attól keletre Berekalja és annak is keleti szomszédságában Tompaháza. A közvetlenül határos települések: észak felől Nemesládony, kelet felől Nagygeresd, délkelet felől Vasegerszeg, dél felől Hegyfalu, nyugat felől Mesterháza, északnyugat felől pedig Sajtoskál.'),
    ('Tordas', 'A környező nagyobb települések közül Martonvásártól 3, Érdtől 17, Biatorbágytól 18, Bicskétől 26, Csákvártól 27, Budapesttől pedig kereken 30 kilométerre fekszik. Egyetlen jelentősebb külterületi településrésze Erdőmajor, mely Tordas centrumától 3 kilométerre fekszik északkeletre, a tárnoki határban. A 2001-es népszámlálási adatok szerint Erdőmajor lakónépessége 16 főt tett ki, a lakások száma pedig 4 volt.'),
    ('Tormafölde', 'A község az Ős-Mura völgyében, a Zalai-dombság peremén helyezkedik el, nyugaton a Kerka-patak határolja. Az írásos emlékek előtt ezt a területet összefüggő erdők borították. Később a jobbágyok, zsellérek letelepítésével megkezdődött az erdők irtása. A Vétyempuszta közelében szinte hegyvidékre emlékeztető relifek és őshonos bükkös fogadja a természeti szépségeket kereső látogatót.'),
    ('Tormás', 'Északról Gödre, keletről Baranyaszentgyörgy, délről Bakóca, nyugatról Szágy falu határolja. A megye egyik legősibb települése. A megyeszékhelytől való távolsága 38-40 kilométer. Jellemző és jól kiaknázható az erdő-, valamint a vadgazdálkodás. A település közvetlen közelében található erdőségek értékes fa- és vadállományával, Felső- és Alsókövesden erdészházakkal, az alsókövesdi halastórendszerrel, a nagymátéi vadász vendégházzal a jövőben jelentős turisztikai vonzerőt képezhetnek.'),
    ('Tormásliget', 'Csepregtől 6 kilométerre északkeletre fekszik. A szomszédos települések: észak felől Egyházasfalu, északkelet felől Újkér, kelet felől Iklanberény, délkelet felől Lócs, délnyugat felől pedig Csepreg. Kevés híja van annak, hogy nem határos nyugat felől még Szakonnyal is. A mai község területe a 16. században a Nádasdy család birtoka volt, akik majorságot alakítottak ki itt.'),
    ('Tornabarakony', 'Miskolctól mintegy 90 kilométerre északra, Tornaszentandrás délkeleti szomszédságában fekszik, zsáktelepülés. Ez először Tornaszentandráson halad végig, majd nagyjából 8 kilométer után éri el Tornabarakony központját. Közösségi közlekedéssel a Volánbusz 4124-es járatával közelíthető meg. Tornabarakony nevét az oklevelek 1427-ben említették először, Barakon alakban írva.'),
    ('Tornakápolna', 'Az Északi-középhegységben, azon belül is az Aggteleki-karszttól nem messze, a Galyaságban, az Aggteleki Nemzeti Park területén található kicsiny falu, Aggtelektől körülbelül 10 kilométerre. A háborítatlan környezet vonzó a turisták számára helyezkedik el. A faluhoz legközelebb fekvő települések Jósvafő, Égerszög, Szinpetri, Szőlősardó, Teresztenye és Varbóc, amelyekből – Jósvafő és Szinpetri kivételével – csak kerülőúton érhető el a falu.'),
    ('Tornanádaska', 'A szlovák határ mellett fekszik, Aggtelektől 28, Szögligettől 11 kilométer távolságra kelet-északkeleti irányban. Az országhatár magyar oldalán csak három települési szomszédja van: kelet felől Hidvégardó, dél felől Bódvalenke, nyugat felől pedig Komjáti. Észak felől a legközelebbi település a szlovákiai Tornagörgő (Hrhov). Belterületének központja tekintetében Magyarország legészakibb fekvésű települése.'),
    ('Tornaszentandrás', 'Közösségi közlekedéssel a Volánbusz által üzemeltetett 4124-es busszal közelíthető meg. A település nevét temploma védőszentjéről, Szent Andrásról kapta. A környék már az őskor óta lakott volt. A település a honfoglalás idején jött létre. Neve először egy 1283-ban kiadott adományozó okiratban szerepel először. László király ekkor adományozta Szentandrás falut Vid fia Bengrének.'),
    ('Tornaszentjakab', 'Az Északi-középhegység északi peremén, a szlovák határ mentén helyezkedik el, a Gömör-Tornai karszt területén. Tornanádaskától 10, Miskolctól 80 kilométerre található. Autóbusszal a Volánbusz által üzemeltetett 4136-os járattal közelíthető meg. Jacobus) nevét 1273-ban említették először az oklevelek Zenth Jacab alakban írva. A település Thekus fiainak vásárolt birtoka volt. 1273-ban IV.'),
    ('Tornyiszentmiklós', 'Lentitől 15 kilométerre délre, Letenyétől hasonló távolságra északnyugatra található. Utóbbiból a központjában ágazik ki nyugat felé a 75 333-as út, ami Lendvaújfalu településrész főutcáját képezi, majd onnan továbbvezet az országhatárig és a határ túloldalán, a már Szlovéniához tartozó Pince területére érve 443-as számozással folytatódik, egészen Hársliget (Lipovci) településig.'),
    ('Tornyosnémeti', 'Közúti határátkelőhely Szlovákia felé. Miskolctól északkeletre kb. 63 kilométer-re, a Hernád völgyében fekszik. Közúti határátkelőhely Szlovákia felé. Közigazgatásilag a falu legkorábban a vizsolyi ispánság része volt.'),
    ('Tornyospálca', 'A környező települések közül Jéke 7,5, Kisvárda 12, Kékcse 18,5, Tiszakanyár 24 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Mándok, kelet felől Mezőladány és Újkenéz, délkelet felől Aranyosapáti, dél felől Nyírlövő, délnyugat felől Pap, nyugat felől pedig Jéke és Fényeslitke. Északnyugat felől a legközelebbi település Tuzsér, de közigazgatási területeik nem érintkeznek.'),
    ('Torony', 'A torony olyan álló négy- vagy sokszöghasáb-, esetleg henger alakú, alapterületéhez viszonyítva nagy magasságú építmény, melynek funkciója meghatározza építését, berendezését. Állhat önállóan: zikkurat, minaret, harangtorony (ebben az esetben campanile). Más építményekkel együtt: őrtorony, tűztorony, óratorony, kilátótororny, hídtorony, kaputorony, lakótorony, a vár részeként öregtorony (donzson).'),
    ('Trizs', 'Közigazgatási határának északnyugati széle kevesebb, mint fél kilométernyi távolságra van a szlovák határtól. A szomszédos települések: észak felől Aggtelek, kelet felől Imola, délkelet felől Ragály, dél felől Zádorfalva, délnyugat felől pedig Szuhafő. A legközelebbi szlovákiai település a tőle több kilométerre északra fekvő Kecső. Csak közúton érhető el, Aggtelek vagy Ragály érintésével, mindkét irányból a 2603-as úton.'),
    ('Tunyogmatolcs', 'A megye keleti részén található, a Szatmári-síkságon, a Szamos folyó bal partján. A mai települést a Holt-Szamos szeli át. Az attól is nyugatra fekvő településrész volt Tunyog, míg Matolcs a folyó szabályozása előtti állapotában annak jobb partján feküdt, ma a holtág és az élő folyó által közrezárt területen található. Szomszédai: észak felől Nábrád, kelet felől Fehérgyarmat, dél felől Géberjén, délnyugat felől Győrtelek és Kocsord, nyugat felől Mátészalka, északnyugat felől pedig Szamosszeg és Szamoskér.'),
    ('Tura', 'A Hatvani-síkon, az Alföld és a Mátra találkozásához közel, Budapesttől 50 kilométerre, a megye keleti szélén, a Galga-patak partján helyezkedik el. A hazai vasútvonalak közül a villamosított Budapest…'),
    ('Tuzsér', 'Szomszédai: észak felől Tiszabezdéd, kelet felől Mándok, dél felől Komoró, nyugat felől pedig a Tisza túlsó partján fekvő Zemplénagárd. Tuzsér és környéke már a bronzkorban is lakott hely volt, melyet az ásatások során itt talált bronzkori és honfoglalás kori leletek bizonyítanak: a hajdan itt állt földvár területén bronzkori…'),
    ('Tyukod', 'A Szatmári-síkságon, az ország keleti csücskében, az Ecsedi-láp szélén terül el. Mátészalkától 28 kilométerre délkeletre található. Neve a hajdan személynévként is használt magyar tyúk főnév -d képzős származéka. Az egyetlen település Magyarországon, melynek neve ty betűvel kezdődik (bár Erdélyben van más ty-s település is: Tyéjházcsoport és Tyej).'),
    ('Táborfalva', 'Észak felől tölgyesek, dél felől a Kiskunság homokdűnéi és borókásai veszik körbe. Táborfalvához tartozik a község központjától 4 kilométerre nyugatra fekvő Örkénytábor katonai lakótelep is. Táborfalva új, a történeti időkben ilyen nevű település nem létezett. 1870-ben 394-en lakták a mai településterületen lévő tanyákat. 1875-ben a birtokos…'),
    ('Tác', 'Hírnevét az ország legnagyobb méretű római kori szabadtéri múzeumának, Gorsiumnak köszönheti. A Sárvíz menti homokos síkság kétezer év kultúráját őrzi. Határában 46 régészeti lelőhelyet regisztrálnak. A legjelentősebb ezek közül a belterülettől keletre eső római kori Gorsium. A rómaiak a Dunántúl keleti felének meghódításakor, Kr. u. 46-49. között Sárvíz átkelőhelyét katonai táborral szállták meg.'),
    ('Tákos', 'Tákos első írásos említése 1321-ből való egy perrel kapcsolatban, amely szerint Kállai Ubul feldúlta fia, a Kaplon nemzetség-beli Sándor mester tákosi birtokát. A 15. században a Csarnavodai, Surányi és a velük rokon Makray család révén a Szepesi családbeliek is bírták egy részét. 1488-ban a Csicseri Orosz család is birtokot szerzett a településen. 1500-ban a falu egy részét Murgai János kapta királyi adományként.'),
    ('Tállya', 'A közvetlen szomszédos települések: észak felől Abaújszántó, kelet felől Erdőbénye, délkelet felől Mád, dél felől Rátka és a Szerencshez tartozó Ond, délnyugat felől Monok, nyugat felől pedig Golop. A térség fontosabb települései közül Golop és Rátka 3-3, Mád pedig 7 kilométerre található. A legközelebbi város a 6 kilométerre lévő Abaújszántó.'),
    ('Táp', 'A Sokorói-dombság pannonhalmi vonulatának keleti lejtős részén, az Igmánd–Kisbéri-medence nyugati peremén helyezkedik el. Szerves része a Kisalföld tájegységének, ugyanakkor egyértelmű kapcsolódásai vannak a dombvidékhez is. Autóbusszal a Győr-Tápszentmiklós járaton helyezkedik el. A község településszerkezete, határa jól példázza azt az átmenetet, ami a sík vidék és a dombság kapcsolódását jelenti.'),
    ('Tápióbicske', 'A Tápió-vidék központi területén fekszik. A környék alapvetően síkvidéki jellegű, de a község határában kisebb kiemelkedések is találhatók. Belterületén folyik keresztül az Alsó-Tápió. A legközelebbi település Tápiószentmárton helyezkedik el. A község területe, a régészeti leletek tanúsága szerint, a bronzkortól lakott. Ennek egyik legjelentősebb bizonyítéka egy 18 karátos holdsarlós végű arany karpánt, amely a középső bronzkorból (Kr. e. 1600–1450) származik, és a helyi bronzkori kultúra kiemelkedő ékszerleleteként került elő.'),
    ('Tápiószecső', 'Az Alföld északi részén helyezkedik el, közel a Gödöllői-dombsághoz, a Tápió-Galga-Zagyva vidéken, kistérség szerint a Tápió-vidéken, Budapesttől 27 kilométer-re keletre. A közvetlenül határos települések: észak felől Kóka, északkelet felől Tóalmás, kelet felől Szentmártonkáta, délkelet felől Tápióság, délnyugat felől Úri, nyugat felől pedig Sülysáp.'),
    ('Tápiószele', 'Ceglédtől észak-északkeletre, Nagykátától délkeletre fekszik, a megye keleti szélén. Kiterjedt külterületei révén határos észak felől Jászberénnyel, északkelet felől Jászboldogházával, kelet felől Tápiógyörgyével, délkelet felől Újszilvással, dél-délnyugat felől Tápiószőlőssel, nyugat felől Tápiószentmártonnal, északnyugat felől pedig Farmossal is, de ezek közül nincs mindegyikkel közvetlen, kiépített közúti kapcsolata.'),
    ('Tápiószentmárton', 'Az Alsó-Tápió-mente legnagyobb lélekszámú faluja, Nagykáta déli szomszédságában helyezkedik el. A közvetlenül határos települések: észak felől Nagykáta, északkelet felől Farmos, kelet felől Tápiószele, délkelet felől Tápiószőlős, dél felől Cegléd és Ceglédbercel, délnyugat felől Albertirsa, nyugat felől Pánd, északnyugat felől pedig Tápióbicske.'),
    ('Tápiószőlős', 'A falu központja, ahol a Polgármesteri Hivatal is található kb. 2 kilométer-re van a helységtáblától. Földrajzilag a Gerje–Perje-sík része. Újszilvás, Tápiószele, Tápiószentmárton, Cegléd. A település – amely több mint fél évszázada önállósult – területén az időszámítás és a honfoglalás előtt különböző nomád népek éltek: a szkíták, a szarmaták és az avarok a kedvező földrajzi környezet miatt telepedtek le.'),
    ('Tápióság', 'Tápióság jelenlegi közigazgatási területét már jóval az időszámítás kezdete előtt lakták, amelyet jól bizonyítanak a Zsigerpusztán és a Cimbál-réten előkerült bronzkori leletek. A falu 1241-ig a Cimbál-réten volt, ekkor a tatárok elpusztították. 1242 után a Tápió kanálisa, a sió vagy ság csatorna mellé települt át. Az Öregfalu és a templom a völgynek a malommal szemközti oldalán épült fel.'),
    ('Táplánszentkereszt', 'A mai település Táplánfa és Gyöngyösszentkereszt egyesítésével jött létre, de a történelmi időkben 7, sőt talán annál is több különálló kis falu létezett a területén, s ezek elkülönülése még ma is hellyel-közzel felismerhető. A Gyöngyös-sík déli-középső részén, a Gyöngyös-patak két partján terül el, a megyeszékhely Szombathely délkeleti szomszédságában, a város központjától 7,5 kilométerre.'),
    ('Tápszentmiklós', 'A Sokorói-dombság déli, az Igmándi-Kisbéri medence nyugati peremén helyezkedik el. Kapcsolata egyértelmű a Bakony tájegységgel. Felszíne változatos. Az alacsony dombokat és a köztük lévő völgyeket homokos, agyagos-löszös, üledék borítja. Győrtől 27 kilométer távolságra, délkeletre fekszik. Vasúton korábban elérhető volt a Tatabánya–Pápa-vonalon, de itt 2007-ben megszűnt a személyforgalom.'),
    ('Tárkány', 'Hozzá tartoznak Vasdinnyepuszta és Vadasmajor településrészek is. Jelenleg azonban a két megállóhely egyikén sincs személyforgalom. Egy, a település határában talált, zsugorított pózban eltemetett férfi több ezer éves sírja a mellette talált kőeszközökkel arra utal, hogy e tájon az ember már a mezolitikum idején megtelepedett. 1237-ből származó, első okleveles említését egy 1221-es keltezésű határjáró levélben találjuk, Tarcan alakban.'),
    ('Tárnok', 'Budapesttől 20 kilométerre, az Érd-Sóskúti-fennsík és az Érd–Ercsi-hátság határán, a Dunába torkolló Benta-patak két partján helyezkedik el. Közeli települések: Sóskút, Érd és Martonvásár. (A szomszédos Érd városával szinte teljesen összeépült.) A belterület három nagyobb részből áll. A legrégebbi a Falu, központjában az orsósan kibővülő, széles főutcával.'),
    ('Tárnokréti', 'Magyarország északnyugati részén, a Hanság szélén, a Tóközben, a Rábca mellett helyezkedik el. Csak közúton érhető el, Lébény vagy Rábcakapi érintésével, a 8528-as úton. A település környéke már a római időkben is lakott hely lehetett. Határán vezet keresztül az egykori római hadiút. Területe egykor győri és mosoni várföld volt, ahol a vár szolgái éltek.'),
    ('Táska', 'A Balatontól délre fekszik, nagyjából félúton Lengyeltóti és Marcali között, mindkettőtől körülbelül 12-13 kilométerre. Központján a Lengyeltóti-Nikla közti, a 6701-es és 6704-es utakat összekötő 6708-as út halad keresztül, ezen érhető el Marcali és a Balaton térsége felől is. A települést írott forrás először 1268-ban említi. A török hódoltság idején valószínűleg elnéptelenedett.'),
    ('Tát', 'A település a Kis-Duna mellett fekszik, északról az ősi folyó ágai ölelik, míg délről a Gerecse dombjai koszorúzzák. Az egykori fővárostól, Esztergomtól 8 kilométerre, Budapesttől 45 kilométerre található. Vonattal elérhető az Esztergom–Almásfüzitő-vasútvonalon, amelynek egy megállási pontja van itt. Tát megállóhely a központ közelében helyezkedik el, de közúti elérését csak önkormányzati utak biztosítják.'),
    ('Tázlár', 'A település a Kiskunság déli részén helyezkedik el. A szomszédos települések: észak felől Bócsa, kelet felől Szank, délkelet felől Kiskunmajsa és Harkakötöny, dél felől Kiskunhalas, délnyugat felől Pirtó, nyugat felől pedig Soltvadkert. Csak közúton közelíthető meg, Soltvadkert és Kiskunmajsa felől egyaránt a Szegedre vezető 5405-ös úton, Kiskunhalas irányából pedig az 53-as főútból Pirtótól délre kiágazó 5406-os úton.'),
    ('Téglás', 'A közvetlen szomszédos települések: észak felől Újfehértó, kelet felől Bököny, dél felől Hajdúhadház, nyugat-északnyugat felől egy-egy rövidebb szakaszon Hajdúböszörmény és Hajdúdorog külterületeivel is érintkezik.'),
    ('Tékes', 'A Baranyai-hegyháton fekvő zsáktelepülés Dombóvártól mintegy 9, Komlótól 15 kilométerre helyezkedik el. Erdőkkel övezett csendes falu. A 18. században a király Esterházy Pálnak adományozta a falu. Részben ennek hatására az 1700-as évek végén német telepesek költöztek a faluba.'),
    ('Tényő', 'A Kisalföld délkeleti peremén húzódik a Sokorói-dombság néven ismert löszös, homokos talajú dombvidék, a Bakony legészakibb nyúlványa. A Ravazd-Csanaki és a Sokorói dombsorok közötti völgyben található Tényő, a tájegység egyik legszebb természeti környezetű községe. Tényő településszerkezete nem mutat semmiféle rendezettséget. Régebben a falu lakói elsősorban a dombsorok között húzódó kis völgyekbe építették házaikat.'),
    ('Tépe', 'Berettyóújfalutól északra, Derecskétől délre, a Kálló vize mellett fekszik. A két említett városon felül csak egy harmadik települési szomszédja van: délkelet felől Szentpéterszeggel határos. Szentpéterszeggel egy számozatlan mezőgazdasági út köti össze. Tépe ősi nemesi birtok volt, melyet már 1311-ben említettek a korabeli oklevelek Thepa néven. A falu ekkor Dósa nádor birtoka volt.'),
    ('Tésa', 'Tésa az Ipoly-mente legkisebb települése Magyarország és Szlovákia határán, az Ipoly balpartján, a Börzsöny völgyében helyezkedik el. Belterülete 61, külterülete 442 hektár. A határ túloldalán Ipolyszakállos, Szete és Lontó található. Délkeletről Kemence és Perőcsény határolják. Utóbbi csak a belterületének északi szélét érinti, központjába az abból kiágazó 12 116-os út vezet.'),
    ('Tésenfa', 'A horvát határ és a Dráva mellett (a folyótól mintegy 2,5 kilométerre), a Fekete-víz közvetlen közelében helyezkedik el. A szomszédos települések: északkelet felől Drávacsepely, kelet felől Drávacsehi, nyugat felől Szaporca, északnyugat felől pedig Kémes. Dél felől a legközelebbi település a horvátországi Alsómiholjác. A településre parasztházainak egyszerűsége a legjellemzőbb.'),
    ('Téseny', 'Pécstől délnyugatra fekszik, a szomszédos települések: észak felől Velény, kelet felől Baksa, délkelet felől Tengeri, dél felől Bogádmindszent, délnyugat felől Ózdfalu, nyugat felől Kisasszonyfa, északnyugat felől pedig Gerde. Csak közúton érhető el, Baksa vagy Kisasszonyfa felől, az 5803-as úton. Az egyutcás kis településen és környékén már a kőkorszakban és a bronzkorban is laktak emberek, lakóhelyük nyomait a falu határában tárták fel.'),
    ('Tét', 'A sokoróaljai térségben központi funkciót lát el. Magyarország északnyugati, a Kisalföld délkeleti részén helyezkedik el, Győr és Pápa között nagyjából félúton. Valamikor idáig húzódott a Bakony erdőségeinek határa. A közvetlenül határos települések: észak felől Koroncó, északkelet felől Győrszemere, kelet felől Felpéc, délkelet felől Gyömöre, délnyugat felől Mórichida, nyugat felől Rábaszentmiklós, északnyugat felől pedig Kisbabot és Rábaszentmihály.'),
    ('Tóalmás', 'Tura–Zsámbok útvonalon helyezkedik el. Első okleveles említése 1406-ból való, Almásként. Az Árpádok alatt a jánoshidai premontrei apátság birtoka. Mint település, már a XI–XII. században létezett. Erre utalnak a régi templom maradványai: a várfalszerű széles talapzat – melyre a jelenlegi templom épült – és a körülötte fellelt emberi maradványok. Bizonyítékul szolgál még, hogy a Poklos-dombon (Várhegy) földvár nyomai tűnnek elő, körülötte cserépedény-törmelékekkel.'),
    ('Tófalu', 'Területe hordalékkúp-síkság, a tengerszint feletti magasság jellemzően a 200 métert sem éri el. Az éves csapadék 550–600 mm, az évi középhőmérséklet 10 °C, az évi napsütéses órák száma 1950-2000. A gyenge lefolyású terület vizeit a Tarna és a Kígyós-patak gyűjti össze. A természetes növényzet elsősorban lágyszárú fajokból áll. Erdőterülete csekély.'),
    ('Tófej', 'A település a 75-ös főúttól délre fekszik, a Bak-Páka közti 7543-as út mentén. A falu a hagyományok szerint nevét a falu melletti egykori tóról kaphatta. A régi falu nem a mai helyén állt, azonban a török idők alatt a falut többször is támadás érte, különösen Kanizsa török kézre kerülése után, és templomával együtt elpusztult, majd később mai helyén épült újjá.'),
    ('Tófű', 'Baranya megye északi határa mentén helyezkedik el, Pécstől északkeletre, Egyházaskozár és Szászvár között. Tófű nevét az oklevelek 1382-ben említették először, Thofew alakban írva. Nevét valószínűleg a közeli tóról kaphatta. A török időkben elnéptelenedett faluba a törökök kiűzése után szerbek költöztek, majd a 18. század elején német telepesek érkeztek ide.'),
    ('Tószeg', 'A szomszédos települések: észak felől Szolnok, kelet felől a városhoz csatolt Szandaszőlős, délkelet felől Rákóczifalva (e két utóbbi a Tisza túlpartján), dél felől Tiszavárkony, délnyugat felől Jászkarajenő, nyugat felől Kőröstetétlen, északnyugat felől pedig Abony. A Tiszán felül nagyobb élővize még a településtől északra a folyóba ömlő Gerje-Perje főcsatorna.'),
    ('Tótkomlós', 'A Dél-Alföldi turisztikai régióban, a Csongrádi-síkon, a Maros-hordalékkúp részének hátsági területén fekszik, a tengerszint felett 92 méterrel, Orosházától 18 kilométerre délre. Szomszédai: észak felől Pusztaföldvár, északkelet felől Kaszaper, kelet felől Végegyháza, délkelet felől Mezőhegyes, dél felől Nagyér és Ambrózfalva, délnyugat felől Makó, nyugat felől Békéssámson, északnyugat felől pedig Kardoskút.'),
    ('Tótszentgyörgy', 'Szigetvár nyugati vonzáskörzetében helyezkedik el, a város központjától mintegy 7 kilométer távolságra. A szomszédos települések: északkelet felől Patapoklosi, délkelet felől Molvány, délnyugat felől Nemeske, északnyugat felől pedig Merenye. Központja vonatkozásában azonban zsáktelepülésnek tekinthető, oda közúton csak egy bő másfél kilométeres bekötőúton, a 66 115-ös számú mellékúton lehet eljutni.'),
    ('Tótszentmárton', 'Utcanevek: Alkotmány, Arany János, Béke, Dózsa György tér, József Attila, Petőfi Sándor, Rákóczi Ferenc, Szent Márton utca A zágrábi püspöki lajstrom szerint Szentmárton már 1334-ben önálló plébánia volt, más adatok szerint első temploma 1337 illetve 1344 körül épült fel. Annyi azonban biztos, hogy a templom felszentelése Nagy Lajos király uralmának idejére esett. 1539-ben a Zichy családbeliek és özv.'),
    ('Tótszerdahely', 'A településen polgárőrség működik. A község Nagykanizsától délnyugatra, a (Nagykanizsa-)Murakeresztúr-Letenye közti 6835-ös út mellett fekszik. Délről Horvátországgal és a Murával határos, északi szomszédja Tótszentmárton, amellyel az innen Becsehelyig húzódó 6836-os út köti össze. Környéke kedvesen lankás, enyhén dombos. A mai Tóthszerdahely területén a kilencedik századból származó telepek nyomát találták régészek.'),
    ('Tótvázsony', 'Az 1200 lelkes falutól északra a Balaton-felvidék nyúlványát képező Csatár-hegy, és hegyes-völgyes erdővonulatok találhatók. Határát átszeli a Vázsonyi-Séd patak. A település északon Szentgál, nyugaton Nagyvázsony és Barnag, keleten Nemesvámos és Hidegkút földterületeivel határos, délen Pécselyen, Balatonszőlősön és Aszófőn át érjük el a Balatont.'),
    ('Tótújfalu', 'A szomszédos települések a határ magyar oldalán: északnyugat felől Drávagárdony, észak felől Potony, kelet felől Lakócsa, délkelet felől pedig Szentborbás. A határ túloldalán a legközelebbi település a horvátországi Detkovac (Detkovac). Egy rövid szakaszon a határszélét követve húzódik az 5825-ös út Szentborbás és Lakócsa közti szakasza, de a községhez tartozó lakott helyeket nem érint.'),
    ('Tök', 'A Budai-hegység lélekszám szempontjából legkisebb települései közé tartozik. Különlegessége még a környező településekkel összevetve az is, hogy nagyon kevés kivételtől eltekintve csak magyar nemzetiségű és református lakói vannak. A Budai-hegység egyik legjobb bortermő települése, a hosszú időkre visszatekintő helyi szőlész-borász hagyományokról a település szinte minden részén megtalálható, gyakran már muzeális jellegű, de ma is használatban tartott pincék árulkodnak.'),
    ('Töltéstava', 'Győr délkeleti szomszédságában fekszik, mint a megyeszékhelyet délről övező agglomerációs gyűrű egyik települése, a város központjától 9 kilométer távolságra. Különálló településrésze Táplánypuszta, a központjától bő 2 kilométerre északra helyezkedik el. A közvetlenül határos települések: észak felől Győrszentiván (Győr része), északkelet felől Bőny, kelet felől Pér, délkelet felől Pázmándfalu, dél felől Győrság, délnyugat felől Nyúl, nyugat felől Győrújbarát, északnyugat felől pedig Kismegyer (szintén Győr része).'),
    ('Tömörd', 'Kőszegtől 12 kilométerre délkeletre fekszik. A szomszédos települések: észak felől Csepreg, délkelet felől Meszlen, dél felől Vasasszonyfa, délnyugat felől Kőszegpaty, északnyugat felől pedig Kiszsidány. Határában őskori (neolit, rézkor, vaskor) település nyomait tárták fel 1905-ben egy kisebb ásatás során helyezkedik el. A római korból többek között bronzérmek, fibulák kerültek elő. 1978-ban egy hét méter átmérőjű salakhalmot találtak, ahol Árpád-kori kohó nyomaira bukkantak.'),
    ('Tömörkény', 'Csongrádtól délnyugatra, Csanytelek, Pusztaszer és Kiskunfélegyháza közt helyezkedik el. Szomszédai: észak felől Felgyő, kelet felől Csanytelek, délkelet felől Baks, dél felől Ópusztaszer, délnyugat felől Pusztaszer, nyugat felől Pálmonostora, északnyugat felől pedig Gátér. Tömörkény nevét 1326-ban említették először az oklevelek, Temerkenként. A település a Bor-Kalán nemzetséghez tartozó Szeri Pósafiak, Pósa és Pál birtoka volt.'),
    ('Törtel', 'Északon Abonnyal, keleten Kőröstetétlennel, Jászkarajenővel, délen Kocsérral, Nagykőrössel, Nyársapáttal, nyugaton Cegléddel határos. Törtel a főbb útvonalaktól távol helyezkedik el, központjában két, négy számjegyű út, a 4609-es és a 4611-es utak keresztezik egymást. Az előbbi Cegléddel, Kőröstetétlennel, Jászkarajenővel és Tiszajenővel, utóbbi pedig Abonnyal és Nagykőrössel biztosít a településnek közúti összeköttetést.'),
    ('Törökbálint', 'Gazdag történelemmel rendelkezik, és kedvező földrajzi elhelyezkedése miatt vonzó a lakosság és a gazdasági szereplők számára egyaránt. A város területe már a római korban is lakott volt, azonban a település első írásos említése a középkorból származik. Nevét a török hódoltság időszakában kapta, a 16. században a törökök stratégiai pontként használták a környéket, innen ered a város mai neve is.'),
    ('Törökkoppány', 'A központján a Nagykónyi-Somogyacsa között húzódó, a 61-es főutat a 6505-ös úttal összekötő 6508-as út halad végig. Törökkoppány elődje, Koppány Árpád-kori település. Feltehetően Koppány fejedelem idején a somogyi hercegség egyik igazgatási központja volt, Somogyvár mellett. Nevét már 1138-ban említette oklevél „Villa Cuppan” írásmóddal. Az 1332–1337 évi pápai tizedjegyzékben Koban alakban írva fordult elő.'),
    ('Törökszentmiklós', 'A Tiszától nem messze, a mezőgazdaságáról híres Nagykunság területén fekszik, jelentős közlekedési csomópont a régióban. Törökszentmiklós Szolnoktól 20 kilométerre keletre, a Szolnok–Túri-síkon és a Nagykunság szélén helyezkedik el. Északról természetes határként a Tisza, valamint annak fegyverneki holtága határolja, szomszédos továbbá Fegyvernek, Örményes, Kuncsorba, Kétpó, Tiszatenyő, Szajol, Tiszapüspöki településekkel is.'),
    ('Túristvándi', 'Szomszédai: észak felől Szatmárcseke, kelet felől Kölcse, délkelet felől Fülesd, délnyugat felől pedig Kömörő, nyugat felől Szatmárcsekéhez tartozó lakatlan külterületek határolják. Mátészalkától 33, Tiszabecstől 17, Fehérgyarmattól pedig 15 kilométer távolságra található. Az Istvándi nevet birtokosáról, a Kölcsei nemzetség egyik tagjáról kapta. Ekkor a Czégényi monostor területéhez tartozott a település. 1315-ben a Kölcsei nemzetség…'),
    ('Túrkeve', 'A helybeliek szóhasználatában Túrkevi vagy egyszerűen Kevi. Szomszédos települések Mezőtúr és Kisújszállás. A város híres gyógyfürdőjéről, fesztiváljairól (elsősorban a Kevi Juhászfesztiválról), valamint gasztronómiai különlegességeiről. Ezek miatt a várost évről évre számos magyar és külföldi (főleg német) turista keresi fel, ami a mezőgazdaság mellett a település lakosainak egyik legfontosabb bevételi forrása.'),
    ('Túrony', 'A Villányi-hegység nyugati oldalán helyezkedik el, Siklóstól légvonalban 8, közúton 10 kilométerre északnyugatra, Pécstől 20 kilométerre délre, Harkánytól 6 kilométerre északra. A szomszédos települések: észak felől Szalánta, kelet felől Bisse, délkelet felől Máriagyűd, dél felől Harkány, délnyugat felől Csarnóta, északnyugat felől pedig Garé. A község már az újkőkorszaktól kezdve lakott, amikor a dunántúli vonaldíszes kerámia népei, majd a bronzkori mészbetétes kerámia népei éltek itt.'),
    ('Túrricse', 'Szomszédai: délkelet felől Tisztaberek, dél felől Gacsály, délnyugat felől Kisnamény, nyugat felől pedig Csaholc. Észak, északkelet és kelet felől részben Csaholchoz, részben Tisztaberekhez tartozó lakatlan külterületek határolják. A két legközelebbi település Csaholc és Tisztaberek, egyaránt körülbelül 3-4 kilométerre helyezkedik el. A térség más fontosabb települései közül Rozsály 12, Zajta 14,5, Gacsály 14, Császló 19, Csegöld pedig 23 kilométer távolságra található.'),
    ('Türje', 'A településen polgárőrség működik. Türje megállóhely a Boba–Bajánsenye-vasútvonalon található, ahol Zalaegerszeg és Celldömölk között közlekedő személyvonatok állnak meg (ezek közül néhány vonat Celldömölktől Győrön át gyorsvonatként tovább…'),
    ('Tüskevár', 'Devecser és Jánosháza között helyezkedik el, a két város között nagyjából félúton. A közvetlenül határos települések: észak felől Iszkáz, kelet felől Somlójenő, dél felől Káptalanfa, nyugat felől Apácatorna, északnyugat felől pedig Karakószörcsök. A község eredeti neve Nagyjenő, mely név a honfoglalás kori Jenő törzsre utal. A Tüskevár nevet 1657-ben kapta a török háborúkban épült tüskével védett erődítésről.'),
    ('Udvar', 'Határátkelő Horvátországba. Udvar környéke már a római korban is lakott volt, itt ment keresztül a régi Aquincum és Mursa közötti római hadiút. Nevét 1448-ban Wdwarth formában írták. A falu helyén egykor kastély vagy udvarház állhatott, valószínűleg onnan kaphatta nevét. A település a török időket nem vészelte át, elpusztult. A 18. században német lakosokkal települt újra a falu.'),
    ('Udvari', 'A Dunántúli-dombságban, a Tolnai-Hegyháton, a Kapos és a Sió között fekszik, a megyeszékhelytől, Szekszárdtól mintegy 50 kilométerre. Szomszédos települések: Miszla és Gyönk. Zsáktelepülés, csak a 63 119-es számú mellékúton érhető el Gyönk irányából. Elérhető még Belecska felől is, Miszla érintésével, de ez az útvonal változó burkolatminőségű, némely szakaszain burkolatlan helyezkedik el.'),
    ('Ugod', 'A település az Északi-Bakony nyugati lejtőin fekszik, gyakorlatilag a Kisalföld és a Bakony találkozásánál. Az ország nyugati felének nagyobb városai, illetve turisztikai célpontjai közül Budapesttől mintegy 150, Veszprémtől és Győrtől egyaránt 60-60, Pápától 15, a Balatontól pedig nagyjából 70 kilométerre fekszik.'),
    ('Ukk', 'A Marcal-medence déli részén fekszik, a Marcal folyó jobb (keleti) parti oldalán. A közvetlenül határos települések: észak felől Rigács és Zalameggyes, északkelet felől Hosztót, kelet felől Csabrendek, dél felől Zalagyömörő, délnyugat felől pedig Gógánfa. Északnyugat felől a legközelebbi település Megyer, de a közigazgatási területeik – bő fél kilométer híján – nem érintkeznek.'),
    ('Und', 'A népesség kb. 60%-a horvát nemzetiségű, de sokan közülük egyúttal magyarnak is vallják magukat. Az Alpokalján, a mai országhatár közvetlen közelében helyezkedik el. Egyutcás, fésűs beépítésű település. Mindössze két települési szomszédja van: kelet felől Sopronhorpács, délnyugati irányból pedig Zsira. A legközelebbi városok: Csepreg, Bük és Kőszeg.'),
    ('Uppony', 'Ózdtól 14 kilométerre keletre, a Bükk-vidék területén, az Upponyi-hegység vonulatai között, a Csernely-patak völgyében fekszik. Az út a Lázbérci Tájvédelmi Körzet létrehozatala előtt továbbvezetett Dédestapolcsányig, de az a szakasza jelenleg csak korlátozott forgalmú erdészeti útként funkcionál.'),
    ('Ura', 'A környező települések közül Csengerújfalu 2, Csenger 8, Tyukod 5, Nagyecsed 14, Porcsalma pedig 12 kilométer távolságra található. Ura nevét 1374-ből említik először az ismert oklevelek, ekkor Wra alakban írták. A település ősidők óta az Uray családé volt, bár 1646-ban báró Károlyi Ádám is részbirtokos volt Urán. Az 1900-as évek elején gróf Tisza Istvánnak, Uray Bálintnak és báró Uray Margitnak volt itt birtoka.'),
    ('Uraiújfalu', 'A Nyugat-magyarországi peremvidéken, a Sopron-Vasi-síkság közepén, a Rába bal oldalán, a Kőris-patak mellett fekszik. A szomszédos települések: északkelet felől Nick, kelet felől Csönge, délkelet felől Ostffyasszonyfa, dél felől Jákfa, nyugat felől Vasegerszeg, északnyugat felől pedig Vámoscsalád. Közigazgatási területe kelet felől egy rövid szakaszon érintkezik még a fentieken túlmenően Kenyeri határszélével is.'),
    ('Uszka', 'A megye keleti részén, a Szamosközben fekszik, közvetlenül az ukrán-magyar országhatár mellett. A határ magyar oldalán csak három településsel határos: a szomszédai északnyugat felől Tiszabecs, dél felől a mindössze 2 kilométerre fekvő Magosliget (ez utóbbi a legközelebbi szomszédja), délnyugat felől pedig még érintkezik a területe Botpalád határszélével is.'),
    ('Uszód', 'Külterületei messze elnyúlnak kelet felé, így abban az irányban határos Dunapatajjal, Géderlakkal és Szakmárral is. A településen, annak főutcájaként a Dunapataj-Kalocsa közt húzódó 5106-os út húzódik végig, így ez a legfontosabb közúti elérési útvonala. Uszód mai formájában már a 16. században fennállt. 1599 tavaszán a dunai naszádosok, a hajdúk támogatásával, Pálffy Miklós vezérlete alatt fényes győzelmet arattak a törökökön, akiknek élelemszállító hajóit Foktő és Uszód között szétverték.'),
    ('Uzsa', 'A Bakony és a Keszthelyi-fennsík között fekszik, a Lesence-patak völgyében, a Balatontól 13 kilométerre északra. Különálló településrészei Erdésztelep és Vasútastelep, előbbi a központjától 1,5, utóbbi 3 kilométerre északra helyezkedik el. Mindössze három településsel határos közvetlenül: a szomszédai észak felől Sümeg, dél felől Lesenceistvánd, nyugat felől pedig Várvölgy (kelet felől lesenceistvándi külterületek határolják).'),
    ('V. kerület', 'Az V. kerület, vagy hivatalos nevén Belváros-Lipótváros a magyar főváros, Budapest egyik történelmi kerülete, amely a Duna bal partján, Pesten fekszik. A főváros szíve, sok tekintetben Budapest, illetve Magyarország közigazgatási, hivatali, kereskedelmi és turisztikai központja. Északon a XIII. kerület, nyugaton a Duna által az I. kerület és a II. kerület, délen a IX. kerület, míg keleten az VI. kerület, a VII. kerület és a VIII. kerület határolja.'),
    ('Vadna', 'A település a Sajó folyó és a Bán-patak összefolyásától délkeletre fekszik, a Sajó-völgy kistájon, 141 méteres tengerszint feletti magasságban. Délről a Tardonai-dombság, délnyugatról az Upponyi-hegység, északról a Putnoki-dombság határolja. A környező települések: északkelet felől Sajókaza, kelet felől Sajóivánka, dél felől Nagybarca, nyugat felől Sajóvelezd, északnyugat felől pedig Sajógalgóc.'),
    ('Vadosfa', 'Magyarország északnyugati részén, Kapuvártól délre helyezkedik el. Útelágazásban fekvő, két templomot körülvevő, zárt település, különleges települési formákkal. Mindössze három szomszédja van: északnyugat felől Mihályi, északkelet felől Magyarkeresztúr, délnyugat felől pedig Beled. Délkeleti irányból a legközelebbi település Páli, de közigazgatási területeik nem érintkeznek.'),
    ('Vaja', 'Különálló településrésze az északi határszéle közelében Rákóczitanya. A térség fontosabb települései közül Rohod 3, Őr 4, Jármi 9,5, Mátészalka 14,, Vásárosnamény pedig 20 kilométer távolságra található. A szomszédos települések: észak felől Nyírmada, északkelet felől Pusztadobos, kelet felől Nyírparasznya, délkelet felől Papos, dél felől Őr, délnyugat felől Kántorjánosi, nyugat felől Baktalórántháza, északnyugat felől pedig Rohod.'),
    ('Vajdácska', 'A megyeszékhelytől, Miskolctól 83 kilométerre északkeletre helyezkedik el, a Bodrogközben. A legközelebbi város Sárospatak, melytől légvonalban 7, közúton mintegy 9 kilométerre fekszik keleti irányban. Első alkalommal 1308-ban említi a települést egy oklevél Voyda néven helyezkedik el.'),
    ('Vajszló', 'A település patakja a Fekete-víz. A község neve szláv eredetű személynévből, Wojislav, Voyzlow, Wohwslo, Woyzd, vagy Vayzlo, esetleg Vojislav, vagy Vojslav alakulhatott ki. A falu horvát neve hivatalosan Vajslovo, amelyet a drávasztárai horvátok használtak, a Vajslov alakot a szalántai–németi horvátok használták. Az Árpád-korban a közelében vár állhatott, mert írásos forrás még 1257-ben is említi.'),
    ('Vajta', 'A megye és az egész Közép-Dunántúl régió legdélebbi települése. A környező települések közül Bikács 5,5, Cece 6,5, Németkér 7, Simontornya 13, Sárbogárd pedig 16 kilométer távolságra található Vajtától. Nevét feltehetően arról a Vajta besenyő vezértől kapta, aki a Gesta Hungarorum szerint még Kijev alatt csatlakozott a magyarokhoz. Vajta nemzetsége egy részével a Sárvíz mellékén Anonymus szerint "számtalan néppel" letelepedett.'),
    ('Valkonya', 'Valkonya egy kis zsáktelepülés Nagykanizsától légvonalban 14 kilométerre nyugat-északnyugat irányban helyezkedik el. Közúton csak Becsehely felől érhető el, a 7536-os útból kiágazó 75 136-os úton. Lankás domboldalakkal körülvett völgyben fekszik festői környezetben. Valkonya neve a szláv Volkona személynévből alakult, amely a régebbi Vlkonja – vlk szóból ered, jelentése farkas.'),
    ('Valkó', 'A 3-as főútról Gödöllőnél letérve 14 kilométer után érhetjük el legkönnyebben. Nevét egy szláv eredetű személynév után kapta, melynek jelentése farkas. Mint minden közösségben, itt is találhatunk a település nevéhez kapcsolódó népmondát: Régen Valkó helyén nem volt más, mint egy hatalmas erdő. Senki nem lakott itt, csak az állatok. Egyszer erre tévedt egy öregember.'),
    ('Vanyarc', 'A Cserhát déli részén fekszik, Budapesttől mintegy 70 kilométerre. A Novohrad-Nógrád UNESCO Globális Geoparkhoz tartozik. A legközelebbi települések Bercel, Kálló, Szirák és Acsa, de közvetlen közúti kapcsolata csak az első hárommal van. A település és környéke már az őskorban is lakott hely volt.'),
    ('Vanyola', 'Pápától északkeletre fekszik. A szomszédos települések: észak felől Lovászpatona, kelet felől Bakonyság és Bakonyszentiván, dél felől Csót, nyugat felől Vaszar. Közigazgatási területe délnyugaton egy ponton érintkezik Nagygyimót határszélével is. Vanyola nevét 1222-ben a pannonhalmi apátság oklevele említi először az ismert források közül. A török hódoltság idején többször is elnéptelenedett, de később mindig újranépesült.'),
    ('Varbó', 'Miskolctól északnyugatra fekszik, a Tardonai-dombság területén, a Nyögő-patak völgyében. A további szomszédos települések: északkelet felől Kondó, kelet felől Parasznya, nyugat felől pedig Mályinka és Tardona. Határszélét délnyugaton érinti még a Miskolcról Dédestapolcsányra vezető 2513-as út is. Címerében egy faágon álló galamb látható, mely csőrében ágacskát tart.'),
    ('Varbóc', 'Kazincbarcikától 28 kilométerre, Aggtelektől pedig 13 kilométerre fekszik. A falu fölött északon a 327 méter magas Hársas-hegy, északnyugaton a 411 méter magas Bérctető, nyugaton a 337 méter magas Borháztető, délnyugaton a 313 méter magas Bokánytető, míg délen a 311 méter magas Szarvas-hegy emelkedik. Külterületi lakott helye: Lászitanya. A kezdetekre – mint a környékbeli többi falu esetében is – inkább nevéből következtethet a kutató, mely ószláv nyelven „füzest” jelent.'),
    ('Varga', 'Pécstől mintegy 30 kilométerre északra fekszik, Sásd délkeleti szomszédságában. Zsáktelepülés, közúton csak a 66-os főútból, annak 27. kilométere előtt keletre kiágazó 65 189-es számú mellékúton érhető el, Felsőegerszeg érintésével. Varga település nevét 1542-ben említették először az oklevelek Warga alakban írva. Neve foglalkozásra utal. Egykor sok varga foglalkozású élt a településen helyezkedik el.'),
    ('Varsád', 'A település neve először egy a pápai tizedjegyzék alapján készült 1330-as térkép, térképvázlaton szerepelt, tehát már az 1200-as években létezett. Bár ekkor még nem bizonyított, hogy szilárd építésű temploma is lett volna, de a Tolna megyei faluhálózathoz tartozott. A régi dokumentumok szerint a környék faluhálózatának kialakulása a fejedelmek korában, a Honfoglalás idején kezdődött.'),
    ('Varsány', 'Északról Szécsény, keletről Rimóc, délről Nógrádsipek, nyugatról Csitár, illetve Iliny határolja. A településtől, amely a Novohrad-Nógrád UNESCO Globális Geoparkhoz tartozik, nem messze fut a Darázsdói-patak. Érinti a település közigazgatási területét a Szécsényből Rimócra vezető 21 133-as út is, de a belterületi községrészeket nem közelíti meg. Régészeti ásatások szerint Varsány területe már a honfoglalás korszaka előtt is lakott volt.'),
    ('Varászló', 'Keleti szomszédja Nemesdéd település. Nevét 1278-ban Warazlou alakban említették először. 1417-ben már részben a Kanizsai család birtoka volt. Ekkor Kanizsai Miklós özvegye a Radóiaktól és Szentpáli Varászló Miklóstól szerzett itt birtokrészeket.'),
    ('Vasad', 'A futóhomok borította sík felszínt csak néhány helyen teszi változatossá egy-egy homokhalom, melyeket a helyiek rendre „hegyként” aposztrofálnak (Gados-hegy, Templom-hegy, Rózsa-hegy, Pipis halom). Az ősi Duna hordalékaként keletkezett futóhomok talajú község külterületének jelentős részét fenyő-, nyár- és akácerdő borítja, a fák között pedig tanyák sokasága búvik meg.'),
    ('Vasalja', 'Az osztrák határ közelében helyezkedik el, Körmendtől 5 kilométerre nyugatra, a Pinka patak partján. A szomszédos települések: kelet felől Magyarnádalja, dél felől Kemestaródfa, északnyugat felől pedig Pinkamindszent. Közigazgatási területe észak, illetve északkelet felől érintkezik egy-egy rövid szakaszon Szentpéterfa és Harasztifalu határszélével is.'),
    ('Vasasszonyfa', 'Kisasszonyfalva és Nagyasszonyfalva egyesítéséből jött létre 1937-ben, neve 1939-ig Asszonyfalva volt. Nevét onnan kapta, hogy a középkorban a királyné birtoka volt. Szombathelytől 10 kilométerre északkeletre fekszik, a Surányi-patak mellett, a Gyöngyös-sík északnyugati részén. A szomszédos települések: észak felől Tömörd, északkelet felől Meszlen, délkelet felől Salköveskút, délnyugat felől Söpte, északnyugat felől pedig Kőszegpaty.'),
    ('Vasboldogasszony', 'A településen polgárőrség működik. Zalaegerszegtől 13 kilométerre északra fekszik, a Vas-zalai Sárvíz mellett. Egervár keleti szomszédja. Első írásos említése 1354-ből ismert: Villa Boldugazzonfalua. Később Saary Boldogazzon(1544.), Boldogazzonfalwa (1545) alakban is megjelenik neve. A Vasboldogasszony nevet 1898-ban vette fel.'),
    ('Vasegerszeg', 'Szombathelytől kelet-északkeletre fekszik, körülbelül 30 kilométerre, a Répce jobb parti oldalán. Mai belterületét két különálló településrész alkotja: északkeleten a nagyobb kiterjedésű Ivánegerszeg vagy Nagyegerszeg és délnyugaton a jóval kisebb, úgyszólván csak egy utcából és egy kastélyból álló Keményegerszeg vagy Kisegerszeg.'),
    ('Vashosszúfalu', 'A Kemenesalján található. A közvetlenül határos települések: észak felől Káld, északkelet felől Kissomlyó, kelet felől Duka, dél felől Bögöte, nyugat felől pedig Hosszúpereszteg. Vashosszúfalu megállóhely állomásépülete ma is áll még (lakóházzá átalakítva), egykori őrházában ma kisbolt üzemel. Somlóvár tartozékaként az Anthimi, majd a Garai család birtokában volt.'),
    ('Vaskeresztes', 'Német többségű falu, de a lakók kevés kivétellel egyúttal magyarnak is vallják magukat. A Vas-hegy lábánál, Szombathelytől mintegy 15 kilométerre nyugatra fekszik, közvetlenül az osztrák határ mellett. A Pinka észak-déli irányban keresztülszeli a települést. A szomszédos települések a határ magyar oldalán: észak felől Felsőcsatár, kelet felől Nárai, dél felől pedig Horvátlövő.'),
    ('Vaskút', 'Bajától 7 kilométerre délkeletre fekszik, alig 20 kilométerre a déli országhatártól. A 19. századi nagy vasútépítések során a Baja–Zombor–Újvidék viszonylatban, eredetileg helyiérdekű vasútként létesített, 1895-ben átadott vonal Vaskúton is áthaladt. A trianoni békeszerződés azonban kettévágta a vasútvonalat, melynek így a forgalma is lecsökkent. A megmaradt Baja-Vaskút-Gara közötti szakaszon az 1968-as közlekedéspolitikai koncepció szerint a forgalom 1971. november 30-ával megszűnt, később a síneket is felszedték.'),
    ('Vasmegyer', 'A Közép-Nyírség északi részén, a Rétközben helyezkedik el, Nagyhalászhoz és Beszterechez közel. A közvetlen szomszédos települések: észak felől Tiszatelek, északkelet felől Beszterec, kelet felől Kék, délkelet felől Nyírbogdány, délnyugat felől Kemecse, nyugat felől pedig Tiszarád. A település és környéke ősidők óta lakott hely, területén már a kőkorszakban is éltek emberek, melyről az itt talált leletek tanúskodnak.'),
    ('Vaspör', 'A településen polgárőrség működik. A legközelebbi város Zalalövő. Különálló belterületi településrésze Velence, amely a község centrumától mintegy 4 kilométerre fekszik, délkeleti irányban. Itt áll a Nyírfa Turistaház, mely a 20. század első felében épült, eredetileg általános iskola működött benne. Az épület 2009-ben felújításon esett át.'),
    ('Vassurány', 'A Gyöngyös-sík északi részén fekszik, a megyeszékhely, Szombathely északkeleti szomszédságában, a város központjától 10 kilométerre. A községet a Surányi-patak választja két részre, melyek közül a délnyugati az Alsósurány, az északkeleti a Felsősurány nevet viseli. A közvetlenül határos települések: észak felől Salköveskút, északkelet felől Vasszilvágy, délkelet felől Nemesbőd, dél felől Vép, délnyugat felől Zanat (Szombathely része), északnyugat felől pedig Söpte.'),
    ('Vasszentmihály', 'A falu Körmendtől 15 kilométerre nyugatra, Szentgotthárdtól 13 kilométerre keletre fekszik, a Lahn-pataknak a Vörös-patakba való betorkollásánál. A közvetlenül határos települések: észak felől Nemesmedves, kelet felől Rátót, délkelet felől Rábagyarmat, délnyugat felől Csörötnek, nyugat felől pedig Rönök. Rátóttal kerékpárút is összeköti. 1336-ban Scentmyhal néven említik először. 1422-ben, 1464-ben, 1476-ban, 1480-ban, 1496-ban említik írott források Zenthmyhal, illetve Zenthmihal néven.'),
    ('Vasszilvágy', 'Szombathelytől 15 kilométerre északkeletre található, a Gyöngyös-sík északi részén. Két falurésze, Alsó- és Felsőszilvágy a Hosszú-víz mentén fekszik, délnyugatról a Rátka-patak, délkeletről a Kőris-patak határolja. A szomszédos települések: észak felől Acsád, kelet felől Szeleste, délkelet felől Vát, délnyugat felől Nemesbőd, nyugat felől pedig Vassurány és Salköveskút.'),
    ('Vasszécseny', 'A mai község Lipárt és Szécseny falvak egyesítésével jött létre. A Gyöngyös-patak jobb partján fekszik, a megyeszékhely Szombathelytől 12 kilométerre délkeletre. Különálló településrésze Lipárt, mely a mai belterület nyugati részét képezi. A közvetlenül határos települések: észak felől Bozzai, északkelet felől Kenéz, kelet felől Pecöl, délkelet felől Csempeszkopács, dél felől Nemeskolta, délnyugat felől Sorkikápolna, nyugat felől pedig Tanakajd.'),
    ('Vasvár', 'A Felső-Kemenesháton, Szombathelytől délkeletre helyezkedik el, a Rába jobb partja mentén. Különálló településrészei Kismákfa és Nagymákfa, a központtól nyugatra helyezkedik el. A közvetlenül határos települések: észak felől Püspökmolnári és Rum, északkelet felől Alsóújlak, kelet felől Oszkó, délkelet felől Pácsony és Győrvár, dél felől Hegyhátszentpéter és Petőmihályfa, délnyugat felől Gersekarát és Döbörhegy, nyugat felől Egyházashollós, északnyugat felől pedig Rábahídvég.'),
    ('Vaszar', 'Pápától mintegy 8 kilométerre, a Sokoróalja szélén húzódó dombhátak egyikén, a Gerence-patak közelében települt. Külterületén két szőlőhegy található, Mézeshegy és Gyulahegy. A település közúti elérését a 8305-ös út biztosítja, ezen közelíthető meg déli irányból, Pápa felől, illetve északról is, Gyarmatnál letérve a 83-as főútról délkeleti irányban helyezkedik el.'),
    ('Vatta', 'Közigazgatási területe nyugat-északnyugat felől egy-egy rövid szakaszon határos még Tibolddaróccal és Sállyal is, de e községekkel nincs közvetlen, kiépített közúti kapcsolata. Csincse 6 kilométer-re, Harsány 7 kilométer-re, Bükkábrány 7 kilométer-re, Tibolddaróc 10 kilométer-re, Sály 8 kilométer-re, Borsodgeszt 7 kilométer-re. A legközelebbi város: Emőd 7 kilométerre helyezkedik el.'),
    ('Vecsés', 'A magyarság és a világ elsősorban a híres káposztájáról ismeri a várost. Vecsés földrajzi értelemben a Duna Pest megye teraszos völgymedencéjében, a Pesti-hordalékkúpsíkságon helyezkedik el. Északkelet felől a Gödöllői-dombsághoz tartozó dombvidék húzódik, déli irányban a Duna–Tisza közi homokhátság területe kezdődik. Határos Budapest fővárossal, Ecser községgel, valamint Üllő és Gyál városokkal.'),
    ('Vejti', 'Az Ormánság középső-déli részén helyezkedik el, Sellyétől délkeletre, Vajszló déli szomszédjában. A térség legdélebbi fekvésű falvai közé tartozik, központja alig egy kilométerre fekszik a Dráva folyótól – amely itt természetes határt képez Magyarország és Horvátország között –, déli határszéle bő 3 kilométeres szakaszon egybe is esik a déli országhatárral.'),
    ('Vekerd', 'Zsáka központjától 3-4 kilométerre délnyugatra található, de teljesen enklávé jelleggel ékelődik be annak határrészei közé, vagyis minden irányból csak zsákai közigazgatási területek veszik körbe. Természetföldrajzi szempontból a Bihari-sík nyugati vidékén, az Ölyvös-csatorna partján fekszik. Vekerd nevével a curui apátsággal kapcsolatban a Váradi regestrumban találkozhatunk először, ahol Vazul curui apát vekerdi lakosokat valamely „kihágással” vádolt. 1332-ben a pápai…'),
    ('Velem', 'Velem Magyarország nyugati határán a Kőszegi-hegység lábánál fekszik, Kőszeg városától 8 kilométer-re. Északkeletre Cák, délkeletre Kőszegszerdahely, délre Bozsok, nyugatra pedig az osztrák határ szegélyezi. A település az Írottkő Natúrpark része. A község és környéke lakott volt már az újkőkorszakban is. A tárgyi emlékek legjelentősebb lelőhelye a község feletti 582 méter magas Szent Vid-hegy.'),
    ('Velemér', 'Magyarország nyugati határán, a Vendvidék, a Vasi-Hegyhát és a Zalai-dombság által határolt háromszögben, Hetés tájegység északnyugati szegletében lelhető fel. Területén a Csesztreg-Magyarszombatfa közti 7423-as út húzódik végig, amelybe itt torkollik bele a Szentgyörgyvölgy több településrészét összekapcsoló 7425-ös út. A völgyet, amelyben Velemér (Magyarszombatfával és a hozzá csatolt Gödörházával egyetemben) megtalálható, a reformáció óta Zürich-völgynek is nevezték.'),
    ('Velence', 'Gyorsan fejlődő, országos jelentőségű fürdőváros, mely főként a Velencei-tónak, valamint két nagyváros, Budapest és Székesfehérvár közelségének köszönheti gazdaságának és népességének jó ütemű növekedését. A város déli része, Velencefürdő főként üdülőtelep.'),
    ('Velény', 'A község Pécstől 25 kilométerre délnyugatra fekszik a Pécsi–víz völgyében. A domborzati viszonyok miatt külterületének csak a Szabadszentkirály felőli része alkalmas a hagyományos szántóföldi művelésre helyezkedik el. A község másik oldalán elhelyezkedő dombokat jelentős kiterjedésű erdő- és szőlőterületek borítják. A völgyben két utca húzódik végig, amelyeket fésűs beépítés jellemez.'),
    ('Veresegyház', 'A községet már Secretarius Lazarus 1510 és 1520 között készült térképe is feltünteti Vesereghatz néven. A település (mely 1999. június 30. óta város) Budapestől 30 kilométer-re északkeletre található, a Gödöllői-dombságban a Sződ–Rákos-patak széles völgyében terül el, a Cserhát vonulatainak délnyugati vége közelében. A várost déli irányból a mogyoródi Gyertyános és a Fóti-Somlyó, nyugatról a csomádi Magas-hegy, keletről a 345 méter magas Margita, valamint a Bódis-hegy határolja.'),
    ('Verpelét', 'A Mátra keleti lábánál, a Tarna völgyében fekszik. A környező települések: észak felől Sirok, északkelet felől Egerszólát, dél felől Feldebrő, délnyugat felől Vécs, nyugat felől Kisnána, északnyugat felől pedig Tarnaszentmária. Északnyugati irányban messze elnyúló külterületei révén határos még Recskkel is. Határszélét északkeleten érinti még a 24 128-as út is.'),
    ('Verseg', 'Aszódtól északkeletre fekvő, mezőgazdasági jellegű település. A 2106-os és a 2109-es utak találkozásánál fekszik. Előbbi Kállón át Váccal köti össze a községet, utóbbi Aszódtól húzódik Szarvasgedéig. Verseg (Versend) Árpád-kori település a Cserhátalján helyezkedik el. Nevét 1290-ben említette először oklevél Wrsegh néven, ide való nemesek budai szőlejéről szólva.'),
    ('Versend', 'Mohácstól nyugatra helyezkedik el, közvetlenül Bóly északi szomszédságában. A további szomszédos települések: észak felől Liptód, kelet felől Szajk, nyugat felől Monyoród, északnyugat felől pedig Máriakéménd. A település népességének változása: A 2011-es népszámlálás során a lakosok 96,7%-a magyarnak, 52,9% cigánynak, 10,4% horvátnak, 6,2% németnek mondta magát (2% nem nyilatkozott.'),
    ('Verőce', 'A Dunakanyarban Vác és Szob között a Duna bal partján helyezkedik el. Kerékpárral elkerülhető a közúti forgalom a Váctól kiépített kerékpárúton. Elérhető Verőce vasúton és vízi úton is. Nevének eredetét kétféleképpen magyarázzák: az egyik változat szerint kaput jelent, míg a másik…'),
    ('Veszkény', 'Veszkény Magyarország északnyugati részén Kapuvártól keletre, 8 kilométer távolságra helyezkedik el. Első írásos említése 1265-ből maradt fenn "nobilis de wezeken" alakban helyezkedik el. Béla ekkor öt telket adományozott a királyi erdőőrök birtokából Vezekényi Dénesnek, mivel a Morva melletti csatában a királyt védve súlyosan megsebesült. Az Árpád-kori oklevelekben Veszkény, Wezeken, Vezeken, Wezekin formában fordult elő. 1366-ban a győri káptalan előtt a Vezekény család tagjai közös megegyezéssel felosztják egymás között birtokaikat.'),
    ('Veszprém', 'Egyetemi, a királynék városa. 2023-ban az Európa kulturális fővárosa címet is viselte. Magyarország egyik legrégebben alapított városa, szinte egyidős az állammal. Légvonalban a Balatontól 11 kilométer-re, a közép-dunántúli régióközponttól, Székesfehérvártól 40 kilométer-re, Budapesttől pedig 97 kilométer-re fekszik, a Bakony déli részén. A város története egészen a honfoglalás koráig nyúlik vissza: Anonymus szerint már a magyarok beérkezésekor is állt itt egy vár, amely valószínűleg egy 9. századi frank erőd lehetett.'),
    ('Veszprémfajsz', 'Veszprémfajsz egy, a Bakony déli lábánál fekvő egyutcás település. A legközelebbi települések: Nemesvámos (4 kilométerre), Felsőörs (6 kilométerre), Paloznak (8 kilométerre), valamint Csopak és Veszprém (egyaránt 9-9 kilométerre). Délkelet felől pontszerűen határos még Lovassal is. A falu nevét Árpád fia Jutas fiáról, Fajszról kapta. A jelenlegi község a 18. században épült ki, a középkori falu majd egy kilométerre innen helyezkedett el.'),
    ('Veszprémgalsa', 'A Marcal-medencében a Marcaltól körülbelül 4 kilométerre, a Torna-patak közelében fekszik. Szomszédai Apácatorna, Kisberzseny és Hosztót. Legegyszerűbben a 8-as főúton érhető el a település, Apácatornánál letérve a 7326-os útra, az elágazástól nagyjából 3 kilométer távolságra. Áthalad emellett a község területén a Csabrendek-Nemeskeresztúr közti 7325-ös út is.'),
    ('Veszprémvarsány', 'A település az északi Bakony keleti lejtőjére épült. Közigazgatási területe lenyúlik a Sokorói-dombságot és a Bakony hegységet elválasztó síkságra is, ahol a gabona is megterem. Az északi lejtőkön szőlő termelhető. Egyike ama hat településnek, amelyet 2002. október 20. után csatoltak a megyéhez, a Zirci kistérségből átsorolva a Pannonhalmai kistérségbe.'),
    ('Vezseny', 'A folyó Vezseny „körül” 12 kilométeres kerülőt tesz meg. A község elvileg mégsem zsáktelepülés, a főutca ugyanis a Tisza-partra vezet, a folyón pedig komp működik, és az út folytatódik a túloldalon, Martfű és Tiszaföldvár közigazgatási határvonalán helyezkedik el. Tengerszint feletti magassága 87–91 méter. A megyeszékhely, Szolnok körülbelül 25 kilométerre fekszik, a két legközelebbi város pedig a már említett Martfű és Tiszaföldvár (mindkettő már a Tisza bal partján), körülbelül 5–5 kilométerre.'),
    ('VI. kerület', 'A VI. kerület, vagy hivatalos nevén Terézváros a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon a XIII. kerület, nyugaton az V. kerület, délen a VII. kerület, míg keleten a XIV. kerület határolja. A kerület egyike Budapest legforgalmasabb és legélettelibb részeinek, ahol az elegáns sugárutak, történelmi épületek és kulturális központok találkoznak a pezsgő városi élettel.'),
    ('Vid', 'Devecsertől északnyugatra, Nagyalásony és Iszkáz közt fekszik. A térség legkisebb közigazgatási területű települései közé tartozik, mindössze három közvetlen szomszédja van: észak és kelet felől Nagyalásony, délkelet felől Somlószőlős, dél és nyugat felől pedig Kisszőlős. Vid és környéke már a bronzkorban is lakott hely volt, amit a mai falutól délre feltárt urnasíros temető leletei is bizonyítanak.'),
    ('Vigántpetend', 'Vigántpetend a Balatontól 15 kilométerre északra, a Balaton-felvidéket és a Bakony hegyvonalát szétválasztó Eger-patak völgyében, a Veszprém-Tapolca főközlekedési út mentén fekszik. Nagyvázsony irányából a Balaton-felvidék fennsíkjáról ereszkedhetünk le a meredek szerpentinúton. Az első meredek jobb kanyar után már lehet látni a községet és az Eger-völgye településeit, a Bakony hegyvonulatait.'),
    ('VII. kerület', 'A VII. kerület, vagy hivatalos nevén Erzsébetváros a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon a VI. kerület, nyugaton a V. kerület, délen a VIII. kerület, míg keleten a XIV. kerület határolja. A kerület 2010-ben elnyerte az Értékgazdag Település címet, Pest egyik legjelentősebb, történelmileg és kulturálisan gazdag városrésze.'),
    ('VIII. kerület', 'A VIII. kerület, vagy hivatalos nevén Józsefváros a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon a VII. kerület és a XIV. kerület, nyugaton a V. kerület, délen a IX. kerület, míg keleten a X. kerület határolja. A főváros egyik legváltozatosabb területe, amely gazdag történelmi, kulturális és társadalmi háttérrel rendelkezik.'),
    ('Villány', 'A róla elnevezett Villányi-hegység keleti lábainál található, mintegy tíz kilométerre a déli országhatártól. Mohácstól délnyugati, Siklóstól és Harkánytól ugyancsak keleti irányban fekszik. A szomszédos települések: észak felől Kisbudmér, északkelet felől Pócsa és Borjád, kelet felől Márok, délkelet felől Magyarbóly, dél felől Beremend, délnyugat felől Nagyharsány, északnyugat felől pedig Villánykövesd és Kisjakabfalva.'),
    ('Villánykövesd', 'Villány nyugati szomszédságában fekszik, nem messze a déli országhatártól. A további szomszédos települések: észak felől Ivánbattyán, északkelet felől Kisjakabfalva, dél felől Nagyharsány, délnyugat felől Kisharsány, északnyugat felől pedig Palkonya. Határszéleit érintik még keleten a Kisjakabfalvára vezető 57 132-es, nyugaton pedig az Ivánbattyánt kiszolgáló 57 116-os számú mellékutak is.'),
    ('Vilmány', 'Hozzátartozik a vele összeépült Vilmánykisfalu is. A Zempléni-hegység nyugati lábainál, a Hernád völgyében fekszik. Határa szinte teljes egészében a folyó bal parti oldalán terül el, de hozzá tartozik két kisebb, lakatlan külterület a folyó jobb parti oldaláról is. A közvetlen szomszédos települések: észak felől Göncruszka, kelet felől Hejce, délkelet felől Fony, dél felől Vizsoly, nyugat felől Garadna, északnyugat felől pedig Hernádvécse.'),
    ('Vilonya', 'A község a Dunántúli-középhegységhez tartozó Bakony-vidék Balaton-felvidékének kistájcsoportjába tartozik. Veszprémtől keletre, a Séd patak mentén található. Átlagos tengerszint feletti magassága 180-200 méter. Vilonya a Balatontól 8 kilométerre, a Mezőföld nyugati határánál, a Veszprém–Várpalota–Balatonfűzfő háromszögben, vagyis tájak, régiók találkozásánál terül el, s ennek megfelelően a környezete kis területen is igen változatos.'),
    ('Vilyvitány', 'Az Északi-középhegységben, ezen belül a Hegyköz tájegységben található, közvetlenül a szlovák határ mellett. A szomszédos települések: kelet felől Felsőregmec, délkelet felől Mikóháza, délnyugat felől Kovácsvágás, nyugat felől Füzérradvány, északnyugat felől pedig Füzérkajata.'),
    ('Vindornyafok', 'Vindornyafok a Keszthelyi-fennsík nyugati szélénél a Zalai-dombságtól keletre, a Vindornya és a Gyöngyös-patak összefolyásánál található. A leginkább Keszthely, kisebb számban Hévíz és Zalaszentgrót felől érkező buszok nagy része a falu határában áll meg, kisebb részük megy csak be a településre. A település első említése 1358-ból való mint nemesi falu. 1508-ban a nagybirtokos Sárkány család is részt szerzett a faluból, azonban a jobbágyi rész tulajdonosa nagyrészt a Derecskei család volt.'),
    ('Vindornyalak', 'Vindornyalak a Tátika-csoportban, a Vindornya kelet-nyugati völgyében fekszik, a Zalaszántót (a 7327-es utat) és Vindornyaszőlőst (a 7331-es utat) összekötő 73 164-es számú mellékúton félúton. A településre nem túl sűrűn járnak a Hévíz és Zalaszántó között járó autóbuszok. Pár járat köti össze Keszthellyel és Sümeggel. A település minden várostól messze esik, a legközelebbi, Hévíz közúton mintegy 12 kilométerre található.'),
    ('Vindornyaszőlős', 'Pár járat köti össze Vindornyafokon át Zalaszántóval. A falu első említése 1274-ből való, amikor a király a zalai vár birtokát a Péci családnak adományozta. Kihalásuk után, 1525-ben a Sárkány család birtoka lett, majd még a 16. században a gersei Pethők is tulajdont szereztek a szőlőművelésből élő településen. Vulkanikus alapon létrejött agyagos talaja ma is igen alkalmas a vörösbor alapanyaga termesztésére. 1564-től kezdve a törökök többször csapást mértek a falura.'),
    ('Vinár', 'Pápától mintegy 23 kilométerre nyugatra, Celldömölktől hasonló távolságra keletre helyezkedik el, a Marcal folyó árterében. Határában éri el a Marcalt a Hajagos-patak. A további szomszédos települések: kelet felől Mihályháza, dél felől Nemesszalók, nyugat felől pedig Marcalgergelyi, utóbbi községgel szinte összeépült. Közigazgatási területe északkeleten, pontszerűen érintkezik még Kemeneshőgyész határával is.'),
    ('Visegrád', 'Esztergomtól 25 kilométer-re, Budapesttől 35 kilométer-re helyezkedik el a Duna jobb partján, Nagymarossal szemben. Magyarország egyik legkisebb városa, népszerű kirándulóhely, kikötőváros. Vára, mely egy alsó várból és egy citadellából áll, kiemelkedő jelentőségű: a középkorban a magyar királyok egyik legfontosabb rezidenciája állt itt, később pedig a Visegrádi Csoport (V4) 1991-es találkozó helyeként ismert. 1323-tól, egészen 1408-ig ez volt a középkori Magyar Királyság székvárosa.'),
    ('Visonta', 'A település a Keleti-Mátraalján, Gyöngyöstől keletre helyezkedik el. Keletről a Bene-patak, délről a Borhy-völgyi-patak határolja. A közvetlenül határos települések: északkelet felől Markaz, délkelet felől Halmajugra, dél felől Karácsond, délnyugat felől Gyöngyöshalász, nyugat felől Gyöngyös, északnyugat felől pedig Abasár. Határszélét keleten érinti még a 24 146-os út is.'),
    ('Viss', 'A Bodrogközben, Olaszliszka, Kenézlő és Zalkod közt fekvő település. A település a honfoglalás korában jött létre, a honfoglalás kori leletek ma Nyíregyházán tekinthetőek meg a Jósa András Múzeumban. A falut elsőként 1239-ben említik. 1410-ben a település vámhely, vízi és szárazföldi vámja is van. A 15. század közepéig több birtokosa is volt a településnek: Upor, Ujfalusy, és az Óbégányi családoknak volt itt birtoka.'),
    ('Visz', 'Erdős dombok, szőlő- és gyümölcsültetvények veszik körül. A Balatonra érkező turisták szívesen kirándulnak a Balatonlellétől mintegy 10 kilométerre délre fekvő településre, amely a Balatonboglári borvidék részét képezi. A község neve először 1229-ben Wysch alakban fordult elő, a székesfehérvári káptalan birtokaként.'),
    ('Viszló', 'Szendrőtől 20, Edelénytől 30 kilométerre található. A szomszédos települések: észak felől Tornaszentjakab, kelet felől Pamlény, dél felől Rakaca, nyugat felől pedig Debréte. Északkeleten egy pár kilométeres szélességű, Perecséhez tartozó külterületi sáv határolja (ez választja el az államhatártól), ez utóbbi község belterülete azonban távol esik tőle.'),
    ('Visznek', 'A szomszédos települések: északkelet felől Nagyfüged, kelet felől Zaránk, délkelet felől Erk, dél felől Tarnaörs, nyugat felől Jászárokszállás, északnyugat felől pedig Adács. Észak felől a legközelebbi település Karácsond, de a közigazgatási területeik nem határosak. Csak közúton közelíthető meg, Jászárokszállás vagy Tarnaörs érintésével, mindkét irányból a 3205-ös úton helyezkedik el.'),
    ('Viszák', 'Lakosságszáma 1980-ban még 386 fős volt, ami bő egy emberöltő, 34 év alatt kevesebb, mint a kétharmadára csökkent, 2014-ben már csak 251 főt írtak össze a községben. Történelme az Árpádok koráig nyúlik vissza. Első okleveles említés Lugossal és Ivánccal együtt 1237 előttről való „Vyzaah” alakban helyezkedik el. Nevének eredete a magyar „vissza-ág” azaz visszakanyarodó patak jelentésű szóösszetételre vezethető vissza (Kniezsa István).'),
    ('Vizslás', 'Lakóinak többsége a palóc népcsoporthoz tartozik, a faluban gazdag hagyománya van a palóc népviselet készítésének és viselésének, amely a kazári népviselettel együtt formálódott. Salgótarjántól délkeletre található, Kazár irányába. A falu a Medves-fennsík és a Zagyva-völgy földrajzi kistájak határán fekszik, 300–400 méter tszf-i magasságú, szelíd dombok között, a Vizslás-patak völgyében.'),
    ('Vizsoly', 'Történelmi jelentőségét elsősorban arról nyerte, hogy itt nyomtatták ki 1590-ben az első teljes magyar nyelvű Bibliát, Károlyi Gáspár vezetésével. A vizsolyi református templomban ma is megtekinthető egy eredeti példány ebből a Bibliából helyezkedik el. A falu festői környezetben, a Zempléni-hegység közelében fekszik.'),
    ('Vokány', 'Siklóstól kissé északkeletre fekszik, a Villányi-hegység északi lejtője alatt. A szomszédos települések: észak felől Kisherend, északkelet felől Újpetre, délkelet felől Palkonya, dél felől Nagytótfalu, délnyugat felől Siklós (Máriagyűd), nyugat felől Kistótfalu, északnyugat felől pedig Áta és Szőkéd. Vokány helyén már az Árpád-korban a Trinitás bencés apátság állt, melyet az oklevelek már 1183-ban említettek, s az apátsághoz a 14. században már Szenttrinitás falu is kapcsolódott.'),
    ('Vonyarcvashegy', 'Délről a Balaton, északról a Keszthelyi-fennsík hegyei határolják a települést, amely így inkább csak kelet–nyugati irányban nyitott. „Szárazföldön” csak két települési szomszédja van: kelet felől Balatongyörök, nyugat felől pedig Gyenesdiás (észak felől is csak e két településhez tartozó külterületek övezik). Balatoni vízterületei révén dél felől határos még Balatonberénnyel is.'),
    ('Vác', 'Katolikus püspöki székhely, a Váci egyházmegye központja. A gazdag kulturális élettel és sok kuriózummal rendelkező város nem véletlenül katolikus püspöki székhely. A Március 15. tér, a város fő tere, ami az egymást keresztező fontosabb útvonalak találkozásánál alakult ki, itt jött létre a város kereskedelmi és közigazgatási központja.'),
    ('Vácduka', 'Vácduka Árpád-kori település. Nevét (Duka formában) 1295-ben említették először, ekkor adta el a Záh nemzetségbeli Zaah fia Mihály az itteni birtokát a Rátót nemzetséghez tartozó István fia Kokas mesternek, hatvan márkáért. 1332-1337 között neve szerepelt a pápai tizedjegyzékben is. Ekkor a váci egyházmegye szolnoki főesperességi kerületéhez tartozott, melynek „Tuca” nevű plébániáját egyes történészek Dukával azonosítják. 1334-ben Péter fia László dukai birtokrészét leányának adta azzal, hogy az elzálogosított birtokrészt is kiváltja.'),
    ('Vácegres', 'A település első okleveles említése Sydo néven ismert. A Zsidó-nemzetség, illetve a nemzetségből származott Csáky-család ősi birtoka. A török időben sem néptelenedett el a község, ismerjük török birtokosait is. Csak az 1686-os felszabadító háború idején futottak szét lakói, ám 1695-96-ban ismét benépesült, római katolikus magyarokkal és evangélikus szlovákokkal.'),
    ('Váchartyán', 'Budapesttől mintegy 30 kilométerre fekszik észak-északkeleti irányban. Északról a Cserhát dombjai védik a zord északi széltől, dél felé kinyílik a látóhatár, és jó időben ellátni a Visegrádi-hegységig helyezkedik el. Az M2-es autóút megépülésével a közúti közlekedés is jobb minőségűvé vált, mint a megye más, félreesőbb területein. Határszélét délkeleten érinti még az Őrbottyán főutcájaként húzódó 2103-as út is.'),
    ('Váckisújfalu', 'A szomszédos települések: északkelet felől Galgagyörk, kelet felől Galgamácsa, dél felől Vácegres, délnyugat felől Őrbottyán, északnyugat felől pedig Kisnémedi és Püspökszilágy. Nyugat felől a legközelebbi település Váchartyán, de a közigazgatási területeik kevés híján nem érintkeznek. A települést az alábbi helyközi autóbuszjáratok érintik: 316, 342, 347, 348, 394, 450, 452, 454.'),
    ('Vácrátót', 'Vácrátót Sződ–Rákos-patak sekély és széles völgyében helyezkedik el. Keleten a Gödöllői-dombság, délen a Kő-hegy, északon a Cserhát peremén húzódó Kígyós-dombsor, végül nyugat felől a Vác–Pesti-Duna-völgy határolja. Vácrátót határának északi része a Gödöllői-dombsághoz, déli része pedig a Pesti-hordalékkúpsíkság keskeny északi nyúlványához tartozik.'),
    ('Vácszentlászló', 'Az ősi magyar település a Hajta-patak két partján húzódik, s az első világháborútól kezdődően új falurészekkel bővült. Belterülete: 188 ha, külterülete 2987 ha. Az M3-as autópályától délre, Gödöllőnél Zsámbok felé letérve érhető el a település. A falu területéről vaskori régészeti leletek kerültek elő. A településtől északra halad el a szarmaták által 324 és 337 között épített, a Dunát a Tiszával összekötő Csörsz árok nyomvonala.'),
    ('Vág', 'A Rábaköz déli részén, a Rába bal partján helyezkedik el. Elterjedt az a nézet, hogy a falu első említése 1001-ből származik, ugyanis a Pannonhalmi apátság Alapítólevelének végén említett hét halászfalu egyike: Wag. Az első írott említés 1263-ból, IV. Egy fent maradt monda szerint egyszer Màtyàs kiràly Vàg környèkèn vadàszott. Mivel a faluban èppen akkor bùcsù volt betèrt, hogy szomjùsàgàt csillapìtsa.'),
    ('Vágáshuta', 'A Zempléni-hegység középső részén helyezkedik el, Pálházától délre, a megyeszékhely Miskolctól mintegy 95 kilométerre keletre. Két különálló településrésze: a belterület északi részén Kispart, a délkeleti részén pedig Nagypart. Határszéle szinte minden irányból Kovácsvágáshoz tartozó külterületekkel érintkezik, csak kelet felől határos egy másik községgel, Mikóházával.'),
    ('Vál', 'Székesfehérvártól 50, Budapesttől 45, Bicskétől 18, Baracskától 9,5, Alcsútdoboztól 8,5 kilométer távolságra található. Vál története a csiszolt kőkorszakig nyúlik vissza, az itt talált régészeti leletek alapján már ekkor lakott hely lehetett. A falu nevét feltehetően a latin "vallis", "völgy " szóból kapta. Egy másik magyarázat szerint „Valószínűleg puszta személynévből keletkezett magyar névadással.'),
    ('Vállaj', 'Határszéle keleten és délen, összesen több mint 13 kilométer hosszan egybeesik a magyar-román államhatárral. A térség fontosabb települései közül Nyírbátortól 25, Fábiánházától 9, Nagyecsedtől pedig 11 kilométerre található. A határ magyar oldalán csak két települési szomszédja van: észak felől Mérk, nyugat felől pedig Terem. A határ túloldalán a legközelebbi települések: kelet felől Börvely (Berveni), dél felől Csanálos (Urziceni), délnyugat felől pedig Csanáloserdő (Urziceni-Pădure).'),
    ('Vállus', 'Vállus a Keszthelyi-fennsík délkeleti részén, egy hegyoldalon fekszik. A településre Keszthely és Tapolca felől járnak autóbuszok. Vállus első említése 1121-ből való, amikor a almádi monostor kapta meg a királytól kegyes ajándékként. 1359-ben Ujlaki Miklós herceghez került a település, majd 1525-től a Sárkány család lett az új birtokos. A 15. században a község felett pálos monostor állt.'),
    ('Vámosatya', 'A keleti schengeni határtól 5 kilométerre található. Közúton három irányból érhető el: Vásárosnamény (Gergelyiugornya)-Tiszaszalka, illetve Gelénes felől a 4122-es, Barabás felől pedig a 4123-as úton. Vásárosnaményból a Tisza-híd után balra fordulva kanyargós úton 16 kilométerre, vagy egyenesen haladva Tákos, Csaroda, Gelénes felől közelíthető meg.'),
    ('Vámoscsalád', 'A Kisalföld déli részén helyezkedik el, a Répce jobb parti oldalán. A közvetlenül határos települések: észak felől Répceszemere, északkelet felől Répcelak, kelet felől Nick, dél felől Uraiújfalu, délnyugat felől Vasegerszeg, nyugat felől Nagygeresd, északnyugat felől pedig Csáfordjánosfa. Vámoscsaládot 1221-ben említi először oklevél. Nevét a Répce hídjához kapcsolódó vámszedőhelyről kapta.'),
    ('Vámosgyörk', 'Az Alföldön, a Gyöngyösi-síkon található, a Rédei-Nagy-patak és a Gyöngyös-patak mellett. Budapesttől kb. 90 kilométer-re fekszik. Szomszédos települései: dél-délkelet felől Jászárokszállás (kb. 7 kilométer), kelet felől Adács (kb. 5 kilométer), északnyugat felől Atkár (kb. 5 kilométer). A közúti tömegközlekedést a Volánbusz végzi. A település környéke a régészeti leletek tanúsága szerint az őskor óta lakott.'),
    ('Vámosmikola', 'Vámosmikola a Börzsöny nyugati lábánál fekszik, az Ipoly bal partján, Szobtól 20 kilométer-re északra. Délről Nagybörzsöny, északról Perőcsény, nyugatról pedig Ipolypásztó, Ipolybél és Ipolyszakállos községekkel határos. Nyugati határát (amely egyben államhatár is Szlovákia felé) az Ipoly alkotja. Keleten területe a Börzsöny külső pereméig nyúlik (Vár-bükk, 743 méter).'),
    ('Vámosoroszi', 'A megye keleti részén, a Szatmári-síkságon, az ukrán határ közelében fekszik, lakott területét a Tapolnok patak szeli ketté. Szomszédai: észak felől Fülesd, északkelet felől Kölcse, kelet felől Csaholc, dél felől Kisnamény, délnyugat felől Darnó, nyugat felől pedig Kisszekeres. A határos települések közül Csaholc, Fülesd, Kisszekeres és Nemesborzova is 4-5 kilométernyi távolságra fekszik.'),
    ('Vámospércs', 'A megyeszékhelytől, Debrecenből 20 kilométerre keletre fekszik. A szomszédos települések: észak felől Nyírmártonfalva, északkelet felől Nyíracsád, kelet felől Nyírábrány, délkelet felől Bagamér, dél felől Újléta, nyugat felől Debrecen, illetve annak Haláp nevű külterületi városrésze. Bagamérral és Álmosddal a 4806-os, Létavértessel a 4807-es, Nyírlugossal pedig a 4905-ös köti össze.'),
    ('Vámosszabadi', 'Határátkelő Szlovákia felé. A Kisalföldnek azon a részén fekszik, amely a Rába győri torkolatától északnyugatra, az országhatárig terjed. Ez a Mosoni-síkság, a Mosoni-Duna, valamint az Öreg-Duna által közrezárt Szigetköz. A Rajkától Gönyűig tartó szakaszon a folyó esése csökken, ezért hordalékának nagy részét ma is itt rakja le, s mederágya folyamatosan emelkedik.'),
    ('Vámosújfalu', 'A Bodrog jobb parti oldalán fekszik, a folyótól mintegy 800 méterre északra, a Tolcsva-patak mellett. Területe és határának nagyobb része sík vidék, csak a Tolcsvával határos, a vasútvonalon túli határrész hegyes (odáig nyúlnak a tolcsvai hegyek lábai). Földrajzi szempontból azonban tiszta alföldi településnek vehető. A település eredeti földrajzi meghatározója a Bodrog folyó volt.'),
    ('Váncsod', 'Berettyóújfalutól keletre fekszik, természetföldrajzi szempontból a Bihari-sík északi vidékén, a Berettyó–Kálló köze szomszédságában. A szomszédos települések: észak felől Gáborján, kelet felől Bojt, délkelet felől Biharkeresztes, dél felől Mezőpeterd, nyugat felől Berettyóújfalu, északnyugat felől pedig Szentpéterszeg. A 13. század elején már említik a település nevét Iváncsod néven, egy perrel kapcsolatban, amikor egy András nevű lakosa lett gyujtogatás vádja miatt a váradi istenítéletiszék elé idézve.'),
    ('Várad', 'Szigetvár déli vonzáskörzetében helyezkedik el. A szomszédos települések: észak felől Molvány és Hobol, kelet felől Szentegát, délkelet felől Bürüs, délnyugat felől Kétújfalu, nyugat felől pedig Gyöngyösmellék. Közigazgatási területét érinti a Szigetvártól Sellye térségéig (Drávafokig) húzódó 5808-as út, így mindhárom említett település felől ezen az úton közelíthető meg.'),
    ('Váralja', 'A település észak felől nyitott, dél felől a Kelet-Mecsek hegyei magasodnak a falu fölé. A gyönyörű fekvésű falu a legegyszerűbben a 11 kilométerre fekvő Bonyhádról közelíthető meg, de el lehet jutni ide a 45 kilométerre fekvő megyeszékhely, Pécs és Komló felől is, Szászváron át. A Mecsek, mint hazánk legdélibb fekvésű hegységének jellemzője a Földközi-tenger hatásait is mutató, úgynevezett szubmediterrán éghajlat.'),
    ('Váraszó', 'Az Északi-középhegységben fekszik, a Tarna völgyében, annak egyik mellékágának két partján. Kiterjedt külterületei révén viszonylag távol fekvő településekkel is közvetlenül határos, így északon Domaházával, északkeleten Tarnalelesszel, keleten Bükkszenterzsébettel, dél felől Pétervásárával, délnyugaton Erdőkövesddel, nyugat felől Istenmezejével, északnyugat felől pedig Zabarral.'),
    ('Várbalog', 'Az osztrák határ mellett fekszik, Jánossomorjától 9 kilométerre északnyugatra, a régió központjától, Mosonmagyaróvártól légvonalban 15, közúton mintegy 22 kilométerre. A 20. század nagy részében zsáktelepülés volt, a határnyitás némileg javított a helyzetén. Mosonmagyaróvár és Csorna felől egyaránt a 86-os főúton közelíthető meg, amelyről Jánossomorjánál kell letérni a 8507-es, majd a 8508-as útra helyezkedik el.'),
    ('Várdomb', 'Dél-Dunántúlon, a Mecsek lankás dombokká szelídült keleti végének és a Duna egykori árterületének, a Sárköznek határán fekszik, része a szekszárdi történelmi borvidéknek. Szomszédos községei keleten Sárpilis 4, nyugaton pedig Alsónána, 3 kilométernyi távolságra helyezkedik el. A falu jelenlegi hossza kb. 2 kilométer, területe 450 ha, a lakóházak száma 430.'),
    ('Várfölde', 'A Zalaegerszeg-Nagykanizsa-Letenye háromszögön belül fekvő település, Bánokszentgyörgytől északnyugatra helyezkedik el. Zsákfalunak tekinthető, közúton csak ez utóbbi település felől érhető el, a 7536-os útból nyugatnak kiágazó 75 138-as úton. Az első Árpádok uralkodása idején a zalai vár földjei közé tartozott. 1379-ben kapta a Bánfi család őse (Haholt).'),
    ('Várgesztes', 'A Vértes északnyugati csücskében fekszik, Tatabányától 17 kilométerre, a gesztesi vár alatti völgyben meghúzódva. Dél felől Gánthoz, nyugat felől pedig Oroszlányhoz tartozó külterületek határolják. Területén illetve a közvetlen környezetében jó néhány, 400 méter körüli vagy azt meghaladó vértesi magaslat emelkedik, ezek egyike a 410 méteres Zsigmond-kő.'),
    ('Várkesző', 'A Rába folyóhoz közel, Egyházaskeszőtől 2 kilométerre északnyugatra található. Előnevét a Rába folyó partján épült vízivárról kapta, amelynek földbástyaszerű kiemelkedését ma is látni lehet. A vízivárat körülfogta a Rába vize, természetes védővonalat vonva a vár köré. Nevének utótagját többféleképpen értelmezik. Valószínű, hogy a Keszi=Kesző törzsnévből ered.'),
    ('Várong', 'Tájéka szervesen kapcsolódik a külső-somogyi dombvidékhez, amely épp e környéken éri el egyik legmagasabb pontját. Várong ezen dombok déli oldalán, Törökkoppánytól mintegy 5 kilométerre délre helyezkedik el, a hajdani Körtvélyesi-patak nyugati dombhajlatán. Amióta azonban elkészült a Lápafőt Dombóvárral összekötő út felújítása, jóval lerövidült a Várongra való eljutás menetideje is.'),
    ('Városföld', 'A Duna-Tisza közi homokhátságon, a kiskunsági löszöshát területén helyezkedik el. A szomszédos települések: észak (és nyugat) felől Kecskemét, északkelet felől Nyárlőrinc, délkelet felől Kiskunfélegyháza, dél felől pedig Kunszállás. Délnyugat felől, pontszerűen érintkezik még a közigazgatási területe Fülöpjakabéval is.'),
    ('Városlőd', 'Mindössze három települési szomszédja van: észak felől Csehbánya, délkelet felől Szentgál, nyugat felől pedig Kislőd. A helyközi buszjáratok Ajka, Pápa és Veszprém felől is bemennek a településre helyezkedik el. A távolsági járatok csak az elágazásnál állnak meg. A bronzkorban már lakott település volt. A község határában működött 1346…'),
    ('Várpalota', 'Magyarország szocialista idejében bányavárosként tartották számon, ám a bányákat az idő múlásával bezárták. A városlakók közül sokan a közeli nagyvárosokban, Veszprémben vagy Székesfehérváron dolgoznak. Légvonalban Veszprémtől és Székesfehérvártól is egyaránt 20 kilométer-re, Budapesttől 70 kilométer-re, a Balatontól pedig 17 kilométer-re fekszik. A város eredete a római és az avar korszakhoz kapcsolódik, amint azt a város külterületén megtalált temetkezési halmok, sírkövek és római kori leletek bizonyítják.'),
    ('Várvölgy', 'A Balaton-felvidéki borvidék cserszegi körzetének része. Utóbbi Vállus lakott területét elhagyva is folytatódik (ott már az előbbi számozás nélkül), egészen Balatongyörökig, de az a szakasz korlátozott forgalmú erdészeti út. Az álló, háromszögű pajzs kék mezejében alul zöld hármashalom díszlik. A középső halmon a falu védőszentjére utaló, liliomban végződő, szárain ezüst és fekete váltakozásával élre csiszolt, úgynevezett Domonkos-kereszt áll.'),
    ('Vászoly', 'Az apró, Balaton-felvidéki falu a Balaton-felvidéki Nemzeti Park területén, egy völgyben fekszik, amely völgy szerkezetileg a Dörgicsei-medencéhez tartozik. Távolsága Balatonfüredtől 15, Aszófőtől 10 kilométer. Közúton legegyszerűbben a Balatonakali-Dörgicse-Pécsely-Balatonszőlős között húzódó 7338-as úton érhető el, ahol Dörgicse és Pécsely között fekszik, az út mindkét végpontjától majdnem azonos (8-9 kilométernyi) távolságra.'),
    ('Vásárosbéc', 'Szigetvártól északra, a Zselic alján fekszik, Magyarlukafa és Visnye között. A központjától mintegy 7 kilométerre délre fekvő Dióspuszta településrésze Somogyapáti Adorjánpuszta nevű községrésze felől érhető el, a 66 129-es számú mellékúton. A falu és környéke a fennmaradt adatok szerint az Árpád-korban királyi vadászterület volt. Nevét 1332-1237 között említették először egy oklevélben.'),
    ('Vásárosdombó', 'A település nagyobb része a csatorna bal oldalán fekszik, egy kisebb, Ódombó nevű része a jobb oldalon terül el. Külterületi településrésze Melegoldal, mely a központtól mintegy 2 kilométerre fekszik északkeleti irányban. A 2011-es adatok szerint Melegoldal lakatlan, 12 nem lakott üdülő alkotja. Melegoldalra egy földút vezet Vásárosdombóról. A környező kisebb települések közül Vásárosdombó déli széle felől érhető el Tarrós, a 65 178-as számú mellékúton.'),
    ('Vásárosfalu', 'Magyarország északnyugati részén, a Rábaközben, a kapuvári sík kistájon helyezkedik el. A Rába folyótól 4 kilométerre északra, Kapuvártól 18 kilométerre délkeletre, Csornától pedig 25 kilométerre délnyugatra fekszik. Éghajlata mérsékelten meleg és az ország nagyobb részének átlagához képest csapadékosabb (636 mm). Központját viszont csak a Páli-Edve felől idáig húzódó 8427-es, illetve a Beled-Rábakecöl közti 8428-as utak érintik, a környező kisebb települések felől ezek valamelyikén érhető el.'),
    ('Vásárosmiske', 'A Kemenesalján található. A szomszédos települések: északkelet felől Mesteri, kelet felől Kemeneskápolna, délkelet felől Köcsk, délnyugat felől Káld, nyugat felől Gérce, északnyugat felől pedig Sitke. Csak közúton közelíthető meg: a legközelebbi város, Celldömölk központja felől Mesteri érintésével, illetve Gérce irányából a 8432-es, Celldömölk Alsóság városrésze és Kemeneskápolna felől pedig a 8433-as úton helyezkedik el.'),
    ('Vásárosnamény', 'Hozzá tartozik 1969 óta Vitka, továbbá az 1939-ben Gergelyi és Ugornya egyesítésével keletkezett Gergelyiugornya. A város központi része az itt csatornaszerűen egyenes mederben lefutó Kraszna bal partján terül el. Különálló városrésze Gergelyiugornya, amely a Tisza jobbparti oldalán, tehát már a beregi részen fekszik.'),
    ('Vát', 'A Gyöngyös-sík keleti részén fekszik, Szombathelytől 15 kilométerre kelet-északkeletre, Sárvártól 10 kilométerre nyugat-északnyugatra. A szomszédos települések: északkelet felől Szeleste, kelet felől Ölbő, délkelet felől Csénye és Bögöt, dél felől Porpác, délnyugat felől Vép, nyugat felől Nemesbőd, északnyugat felől pedig Vasszilvágy. Kevés híja van annak, hogy nem határos északnyugat felől még Vassurány községgel is.'),
    ('Vázsnok', 'Vázsnok és környéke már a bronzkorban is lakott hely volt, az itt talált bronzkori temető leletei szerint, de kelta, római kori emlékek is napvilágra kerültek itt. A falut 1332-ben említette először oklevél, nevét Wasnuk alakban írva, birtokosa ekkor a Dobai család volt. Vázsnok a 14. században már jelentős település lehetett, ekkor már állt Kisboldogasszonyról elnevezett temploma is, és a környék vallási központjának írták.'),
    ('Vécs', 'A közvetlen szomszédos települések: észak felől Kisnána, északkelet felől Verpelét, kelet felől Feldebrő, délkelet felől Aldebrő és Tófalu, nyugat felől pedig Domoszló. [Dél felől a Mátrai Erőmű aldebrői lignitbányája határolja.] Csak közúton érhető el, Kisnána felől a 24 131-es, Feldebrő és Detk felől pedig a 24 132-es számú mellékúton. Határszélét délen érinti még a 2420-as út is.'),
    ('Végegyháza', 'Előbbi a településközpont keleti szélén, utóbbi pedig attól délre, Árpádtelep községrész közelében, külterületen helyezkedik el. A település az 1892-ig Tótkovácsházának, ma Végegyházának nevezett község. Nevét Végh Aurél kincstári felügyelő tiszteletére kapta. Teljesen sakktáblás utcahálózattal, szerződéses telepítvényes községként jött létre 1815-ben, kincstári földön, közel egy időben a…'),
    ('Vékény', 'Vékény és környéke már az őskorban lakott hely volt, később a rómaiak is megtelepedtek itt. Ezt támasztja alá a környéken talált sok kőkori és római korból származó lelet, épületmaradvány is. A honfoglalás szlávokat talált itt, akik később beolvadtak a magyarságba. Emléküket a falu fennmaradt dűlőnevei máig őrzik: Ilyen a Szászvár és Vékény határán húzódó Szapuka és Szalósa dűlő.'),
    ('Véménd', 'A kelet-baranyai település szelíd dombok között húzódik meg. Már a bronzkorban lakott volt: előbb a mészbetétes kultúra, később a kelták szórványleletei erről tanúskodnak. Első említése az 1332–35 közötti időszakban történt Emon néven, csupán a 18. század első harmadában jelent meg a Vemen forma.'),
    ('Vének', 'Magyarország északnyugati részén, a Szigetköz csücskében, Győrtől 14 kilométer-re helyezkedik el. Vének kicsi falu a Szigetközben a Nagy-Duna és Mosoni-Duna találkozásánál. Jelenleg mindössze 154 fő él a helységben. Őseiknek régebben nagy problémát okozott a Duna gyakori áradása. Vének és a vele határos Szőgye, a Szigetközi Ármentesítő Társulat megalakulásával és az általa kezdeményezett töltés építése révén vált védettebbé a folyó pusztító hatásától.'),
    ('Vép', 'A Gyöngyös-sík középső részén fekszik, a Kozár- és Borzó-patakok összefolyásánál, a megyeszékhely Szombathely keleti szomszédságában, a város központjától 8 kilométerre. A közvetlenül határos települések: észak felől Vassurány és Nemesbőd, északkelet felől Vát, kelet felől Porpác, délkelet felől Pecöl, Kenéz és Bozzai, dél felől Tanakajd és Táplánszentkereszt, délnyugat felől Zarkaháza, északnyugat felől pedig Zanat (mindkét utóbbi Szombathely része).'),
    ('Vértesacsa', 'Acsa (a Vértes hegységre utaló Vértes jelző a 20. század elején járult Acsa helységnévhez megkülönböztetésül más Acsa nevű falvaktól) halmazfaluból kialakított többutcás szalagtelepülés a Lovasberényi-háton. A község központi belterülete (213 hektár) a vértesacsai völgyben fekszik 161 méter tengerszint feletti magasságban. Területe (3619 hektár) völgyekkel sűrűn felszabdalt löszborította eróziós dombság.'),
    ('Vértesboglár', 'A falut körülvevő területek nagy része a Vértesi Tájvédelmi Körzethez tartozik. Vértesboglárt és környékét már a rómaiak is lakták, amit a leletek és a települést átszelő római út nyomai is bizonyítanak. Boglár (Al- és Felboglár) nevét az oklevelek már 1187 előtt említik, mint királynéi birtokot.'),
    ('Vérteskethely', 'A hangulatos, jó levegőjű, csendes kisközség kellemes kikapcsolódási lehetőséget kínál az ide látogatóknak. Autóbusszal az 1256-os, 1257-es, 1702-es, 1848-as, 1851-es, 8464-es, 8560-as, 8618-as és 8736-os járatokkal közelíthető meg A terület már a kora vaskor-tól lakott, később megtelepedtek itt az avarok és a rómaiak is. A falut egy 1250-ben kelt oklevél említi először. 1332 körül Károly Róbert a falu vásárnapját keddre tette, innen is eredhet a Kethely név.'),
    ('Vértessomló', 'A római kor óta lakott település, mely a mai napig németajkú a 18. századi betelepítéseknek köszönhetően. 1734–1737 között Esterházy József gróf katolikus németeket telepített a községbe. A lakosok sokféle változatban ejtették ki és használták írásban a település nevét: Semle, Zsemle, Zsömléd, Schemling. Végül 1890-ben miniszteri rendelettel a Vértessomló elnevezést kapta.'),
    ('Vértesszőlős', 'Nemzetközi hírnevét a vértesszőlősi őstelep elnevezésű archeológiai bemutatóhelynek köszönheti, ahol 1965-ben a Homo erectus leleteit tárták fel. Vértesszőlős már ősidők óta lakott helynek számít. Neve az 1960-as években vált világszerte ismertté, amikor Pécsi Márton geográfus két tanítványa, Mészáros Imre és Schweitzer Ferenc megtalálta az első csonttöredékeket, illetve eszközöket, majd Vértes László ősrégész vezetésével feltárták Európa egyik legrégibb, mintegy félmillió évvel ezelőtt élt ősemberének, Samunak telephelyét.'),
    ('Vértestolna', 'Mai elnevezése némileg megtévesztő, hiszen nem a Vértes, hanem a Gerecse területén fekszik. A településen ma is jelentős számú német nemzetiségi lakos él, gazdag a falu nemzetiségi kulturális élete is. Vértestolna a Gerecse hegység nyugati részének kis völgyében található, alig 500 lakosú község. A településtől Tata közúton mintegy 12, Tatabánya 16 kilométernyi utazással érhető el (légvonalban Tatabánya valójában közelebb fekszik hozzá, mint Tata).'),
    ('Vése', 'A közvetlenül határos települések: északkelet felől Tapsony, kelet felől Böhönye, délkelet felől Segesd, dél felől Somogyszob, délnyugat felől Kaszó, nyugat felől Inke, északnyugat felől pedig Nemesdéd. Nemesdéddel és Nemesviddel a 6816-os út köti össze, mely a központjában ágazik ki a főútból északnyugat felé. A közeli Merkepusztán kolostormaradványt tártak fel.'),
    ('Vésztő', 'Természetföldrajzi szempontból a Kis-Sárrét délnyugati peremén, a Körös menti sík szomszédságában fekszik. Saját fűtőházzal rendelkezik. Szomszédai: Bélmegyer, Okány, Körösújfalu, Körösladány, Szeghalom és Újiráz.'),
    ('Vízvár', 'A partmente a Duna–Dráva Nemzeti Park része. Vízvár múltjából először a 16. századból vannak emlékek, amikor Tahy Ferenc várat emeltetett a Dráva partján, a víztől és mocsaraktól védett helyen. A vár 1555-ben már fennállt, mivel Zrínyi Miklós 1555 november 17-én kelt levelében a törökök elleni harcban fontosnak vélve az erődítményt zsoldosőrséget sürgetett a vár védelmére, Szigetvár eleste után azonban védői a várat elhagyták, sőt fel is égették maguk mögött.'),
    ('Vöckönd', 'Zalaegerszegtől északkeletre fekszik, mintegy 14 kilométernyire. Zsáktelepülés, közúton csak a Sümeg és Zalaegerszeg között húzódó 7328-as útról Kemendollárnál leágazó, bő 3 kilométer hosszú, 73 221-es számú mellékúton közelíthető meg. Vöckönd a kapornaki apátság ősi birtoka volt. A falu első említése 1451-es oklevelekben történt. Nem sokkal később, 1480-ban már egyházashely, vagyis temploma van.'),
    ('Völcsej', 'Egyutcás, fésűs beépítésű, egykori nemesi falu. Soprontól 27, Kapuvártól 28, Kőszegtől 26 kilométerre helyezkedik el, határát erdőség övezi. A terület növénytermesztésre és állattenyésztésre is kiválóan alkalmas. Első okleveles említése 1281-ben helyezkedik el. A falu legrégibb, 1865-ből ismert pecsétje: A pecsét mezejében levágott páncélos, kardos kart két pálmalevél övez.'),
    ('Vönöck', 'Celldömölktől 7 kilométerre északi irányban fekszik. A szomszéd települések: északkelet felől Kemenesmagasi, délkelet felől Mersevát, dél felől Kemenesszentmárton, délnyugat felől Kemenessömjén, északnyugat felől Csönge és Kenyeri. Vönöck a Kemenesalján húzódó, 850 lélekszámú, többutcás, szalagtelkes község. A bazaltvulkán a „tanúhegytől”, a Ság hegytől 7 kilométer-re terül el északi irányban.'),
    ('Vörs', 'Hivatalosan, levédetve „a Kis-Balaton fővárosa”. Vörsön található Európa legnagyobb templomban épített beltéri betleheme, amely a karácsonyi ünnepek idején több tízezer látogatót vonz a településre. A Szent Márton Európai Kulturális Útvonalat az Európai Tanács 2005-ben kiemelkedő jelentőségű európai kulturális úttá nyilvánította. Vörs az ennek nyomán kialakított Via Sancti Martini hálózat egyik állomása.'),
    ('Vöröstó', 'A Balaton-felvidéken, Nagyvázsonytól délkeletre fekvő település. Főutcája a 73 113-as út, ami Barnag és Mencshely külterületei közt húzódik 6,6 kilométer hosszban, kelet-nyugati irányban, de egy korlátozott forgalmú önkormányzati út vezet innen Nagyvázsony központjába is. A település és környéke ősidők óta lakott hely volt. Területén kőkorszakból származó csiszolt kőszerszámok, kőbalták kerültek elő.'),
    ('X. kerület', 'A X. kerület, vagy hivatalos nevén Kőbánya a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon a XIV. kerület és a XVI. kerület, nyugaton a VIII. kerület és a IX. kerület, délen a XIX. kerület és a XVIII. kerület, míg keleten a XVII. kerület határolja. A lakótelepek mellett kertvárosias és szerény külvárosias részek egyaránt megtalálhatók a kerületben.'),
    ('XI. kerület', 'A XI. kerület, vagy hivatalos nevén Újbuda a magyar főváros, Budapest egyik kerülete, amely a Duna jobb partján, Budán fekszik. Északon az I. kerület és a XII. kerület, nyugaton Budaörs, délen a XXII. kerület, míg a Duna által keleten a IX. kerület, illetve a XXI. kerület határolja. A változatos domborzatú és arculatú dél-budai kerület közlekedési értelemben a főváros nyugati kapuja.'),
    ('XII. kerület', 'A XII. kerület, vagy hivatalos nevén Hegyvidék a magyar főváros, Budapest egyik kerülete, amely a Duna jobb partján, Budán fekszik. Északon a II. kerület, nyugaton Budakeszi, délen Budaörs és a XI. kerület, míg keleten az I. kerület határolja. Legfőképp hegyvidéki területein (a Budai-hegység magaslatain) fekszik. Területe már az őskorban lakott volt.'),
    ('XIII. kerület', 'A XIII. kerület a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon a IV. kerület, nyugaton a Duna által II. kerület és a III. kerület, délen az V. kerület és a VI. kerület, míg keleten a XIV. kerület határolja. A legtöbb kerülettől eltérően nincs általános elnevezése. A kerületnek jelenleg 5 városrésze van: Angyalföld, a Göncz Árpád városközpont, a Népsziget, Újlipótváros és Vizafogó.'),
    ('XIV. kerület', 'A XIV. kerület, vagy hivatalos nevén Zugló a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon az IV. kerület és a XV. kerület, nyugaton a VI. kerület, a VII. kerület és a XIII. kerület, délen a VIII. kerület és a X. kerület, míg keleten az XVI. kerület határolja. A városrész 1792-ben I. Ferenc trónra lépésének alkalmából kapta ezt a nevet.'),
    ('XIX. kerület', 'A XIX. kerület, vagy hivatalos nevén Kispest a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon a X. kerület, nyugaton a IX. kerület, nyugaton és délen a XX. kerület, míg keleten a XVIII. kerület határolja. A főváros egyik legváltozatosabb területe, gazdag történelmi, kulturális és társadalmi háttérrel rendelkezik.'),
    ('XV. kerület', 'A XV. kerület, vagy hivatalos nevén Rákospalota-Pestújhely-Újpalota a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon Dunakeszi és Fót, nyugaton a IV. kerület, délen a XIV. kerület, míg keleten a XVI. kerület és Csömör határolja. A kerületnek jelenleg 3 városrésze van: Pestújhely, Rákospalota és Újpalota. Jelentősebb terei közé tartozik a Széchenyi tér, a Szentmihályi tér, valamint a Rákos út környéke.'),
    ('XVI. kerület', 'A XVI. kerület a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északkeleten Csömör, keleten Nagytarcsa, délkeleten a XVII. kerület, délnyugaton a X. kerület, nyugaton a XIV. kerület, míg északnyugaton a XV. kerület határolja. A kerületnek jelenleg 5 városrésze van: Árpádföld, Cinkota, Mátyásföld, Rákosszentmihály és Sashalom.'),
    ('XVII. kerület', 'A XVII. kerület, vagy hivatalos nevén Rákosmente a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik, a főváros keleti részén. Északon a XVI. kerület és Csömör, nyugaton a X. kerület, délen a XVIII. kerület és Ecser, míg keleten Maglód és Pécel határolja. Az egyik legszebb fekvésű pesti kerület, amely részben ugyanolyan magasan terül el, mint a 235 méter magas Gellért-hegy.'),
    ('XVIII. kerület', 'A XVIII. kerület, vagy hivatalos nevén Pestszentlőrinc-Pestszentimre a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon a X. kerület és a XVII. kerület, nyugaton a XIX. kerület és a XXIII. kerület, délen Gyál, míg keleten Vecsés határolja. A kerület főleg lakófunkciójú peremkerület, nagyrészt laza családiházas beépítéssel, több sűrűn beépített lakóteleppel és néhány ipari létesítménnyel.'),
    ('XX. kerület', 'A XX. kerület, vagy hivatalos nevén Pesterzsébet a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pest déli részén fekszik. Északon a IX. kerület, nyugaton a Ráckevei-Duna által a XXI. kerület, délen a XXIII. kerület, míg keleten a XIX. kerület határolja. A kerület túlnyomórészt lakóingatlanokból áll, ipara elhanyagolható. A kerület fontos intézménye a Jahn Ferenc Dél-pesti Kórház, melyet 1980-ban adtak át.'),
    ('XXI. kerület', 'A XXI. kerület, vagy hivatalos nevén Csepel a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján és a Ráckevei-Duna jobb partján, a Csepel-szigeten fekszik. Északon a IX. kerület, nyugaton a XI. kerület és a XXII. kerület, délen Szigetszentmiklós, míg keleten a XX. kerület és a XXIII. kerület határolja. Egyaránt rendelkezik kertvárosias, falusias, vízparti, illetve lakótelepi és ipari városrészekkel.'),
    ('XXII. kerület', 'A XXII. kerület, vagy hivatalos nevén Budafok-Tétény a magyar főváros, Budapest egyik kerülete, amely a Duna jobb partján, Budán fekszik. Északon a XI. kerület, nyugaton Budaörs, Törökbálint, Diósd és Érd, délen a Duna által Halásztelek és Szigetszentmiklós, míg keleten szintén a Duna által XXI. kerület határolja. A kerületnek jelenleg 4 városrésze van: a Baross Gábor-telep, Budafok, Budatétény és Nagytétény.'),
    ('XXIII. kerület', 'A XXIII. kerület, vagy hivatalos nevén Soroksár a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. 1994-ben vált le Budapest XX. kerületéről. Területe megegyezik az 1950-ben Nagy-Budapesthez csatolt Soroksár nagyközségével. Északon a XX. kerület, nyugaton a Ráckevei-Duna által a XXI. kerület és Szigetszentmiklós, délen Dunaharaszti és Alsónémedi, míg keleten a XVIII. kerület és Gyál határolja.'),
    ('Zabar', 'Településrészei: Külső- és Belső-Zabar, Bárkányitanya, Hegyesbükkpuszta, Kútágapuszta, Malomútpuszta, Szőlőalja. Szomszédos települések: Cered (7,5 kilométer), Istenmezeje (8 kilométer), Domaháza (8 kilométer). A község természeti környezete, klímája jó lehetőséget nyújt erdei kirándulásokra, gombagyűjtésre helyezkedik el. A Novohrad-Nógrád UNESCO Globális Geopark települése.'),
    ('Zagyvarékas', 'Szolnok, a megyeszékhely kb. 10 kilométer-re található. Szomszédos települések: Szolnok, Szászberek, Újszász. A közúti tömegközlekedést a Volánbusz biztosítja. Régészeti leletek tanúsága szerint Zagyvarékas területe igen régen lakott hely. Kevés ásatás folyt ezen a részen, ám e ritka alkalmak során rábukkantak egy Kr. e. 3000 körüli rézkori telepnyomra helyezkedik el.'),
    ('Zagyvaszántó', 'Hatvantól északra fekszik, a Mátra délnyugati lábánál. Közigazgatási területe két különálló részből tevődik össze, az északabbra eső területrész jóval kisebb a másiknál és csak lakatlan külterületek alkotják. A közvetlenül határos települések: északkelet felől Apc, délkelet felől Petőfibánya, dél felől Lőrinci (Selyp), nyugat felől Héhalom, északnyugat felől pedig Palotás.'),
    ('Zajk', 'A Fintafai-patak partján, erdős hegyekkel szegélyezett völgyben fekszik. 1292 az első év, amikor forrás említi a falut. Első hivatalos levéltári említése 1352-ből való. 1360-ra már Zayk néven találhatjuk a falut. Az 1300-as évek második felében már a Zayky család birtoka, hosszú ideig a család kezén is maradt. A családot később Zichy néven lelhetjük fel.'),
    ('Zajta', 'Csengertől 14 kilométerre északkeletre fekszik, közvetlenül a román határ mellett. A határ magyar oldalán csak két településsel szomszédos: észak (és nyugat) felől Rozsállyal, északkelet felől pedig Méhtelekkel. A román oldalon a legközelebbi szomszédja dél felől Nagypeleske (Peleș), de feltehetőleg határos Atya (Atea) és Kispeleske (Pelișor) településekkel is.'),
    ('Zala', 'A község a Balatontól 23 kilométerre, délre fekszik a külső-somogyi dombságban. Északkeleten Sérsekszőlőssel, délkeleten Tabbal, míg nyugaton Kapollyal határos. A település belterülete 185 méter magasan fekszik az Adriai-tenger szintje felett. Legmagasabb pontja a község északkeleti részén található Halomi-dűlő, mely 269 méter magasan fekszik. A településen átfolyik egy kis patak, a Zalai vízfolyás, mely a Kis-Koppány folyó egyik mellékfolyója.'),
    ('Zalaapáti', 'Zalaapáti a Zalai-dombság keleti felén, a Zala völgyének nyugati részén terül el. Korábban különálló településrésze volt Zalahosszúfalu, amely mára a központjával szinte teljesen összenőtt és a település északi részét képezi. A közvetlenül határos települések: észak felől Bókaháza, északkelet felől Szentgyörgyvár, délkelet felől Sármellék, dél felől Esztergályhorváti, délnyugat felől Zalaszentmárton, nyugat felől Pacsa, északnyugat felől pedig Szentpéterúr és Gétye.'),
    ('Zalabaksa', 'Jelentős vízfolyása a Kerka patak, mely választóvonalát képezi Hetés, illetve Göcsej tájegységeinek. Zalabaksa és környéke ősidők óta lakott helynek számít, amit a falu határában feltárt késő bronzkori és római kori leletek is bizonyítanak. A jelenlegi főútvonala mentén húzódott a rómaiak híres és nagyon fontos hadi- és kereskedelmi útja, a nevezetes borostyánút is.'),
    ('Zalaboldogfa', 'A megyeszékhely, Zalaegerszeg északnyugati szomszédságában található, az itt nyugat-keleti irányt követő Zala bal (északi) parti oldalán, a folyótól jó 3 kilométerre. A további, közvetlenül határos települések: észak felől Telekes, északkelet felől Kiskutas, délnyugat felől Bagod és Vitenyéd, északnyugat felől pedig Szentpál (mindkét utóbbi Bagod része).'),
    ('Zalabér', 'A nyolcszáz éves múltú, mezővárosi rangú település, központi elhelyezkedése miatt ma is a környék központja. A településen polgárőrség működik. A Zala folyó mentén található, Zalaegerszegtől 20 kilométerre északkeletre, Zalaszentgróttól 5 kilométerre északnyugatra. Állomása a mai Zalabér-Batyk vasútállomástól északnyugatra feküdt volna. Nevének első Zala tagja a Zala folyó közelségére, míg a Bér régi személynév volt.'),
    ('Zalacsány', 'A Zala völgyében fekszik, a folyó jobb parti (nyugati) oldalán. A közvetlenül határos települések: észak felől Kehida, északkelet felől Kustány (ma mindkettő Kehidakustány része), kelet felől Nemesbük, délkelet felől Szentgyörgyvár, dél felől Bókaháza, délnyugat felől Gétye és Szentpéterúr, nyugat felől Tilaj, északnyugat felől pedig Ligetfalva. A legközelebbi városok közül Hévíz 9, Keszthely 14 kilométerre keletre, Zalaszentgrót pedig 17 kilométerre északra található.'),
    ('Zalacséb', 'A településen polgárőrség működik. Kellemes, szélsőségektől mentes éghajlata, a dombokat borító erdők, bőséges vízhálózata jó megélhetést biztosított már a halászó-vadászó őseinknek is. A falu határában talált kőbalta arra enged következtetni, hogy más az őskorban is lakott hely lehetett. A közelmúltban, a vasútépítés miatt végzett feltárások során a Malom-tanya közelében őskori és római kori leletek mellett, az Árpád-kor maradványaira is rábukkantak.'),
    ('Zalaegerszeg', 'Egyike Magyarország legvirágosabb, legzöldebb városainak, 2008-ban elnyerte a Virágos Magyarország program „Arany Rózsa” régiós díját. A város története a középkorig nyúlik vissza, első írásos említése 1247-ből való Egurscugként, 1293-ban pedig már Egerszeg néven szerepel.'),
    ('Zalaerdőd', 'A település legkorábbi okleveles említése 1351-ből ismert, akkor Nauylad néven jegyezték fel, mint a Nyavalád család birtokát. Az első ismert birtokos Nyavalyádi Henrik fia, Jakab volt. Nevét 1426-ban is említette egy oklevél, mint Szentlászló Márton birtokát. Később a Marczali család kapta meg királyi adományként. 1454-ben Marczali János somogyi főispán az akkor lakatlan pusztát az erenyei pálosoknak adta, majd adományát 1458-ban Mátyás király is megerősítette.'),
    ('Zalagyömörő', 'Sümeg vonzáskörzetében, a város északnyugati szomszédságában fekszik. A további közvetlenül határos települések: észak felől Ukk, kelet felől Csabrendek, délnyugat felől Kisvásárhely, nyugat felől pedig Gógánfa. Zalagyömörő nevét 1423-ban említette először oklevél Vggyemerew (Ukkgyömörő) néven. 1424-ben Gemere, 1480-ban Gyemerew néven írták. A török hódoltság alatt sem néptelenedett el…'),
    ('Zalahaláp', 'Zalahaláptól északra, közúton körülbelül 6-6 kilométerre fekszik Ódörögd és Újdörögd, ahol uradalmi gazdaságok voltak. A településnek a belterületen kívül eső területei Ódörögdpuszta, Újdörögdpuszta és Kolónia településrészekre tagolódnak. A települést a Dunántúl egyik legszebb táján, a Tapolcai-medencét körülvevő tanúhegyek északi részén, a Haláp-hegy déli lábánál találjuk.'),
    ('Zalaháshágy', 'A község a Kemeneshát déli kistáján, a fennsík jellegű Felső-Kemenesháton, annak is a Zala völgyére lankásan futó, délies kitettségű lejtőin található. Zalaegerszegtől légvonalban 21 kilométerre északnyugatra található, a legközelebbi város Zalalövő, légvonalban 6, közúton 10 kilométerre délkeleti irányban. A 19. századtól neve leginkább Hashágy, 1873–1882 között Hárshágy volt, végül a településnév-rendezés során, 1908-ban nyerte el a Zalaháshágy nevet.'),
    ('Zalaigrice', 'A Zalai-dombságban, ezen belül a Zalaapáti-hát területén fekszik. A közvetlenül határos települések: észak felől Nemesrádó, kelet felől Szentpéterúr, dél felől Pacsa, délnyugat felől Zalaszentmihály, északnyugat felől pedig Nemessándorháza. A legközelebbi város Pacsa, 3 kilométerre délre helyezkedik el. A megyeszékhelytől, Zalaegerszegtől 30 kilométerre helyezkedik el.'),
    ('Zalaistvánd', 'Zalaegerszegtől északkeletre, Zalaszentgróttól délnyugatra fekvő település, a Principális-völgy és a Zala folyó völgyének találkozásánál. A település és környéke a bronzkor óta lakott hely. Nevét 1279-ben említette először oklevél, majd 1346-ban említették ismét az írásos dokumentumok Stephand néven helyezkedik el. Zalaistvánd egykor a kemendi váruradalom része volt, birtokosai a Gersei Pető család tagjai voltak.'),
    ('Zalakaros', 'A Magyar Fürdővárosok Szövetségének tagja. Kereskedelmi szálláshelyeken eltöltött vendégéjszakák tekintetében Magyarország 7. legnépszerűbb települése, ugyanakkor a 6. legkisebb lélekszámú városa. A városban polgárőrség működik. A település első említése 1254-ből ismert, Korus alakban helyezkedik el. Ekkor a faluban földdel rendelkező, magyar ajkú várszolgák éltek, majd IV.'),
    ('Zalakomár', 'Noha régóta lakott hely, a település a jelenlegi formájában csak 1969-ben jött létre Kiskomárom és Komárváros egyesítésével. Érdekesség, hogy itt csatlakozott volna a Budapest-Nagykanizsa vasútba az 1847-ben tervezett Sopron-Kőszeg-Szombathely…'),
    ('Zalaköveskút', 'Zalaköveskút a Zalai-dombság keleti felén, a Zalavári-hát dombjai közt elrejtve, a Zala folyótól pár kilométerre keletre fekszik. Déli irányból Nemesbükön át, egy önkormányzati úton Hévíz felől is elérhető. Hétköznap három, hétvégén egy további járat a településtől másfél kilométerre áll meg. Zalaköveskút első említése 1408-ból való. A 15. század során csak a Köveskúti nemes család tagjai és jobbágyaik voltak a lakói. 1572-ben, a török támadása után a jobbágyok elhagyták a települést, azonban a nemesek nem költöztek el a faluból.'),
    ('Zalalövő', 'Turistaforgalma jelentős. Zalalövőt délről és keletről a Göcsej, északról és nyugatról az Őrség dombjai övezik, amelyek nem emelkednek 300 méteres tengerszint feletti magasság fölé. A város szerkezete kettős: halmaz- és szeres településrészekből áll. Központja a Zalától északra fekvő mag, amelyhez szervesen csatlakozik nyugatról a zalamindszenti, keletről a zalapatakai településrész.'),
    ('Zalameggyes', 'Jánosházától 8 kilométerre délre, Sümegtől 14 kilométerre északra helyezkedik el. Meggyes 1357-ben tűnik fel először okleveles forrásban, akkor Meggyesi János birtokában volt. 1370-ben már a Meggyesi család hat ága osztozott rajta. Meggy szavunk régi helyneveinkben gyakori névelem, képzős változata olyan helyet jelentett, ahol sok meggyfa volt. Köznemesi birtokosaival a XV. században találkozunk.'),
    ('Zalamerenye', 'Neve 1892-ig Merenye volt. A településen polgárőrség működik. Nagykanizsától északkeletre, közúton 22 kilométerre, az európai hírű zalakarosi gyógyfürdőtől 2–3 kilométerre északnyugatra fekszik. A településre vonatkozó legkorábbi oklevelek, így Szent István 1019. és 1024. évi, valamint Szent László 1082. évi oklevele hamisnak bizonyultak. Ez utóbbi szerint a veszprémi egyház Szent László király második feleségétől a német Adelheid királynétól kapta volna.'),
    ('Zalaszabar', 'Zalaszabar a Kis-Balaton nyugati partján fekszik, a Balatontól és Keszthelytől délnyugatra 22 kilométerre, Hévíztől délnyugatra 20 kilométerre, Zalakarostól északra 10 kilométerre, Nagykanizsától északkeletre 28 kilométerre, környezetileg szép vidéken, erdőkkel határolt lankás dombok között. A község határában végzett régészeti ásatások során számos értékes leletre bukkantak, amelyek igazolják, hogy a környék már a honfoglalás korában is lakott volt.'),
    ('Zalaszegvár', 'Sümegtől északra, Hosztót, Veszprémgalsa és Nemeskeresztúr közt, a 7325-ös út mentén fekvő település. Zalaszegvár nevét 1396-ban említette először oklevél Zeguár néven helyezkedik el. A 15. század közepén épült fel itt a Csép kastellum, mely a Marcal folyó átkelőhelyének védelméül szolgált. A vár később elpusztult, de 1660-ban Hosszútóti Pál újra felépíttette.'),
    ('Zalaszentbalázs', 'A Zalai-dombságban, ezen belül az Egerszeg–Letenyei-dombság területén helyezkedik el. A közvetlenül határos települések: észak felől Hahót, északkelet felől Pölöskefő, délkelet felől Kacorlak, dél felől Magyarszerdahely és Bocska, délnyugat felől Börzönce, nyugat felől Bucsuta, északnyugat felől pedig Pusztamagyaród. A legközelebbi nagyobb város Nagykanizsa körülbelül 19 kilométer dél-délkeletre helyezkedik el.'),
    ('Zalaszentgrót', 'A településhez tartozik Kisszentgrót, Tüskeszentpéter, Csáford, Zalakoppány, Zalaudvarnok és Aranyod településrész. A városban polgárőrség működik. A Földrajzi nevek etimológiai szótára szerint a település neve Szent Geroldra, a város templomának védőszentjére, valamint a Zala folyóra utal. Első írásos említése 1247-ből való – de csak egy 1483-ból származó másolatból ismert – ZentGyrolth alakban helyezkedik el.'),
    ('Zalaszentgyörgy', 'A falu a Zala három teraszszintjén helyezkedik el. A Kemeneshát itt ér véget, annak a Zala völgyére meredeken leereszkedő dombvonulatai határolják, melyeket a folyóra merőlegesen kifutó patakok szabdaltak fel. Zalaegerszegtől nyugatra 13, Bagodtól nyugatra 3, Zalacsébtől keletre 4, Kávástól északra 2 kilométerre található. A legközelebbi város Zalalövő, 9 kilométerre helyezkedik el.'),
    ('Zalaszentiván', 'A szomszédos települések: északról Zalaszentlőrinc, északnyugatról Egervár, délről Pethőhenye, délnyugatról Zalaegerszeg Pózva városrésze, keletről Kemendollár, pedig délkeletről Alibánfa. Erdők, dombok veszik körül, a Zala völgyében fekszik.'),
    ('Zalaszentjakab', 'Érdekesség, hogy a Sopron–Nagykanizsa-vasutat egy 1847-es terv alapján a Sopron–Kőszeg–Szombathely–Rum–Zalaszentgrót–Nagykanizsa-útvonalon kívánták megépíteni úgy, hogy Zalakomár (Komárváros) állomáson csatlakozott volna a Budapest–Nagykanizsa-vasúthoz. Szentjakab nevét először 1329-ben említette írásos dokumentum, ekkor Zenthjakab alakban írták. A 12. század végén és a 14. század közepén Chernel comes és utódai birtokolták.'),
    ('Zalaszentlászló', 'A településen polgárőrség működik. Központján és az attól délre elterülő Gyülevész településrészen is a 7336-os út halad keresztül, de déli határát érinti a Kehidakustánytól észak felé vezető 7335-ös út is. Szomszédja nyugat felől Kallósd. Egy adat szerint a középkorban Zalaszentlászlónál is volt híd a Zala keleti és a nyugati partja között, amely 1408-ban vámszedőhely volt.'),
    ('Zalaszentlőrinc', 'Zalaegerszegtől északkeletre 11 kilométerre, Zalaszentivántól északnyugatra 3 kilométerre, Egervártól délkeletre (közúton) 5 kilométerre fekszik. A 17-es számú Szombathely–Nagykanizsa-vasútvonalon Egervár-Vasboldogasszony és Zalaszentiván vasútállomások között megállóhelye van (Zalaszentlőrinc megállóhely). A településről az első írásos említés 1464-ből Zenthlewrincz néven maradt az utókorra helyezkedik el.'),
    ('Zalaszentmihály', 'A Zalai-dombságban, ezen belül az Egerszeg–Letenyei-dombság területén fekszik, a Szévíz és a Principális-csatorna között. A közvetlenül határos települések: észak felől Nemesszentandrás és Nemessándorháza, északkelet felől Zalaigrice, kelet felől Pacsa, délkelet felől Felsőrajk, dél felől Pötréte, nyugat felől pedig Pölöske. A legközelebbi város Pacsa, 5 kilométerre keletre helyezkedik el.'),
    ('Zalaszentmárton', 'Zalaszentmárton a Zalai-dombság keleti felén, a Zala folyótól nyugatra található. Zsáktelepülés, közúton csak az Esztergályhorváti-Pacsa közti 7526-os útból kiágazó 75 123-as számú bekötőúton érhető el. Autóbuszok Keszthellyel és Zalaegerszeggel kötik össze. Zalaszentmárton első említése 1266-ból való mint a Hahót nemzetség tulajdona. A törökök teljesen elpusztították, és csak lassan települt újra a 18. században, immár a kapornaki apát tulajdonaként.'),
    ('Zalaszombatfa', 'Közigazgatásilag a falu a rédicsi körjegyzőséghez tartozik. Lakossága kevesebb, mint 50 fő, Magyarország lakónépesség szerint negyvenkettedik legkisebb települése. Zalaszombatfa a Lendva síkságán, a magyar-szlovén határ közelében helyezkedik el. A közvetlenül határos települések: észak-északkelet felől Resznek, kelet felől Belsősárd, délkelet felől Rédics, délnyugat felől pedig Szijártóháza.'),
    ('Zalaszántó', 'A településről további utak futnak Rezi és Várvölgy felé (7342-es), valamint Vindornyalakon át Vindornyaszőlős irányába (73 164-es). Zalaszántó két fontosabb vízfolyása a külterületének keleti részén húzódó Lapos-patak és a déli határszélén csörgedező Gyöngyös-patak vagy Nagy-Séd. A falu belterületén egy névtelen vízfolyás folyik keresztül. Zalaszántó Árpád-kori település.'),
    ('Zalasárszeg', 'Nagykanizsától 9 kilométerre északkeletre helyezkedik el, dombos vidéken. A közvetlenül határos települések: észak felől Csapi, kelet felől Galambok, dél és délnyugat felől Nagyrécse, északnyugat felől pedig Kisrécse. Talaja zömmel agyagos, helyenként sáros, vizenyős terület. A település képe szabálytalan, mert a domborzathoz alkalmazkodott. Széles telkek és gyümölcsösök jellemzik.'),
    ('Zalatárnok', 'A Zalai-dombságban fekszik, ezen belül a Göcsej tájegység déli részén. Különálló településrészei Oroklán, Kisoroklán és Vakola, mindhárom a központtól keletre helyezkedik el. A közvetlenül határos települések: észak felől Iborfia és Lickóvadamos, északkelet felől Bak, kelet felől Baktüttös, délkelet felől Tófej, dél felől Szentkozmadombja, délnyugat felől Gutorfölde és Mikekarácsonyfa, nyugat felől Barlahida, északnyugat felől pedig Petrikeresztúr.'),
    ('Zalavár', 'Feltételezett középkori elnevezései németül: Mosaburg, latinul: Zaladia, szlovákul: Blatnohrad. Zalavár a Kis-Balaton két tározója közötti északi földnyelven helyezkedik el. A község területének nagy része víz alatt fekszik vagy mocsaras, és a Balaton-felvidéki Nemzeti Park része. Keletről a Kis-Balaton 2-es tározója, nyugatról az 1-es tározó és a Zala folyó határolja.'),
    ('Zalavég', 'Zalavég a Kemeneshát déli lejtőin, a Zala folyó kanyarulatától kissé északra helyezkedik el. Véged formában 1247-ből való az első ismert említése. Birtokosa akkor a Ják nemzetségből való Zlaudus veszprémi püspök volt.'),
    ('Zalaújlak', 'Zalaújlak a Zalai-dombság délkeleti részén, a Kis-Balatontól kissé délnyugatra található. Nagykanizsa irányából rendszeresen járnak autóbuszok ide. Zalaújlak nevét 1259-ben említették először az írásos forrásokban Wilok, Wylak alakokban helyezkedik el. A település a középkorban a veszprémi káptalan zalamerenyei uradalmának része volt. Az 1531-ben végzett összeíráskor 10 lakott, 15 szegény, 6 elhagyott, valamint három libertinus portáját írták össze.'),
    ('Zalkod', 'A Bodrogközben, annak is a délnyugati részén fekszik, a Bodrog bal, és a Tisza jobb partján (utóbbi folyóhoz lényegesen közelebb). A tájegység legdélebbi és egyben legnyugatabbi önálló települése. A Bodrogzug vízivilágának nála délebbre, illetve nyugatabbra eső – lakatlan – részei már a Bodrog jobb partján fekvő Bodrogkeresztúrhoz és Tokajhoz tartozó külterületek.'),
    ('Zaláta', 'Az Ormánság egyik legdélebbi elhelyezkedésű települése, központja alig másfél kilométernyire fekszik északi irányban a Drávától és a magyar-horvát országhatártól. A horvátországi települések közül légvonalban a Verőce-Drávamente megyében fekvő, közigazgatásilag Szagyolcához (Čađavica) tartozó Ilmin Dvor, valamint az Eszék-Baranya megyében fekvő Martinci Miholjački fekszik a legközelebb hozzá.'),
    ('Zamárdi', 'Remek strandjai, továbbá népszerű nyári fesztiváljai miatt (pl: Balaton Sound, Strand Fesztivál) kisváros létére is az egész ország ismeri, de európai szinten is nagyon népszerű úticélpont. Városi rangját 2008-ban szerezte meg, a Dél-Dunántúli régió egyik legdinamikusabban fejlődő települése. 3 kilométer hosszú füves Nagystrandjának központi panorámája a Tihanyi-félsziget.'),
    ('Zaránk', 'A közvetlen szomszédos települések: észak felől Nagyfüged, északkelet felől Tarnazsadány, kelet felől Tarnaméra, dél felől Erk, nyugat felől pedig Visznek. Csak közúton közelíthető meg, Tarnaméra vagy Erk érintésével, mindkét irányból a 3205-ös úton helyezkedik el. Zaránk nevét a ma ismert források közül 1274-ben említette először oklevél, Zaranca néven, mint az újvári várszerkezet tartozékát.'),
    ('Zebecke', 'Zebecke a Zalai-dombság délnyugati részén, a Cserta partján, Lentitől 15 kilométerre keletre fekszik. Zebeckére Lenti és Nova irányából járnak autóbuszok. A település közelében két tektonikai süllyedék metszi egymást. Az egyik az észak-déli irányú, jellegzetesen menedékes völgy, mely a Göcsej területét választja ketté. Ebben folyik a Közép-Zala vizeit összegyűjtő Cserta.'),
    ('Zebegény', 'A Börzsönyi-peremhegység nyugati oldalánál, a Malom-patak partján fekszik. Egyéb belterületei: Újvölgy Külterületi településrészei: Akácdomb Csapásdűlő Csapásszántó Határában folyik a Medres-patak, amely szintén a Duna vízgyűjtő területéhez tartozik. Északkeletre a vulkanikus andezit és a riolit összetételű Börzsöny fekszik. A patakok környékén löszös, agyagos és homokos talajok találhatók amelyekre lajta mészkő telepedett.'),
    ('Zemplénagárd', 'A község a Bodrogköz magyarországi részének, sőt az egész megyének is a legkeletibb fekvésű települése, határszéle északon egybeesik a magyar-szlovák országhatárral, kelet-délkelet felől pedig több kilométeren át a Tisza sodorvonalát követi, illetve néhány helyen átnyúlik a folyó túlsó, bal parti oldalára is. Ez utóbbi területrészek mindegyike lakatlan, a település teljes belterülete a Tisza jobb parti oldalán terül el.'),
    ('Zengővárkony', 'A Keleti-Mecsek területén, a Zengő lábának keleti lejtőin fekszik. A szomszédos települések: észak felől Mecseknádasd, északkelet felől Apátvarasd, kelet felől Pusztakisfalu, délkelet felől Lovászhetény és Nagypall, délnyugat felől Pécsvárad, északnyugat felől pedig Óbánya. A legközelebbi város az alig 3 kilométerre lévő Pécsvárad. A helyet ősidők óta lakják.'),
    ('Zichyújfalu', 'Az egykori grófi székhely a második világháború után Seregélyeshez tartozott, majd 1966-ban Gárdonyhoz csatlakozott, végül 1997 decemberében önálló községgé alakult. Az államszocializmus évtizedeiben a hazai mezőgazdaság egyik fellegváraként rendkívül sokat fejlődött, azonban a rendszerváltás ezen településen is súlyos következményekkel járt: fejlődése megakadt, az agrárium hanyatlásnak indult.'),
    ('Zics', 'Külső-Somogyban, Tabtól 8 kilométerre délnyugatra fekszik. Központján a Szorosadtól Kapolyig húzódó, a 6508-as és 6511-es utakat összekötő 6516-os út halad végig, nyugati szomszédjával, Nágoccsal a 6523-as út köti össze. A szomszéd települések: északra (5 kilométerre) Kapoly, keletre (3,5 kilométerre) Somogyegres, délre (3,5 kilométerre) Miklósi, nyugat-délnyugatra (3 kilométerre) pedig Nágocs.'),
    ('Ziliz', 'A csereháti dombvidék déli részén fekszik, Miskolctól 15 kilométerre északi irányban. A közvetlenül szomszédos települések: északkelet felől Nyomár, dél felől Boldva, délnyugat felől Sajószentpéter, északnyugat felől pedig Borsodszirák. Nevét a zilíz gyógynövényről kapta. Régen nagyon sok ilyen növény volt a falu körül. Ziliz (Zselic) nevét 1267-ben említették először az oklevelek, Selyz alakban írva.'),
    ('Zimány', 'Kaposvár határától 7 kilométerre északkeletre fekszik. Zsáktelepülés, közúton csak a 6505-ös útból Toponár városrész központjában kiágazó 65 112-es számú mellékúton érhető el, Orci településen keresztül. A község pecsétjén, amely először 1789-ben fordult elő iraton, három álló gabonaszál, mellette egy sarló található. Ez a motívum, a helyi templom stilizált képe és a felemelt jobbjában kardot tartó oroszlán található jelenleg Zimány község címerében.'),
    ('Zirc', 'A település Magyarország legmagasabban fekvő városi rangú települése. A városhoz tartoznak Akli, Kardosrét, Szarvaskút és Tündérmajor falvak is. Az első írásos említés 1199-ből származik, ahol Siric néven említik. A város szimbóluma a zirci ciszterci apátság, amely 1737 és 1752 között épült. Egyéb látnivalók közé tartozik a helyi arborétum, a Természettudományi Múzeum és a Reguly Antal Könyvtár.'),
    ('Zomba', 'Belterületét Bonyháddal a 6533-as út, külterületének legdélebbi részeit az onnan nyugatra fekvő Tabóddal és Kisdoroggal a 6536-os út köti össze. Zomba már az ókorban is lakott volt. A Római Birodalom idejéből maradt ránk az a bronzszobor, amely a zombai Szárnyas Géniusz néven ismert és a Néprajzi Múzeumban található. A római időben Zombának római kolóniának kellett lennie, a mellette fekvő Ódány helységgel együtt. „Saját szememmel láttam a mai…'),
    ('Zsadány', 'Békés megye északkeleti részén fekszik, közel a román határhoz, természetföldrajzi szempontból a Kis-Sárrét középső részén. Szomszédai: észak felől Komádi, északkelet felől Biharugra, délkelet felől Geszt, dél felől Mezőgyán és az utóbbihoz tartozó Nagygyanté, nyugat felől Okány, északnyugat felől pedig Körösújfalu. Zsadány neve először dokumentáltan II.'),
    ('Zsana', 'A település közelében található Magyarország legnagyobb, 2,17 milliárd köbméteres földgáztározója. Kiskunhalastól mintegy 14 kilométerre délkeletre található, a Szegedre vezető 5408-as út mentén. Zsana címerében egy alföldi pásztorruhát viselő juhász látható, a környék legjellemzőbb háziállatával, egy báránnyal. A címerpajzs talpát akácvirágok szegélyezik.'),
    ('Zsarolyán', 'A térség fontosabb települései közül Fehérgyarmat 7,5, Tunyogmatolcs 12, Nagyszekeres 2, Cégénydányád pedig 5 kilométer távolságra található. A közvetlen szomszédos települések: észak-északkelet felől Nagyszekeres, kelet felől Jánkmajtis, dél felől Szamosújlak, délnyugat felől Gyügye, nyugat felől Cégénydányád, északnyugat felől pedig Penyige. Nagyszekeressel a 4133-as út kapcsolja össze.'),
    ('Zsebeháza', 'Magyarország északnyugati részén, a Rábaköz délnyugati részén helyezkedik el, Csornától dél-délnyugatra 16 kilométerre. A település neve 1346-ban Terra Sebe alakban írva szerepelt egy oklevélben helyezkedik el. A Potyondy család birtoka volt. A törökdúlás után tíz évre elnéptelenedett. A 19. század közepén jelentős számú mesterember dolgozott a faluban.'),
    ('Zselickisfalud', 'Zselickisfalud Kaposvártól délre, a zselici dombság egyik erdőkkel körülvett völgyében, a Zselicségi Tájvédelmi Körzet határán helyezkedik el. Címere beszédesen őrzi a település múltját. A tölgyfaág, a koronával ékesített halmok az erdő borította zselici dombokat jelképezik. A központi helyen ábrázolt vadkan rajza részben a térség gazdag nagyvad állományára, részben a hajdani királyi kanászok makkoltatásos sertéstartására utal.'),
    ('Zselickislak', 'A megyeszékhely, Kaposvár déli szomszédságában, a város központjától mindössze 6 kilométerre található ez a kis zselici falu, amely gyönyörű környezetben, a Zselic-patakba torkolló Pölöske-patak völgyében fekszik. Három „hegy” lankái határolják: a Szuszka, a Deres és az Öreg-hegy. Közigazgatási területe Kaposvárt leszámítva mindössze két további településsel határos: keleti szomszédja Zselicszentpál, nyugat felől pedig az amúgy délebbre fekvő Bőszénfához tartozó lakatlan külterületek határolják.'),
    ('Zselicszentpál', 'A megyeszékhely Kaposvár déli szomszédságában fekszik, a város központjától mintegy 7 kilométerre. További, közvetlenül határos települések még: délkelet felől Simonfa, dél felől Bőszénfa, nyugat felől pedig Zselickislak. Zselicszentpál egykor a Gutkeled nemzetség birtoka volt. Neve már 1332-1337 között is szerepelt a pápai tizedjegyzékben, tehát ekkor már plebániája is volt.'),
    ('Zsennye', 'Kis- és Nagyzsennye 20. század eleji egyesüléséből jött létre. A Rába mentén, a Sorok-patak torkolatánál fekszik. Csak három települési szomszédja van: északkelet felől Rum, délnyugat felől Püspökmolnári, északnyugat felől pedig Rábatöttös. Neve a régi magyar Synnie személynévből származik, ennek eredete a Semjén (Simon) személynév. 1237-ben Sennye néven említik először.'),
    ('Zsira', 'A megye székhelyétől, Győrtől 83, Soprontól 36, Kőszegtől pedig 17 kilométerre található, Bükfürdőtől 12 kilométer távolságra van. Zsira 1920 óta határmenti település, a határ túloldalán a fülesi (Nikits) és malomházi (Kroatisch Minihof) erdők, nyugaton Locsmánd község (Lutzmannsburg) határolja. Kerékpárút köti össze Locsmánddal és Répcevissel, valamint Bükön át Bővel.'),
    ('Zsombó', 'Szegedtől északnyugatra fekszik. Szomszédai észak felől Balástya, kelet felől Szatymaz, délkelet felől Szeged (Kiskundorozsma), nyugat felől Bordány, északnyugat felől pedig Forráskút. A települést elkerülik a térség főbb útvonalai. Az 5-ös főútról Szatymazon át érhető el, a 4525-ös úton, az M5-ös autópályáról pedig a balástyai csomópontnál letérve, Forráskútig az 5422-es, majd onnan az 5405-ös úton (ez utóbbi tekinthető Zsombó főutcájának).'),
    ('Zsujta', 'A Hernád völgyében, a szlovák határ közelében található.Gönctöl északra található, Abaújvártól délnyugatra fekszik. Szomszédos települések: Abaújvár, Gönc, Hidasnémeti, Tornyosnémeti. Zsujta és környéke ősidők óta lakott hely volt, amit az 1800-as években határában talált gazdag, és értékes bronzkori leletanyag is bizonyít. Zsujta Árpád-kori település.'),
    ('Zsurk', 'A jelenkori Magyarország lakott helységei között, az alfabetikus névsorrendet tekintve az utolsó, önálló közigazgatással bíró település. Zsurk lényegében egyutcás, szalagtelkes település a Nyírség északi csücskében, a Tisza bal partján helyezkedik el. Ősi folyóparti átkelőhely Kisvárda és Munkács között félúton. Az Alföld legészakibb fekvésű települése.'),
    ('Zsáka', 'Földrajzi szempontból a Bihari-sík északnyugati peremén fekvő település. Belterülete 288, külterülete 7593 hektár. Szomszédai: észak felől Bakonszeg, északkelet felől Berettyóújfalu (Berettyószentmárton), kelet felől Furta, délkelet felől Magyarhomorog, dél felől Komádi, délnyugat felől Darvas, északnyugat felől pedig Nagyrábé. A fentiek mellett Zsáka közigazgatási területébe teljesen enklávé jelleggel beékelődik Vekerd, a lakott terület központjáról mintegy 3-4 kilométerre délnyugatra.'),
    ('Zsámbok', 'Közeli települések: Vácszentlászló, Tura, Dány, Kóka, Tóalmás, Valkó, Jászfényszaru. Az M3-as autópályáról Gödöllőnél Valkón – Vácszentlászlón át, Bagnál vagy Hatvannál dél felé lekanyarodva Turán át érhetjük el a települést. A XVII. kerület felől a legrövidebb út a Pécel – Isaszeg – Dány útvonal helyezkedik el. Nagykáta felől a Szentmártonkáta – Tóalmás az ajánlott útvonal, míg a Jászságból Jászfényszarun keresztül visz az út Zsámbokra.'),
    ('Zsámbék', 'Budapesttől nyugatra 35 kilométerre, a 324 méter magas Nyakas-hegy gerincének tövében, a Zsámbéki-medence északnyugati szélén fekszik, és annak névadó települése. Földrajzilag a Gerecse tájegység egyik nyúlványához tartozik. Környező települések: Tök, Perbál, Páty, Herceghalom, Mány, Bicske, Szomor. Éghajlati viszonyai közel azonosak a főváros budai oldaláéval, bár nyáron kevésbé melegszik fel, míg télen nagyobb a lehűlése.'),
    ('Zsédeny', 'A Rába és a Répce által közrefogott háromszögben fekszik, sík, sovány, homokos területen. A közvetlenül határos települések: észak felől Vasegerszeg, kelet felől Jákfa, dél felől Rábapaty, északnyugat felől pedig Hegyfalu. Régi település, amit a község határában feltárt vaskori sírhalom is bizonyít. Nevét az Árpád kortól ismerjük az oklevelekből…'),
    ('Zubogy', 'A közvetlenül szomszédos települések: észak felől Imola (9 kilométer) és Kánó, kelet felől Rudabánya (7 kilométer), délkelet felől Felsőkelecsény (3 kilométer), dél felől Dövény (5 kilométer), délnyugat felől Alsószuha, északnyugat felől pedig Ragály (5 kilométer). Csak közúton érhető el, Felsőkelecsény vagy Ragály érintésével, a 2603-as úton. Névadója valószínűleg egy Zbud nevű szláv származású ember volt.'),
    ('Zádor', 'A vonalon azonban 2007 márciusa óta szünetel a forgalom. Zádort 1332-ben említette először oklevél, Zadur néven helyezkedik el. Ekkor a szigetvári főesperességhez tartozott. 1460 körül cseh husziták telepedtek meg a faluban. Zádor a török időkben sem néptelenedett el, mindvégig lakott maradt. Akkori birtokosai, a Sáfrán és Csire családok a falu templomát is megmentették, köveit nem építették be a szigetvári vár falaiba, mint a környező…'),
    ('Zádorfalva', 'Az Aggteleki-karszt és a Borsodi-dombság között fekszik a Szuha-patak völgyében, Aggtelektől 11, Ózdtól pedig 29 kilométerre. A közvetlenül határos települések: észak felől Trizs, kelet felől Ragály, délkelet felől Alsószuha, délnyugat felől Kelemér és Gömörszőlős, északnyugat felől pedig Szuhafő. Névadóját Zádornak hívták, aki a 13. század elején élt.'),
    ('Záhony', 'A város térségében változik a Tisza folyásának iránya északiról délnyugatira. 694 hektáros kiterjedésével a megye és az Észak-Alföld legkisebb közigazgatási területű városa. Neve északi szláv eredetű, mint a cseh „záhon”, amelynek jelentése ágyás, barázda, kis földterület. Etimológiailag azonos eredetű a gömöri Zahoniska nevű falunévvel, vagy a székelyföldi Zágon helység déli szláv eredetű nevével.'),
    ('Zákány', 'Nevét Zákány település valószínűleg a zákányos (nyálkás) víztől kölcsönözte. Szabó D. szerént: seprő, seprőlék, ally, allyadék, zavar, zavarék, mocsok.Alapfogalomban egyezik vele záka, zákály, zákla, v. záklya, vagyis a roszúl kelt kenyérnek irgyes, szappanos, czopákás bele, mely megsürűsödött nyákhoz hasonló, s kivált a kéreg alatt gyül öszve. Gyöke zák talán am. hák természeti hangutánzó, s jelent nyálkás, turhás, hurutos pököt.'),
    ('Zákányszék', 'A Dél-Alföldön fekszik, Szegedtől nagyjából 20 kilométerre nyugatra. A szomszédos települések: észak felől Bordány, kelet felől Domaszék, dél felől Mórahalom, nyugat felől Ruzsa, északnyugat felől pedig Üllés. Zákány északi részén a késői bronzkorból való leleteket találtak a régészek, amely azt bizonyítja, hogy itt avarok éltek. I.e. 1000 körül már település volt ezen a részen.'),
    ('Zámoly', 'Zámoly központján keresztülhalad a Székesfehérvárt Gánttal összekötő 8123-as út, külterületét emellett érinti a Söréd-Bicske közti 8126-os út is. Közúton Gánt 9, Csákberény 10, Csákvár 11, Székesfehérvár 13,5, Söréd 15, Bodajk 19,5, Mór pedig 23 kilométer távolságra található. Külterületi lakott helye Forráspuszta. Határához tartozik az 1967-ben létesült Zámolyi-víztároló egy része is.'),
    ('Zánka', 'A Balaton északi partján fekszik, a Balaton-felvidéken, a térség legnagyobb városának számító Balatonfüredtől délnyugatra. Különálló településrésze a keleti határában létrehozott Gyermekváros, korábbi nevén zánkai úttörőváros. A közvetlenül határos települések: észak felől Tagyon, kelet felől Balatonakali, délnyugat felől Balatonszepezd és Kővágóörs, nyugat felől Köveskál, északnyugat felől pedig Monoszló.'),
    ('Závod', 'A megye székhelyétől, Szekszárdtól körülbelül 30 kilométerre, a legközelebbi várostól, Bonyhádtól körülbelül 20 kilométerre található. Szomszédos települések: Tevel, Mucsi, Kisvejke és Kisdorog. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. Ősi település, az első írásos feljegyzés 1231-ből maradt fenn. Wosinsky Mór, a község plébánosa és régész, a Szekszárdi Múzeum alapítója 1893-ban 104 sírból álló népvándorláskori sírmezőt tárt fel.'),
    ('Zók', 'Pécstől délnyugatra, Szentlőrinctől délkeletre helyezkedik el, Bicsérd és Aranyosgadány között, a Pécsi-víz mellett. Az ország távolabbi részei felől csak Bicsérden keresztül érhető el, a 6-os főútból kiágazó 58 102-es számú mellékúton, ez vezet végig Pázdány nevű különálló településrészén is. A település és környéke már a réz- és a bronzkorban is lakott hely volt, az itt talált e korokból származó leletek tanúsága szerint.'),
    ('Ábrahámhegy', 'Északi szomszédja Salföld, ahová a 7346-os út vezet Ábrahámhegy központjából helyezkedik el. A Balaton egyik legkedveltebb fürdőhelye, egyrészt azért, mert félkör alakban magasló hegyei nyugatról és északról védik a szelektől, másrészt mert egy völgykatlanban terül el, s ennek köszönhetően a klímája melegebb a környezetéénél. Régészeti leletek tanúsága szerint már a rómaiaknak is kedvelt helye volt.'),
    ('Ács', 'A Kisalföld északkeleti peremén, a Győr–Tatai-teraszvidéken helyezkedik el, a Concó- és a Székes-patak összefolyásánál, a Dunától 3 kilométer-re délre, Komáromtól 8 kilométer-re délnyugatra. Északkeletről az Ácsi-erdő övezi, melynek nagyobb része azonban már Komárom területéhez tartozik. Belterületének átlagos tengerszint feletti magassága 122 méter.'),
    ('Ácsteszér', 'A legközelebbi város a 15 kilométerre fekvő Kisbér. A község legmagasabb pontjáról elénk tárul a Bakonyt a Vértes hegységtől elválasztó Móri-árok, a másik irányban pedig a pannonhalmi apátság sziluettje. Tiszta levegőjű környezet, vadban gazdag erdőségek veszik körül a községet. Ácsteszér területéről indul ki…'),
    ('Ádánd', 'Ádánd történelme egészen a középkorig nyúlik vissza, és nevét először az 1200-as években említik írásos források. Az évszázadok során a község többször gazdát cserélt, és a török hódoltság idején is fontos szerepet játszott a környék falvai között. A község területén található nevezetességek között kiemelendő a Csapody-kastély, az Árpád-kori eredetű hetyei templomrom, illetve a vizeki Tallián család barokk kúriája a 18. század első feléből.'),
    ('Ág', 'A Baranyai-Hegyhát északi részén fekszik, a legközelebbi szomszéd települések észak felől Gerényes, kelet felől Alsómocsolád, délről Kisvaszar, nyugatról pedig Tékes. Komló felől szintén a 6546-os úton (majd az abból leágazó 65 176-os számú gerényesi mellékúton) érhető el. A falu első írásos emléke 1487-ből maradt fenn. Neve ebben Naghagh formában szerepel.'),
    ('Ágasegyháza', 'Az Alföldön, a Duna–Tisza közi homokhátságon, a Kiskunsági-homokháton, Kecskeméttől 21 kilométerre nyugatra helyezkedik el a Kiskunsági Nemzeti Park által körülvett területen. Közigazgatási területének délkeleti része, mintegy egynegyede tartozik a nemzeti park Orgoványi rétek nevű részterületéhez, észak felől pedig a Fülöpházi buckavidék nevű részterület határolja.'),
    ('Ágfalva', 'Lakosságának mintegy 15%-a német nemzetiségű. A Soproni-hegység lábánál fekszik Soprontól 4 kilométer-re. 2011. szeptember 25-től ismét van közúti kapcsolata az ausztriai Somfalvával is, de ezt az utat 2015. március 31-től a munkába ingázók Ausztriába irányuló megnövekedett forgalmának elterelése érdekében a somfalvai temetőnél hétköznap 5 és 8 óra, illetve 16 és 19 óra között lezárják.'),
    ('Álmosd', 'A szomszédos települések a határ magyar oldalán: észak felől Bagamér, északnyugat felől Újléta, nyugat felől pedig Kokad. Csak kis híja van annak, hogy nem határos északnyugat vagy délnyugat felől még Létavértessel is. Határszéle kelet és dél felől mintegy 7 kilométer hosszban egybeesik az országhatárral, a legközelebbi település abban az irányban Székelyhíd (Săcueni).'),
    ('Áporka', 'A Csepeli-síkon fekszik, amely a Kiskunság északi részén, Budapesttől délre van. A legközelebbi nagyobb település Kiskunlacháza (5 kilométer). A megálló helye Kiskunlacháza és Délegyháza határvonala közelében volt, Áporka központjától majdnem pontosan keleti irányban. A közúti elérését egykor biztosító utak ma már mind alsóbbrendű utaknak minősülnek.'),
    ('Ároktő', 'A Tisza mellett fekszik, Miskolctól mintegy 45 kilométerre délre. Teljes lakott területe és határának túlnyomó része a folyó jobb parti oldalán helyezkedik el, de egy bő 7 négyzetkilométernyi (nagyobbrészt természetvédelmi oltalom alá eső) területrésze a bal parti oldalon található. A legközelebbi szomszédos települések Tiszacsege 8 és Tiszadorogma 9 kilométerre helyezkedik el.'),
    ('Árpádhalom', 'Az Alföldön, a Viharsarokban, a Mágocs-ér mellett fekszik. A legközelebbi város Orosháza, közúton mintegy 10 kilométerre helyezkedik el. Közigazgatási területét – a központját messze elkerülve – érinti még az Orosházáról Szentesre vezető 4406-os, a Gyomaendrőd-Szentes közti 4642-es, valamint az inkább csak átkötő útként szolgáló 4446-os út is. A hagyomány úgy tartja, hogy a falu határában található földhalmok között vert tábort Árpád fejedelem vezéreivel, amikor Pusztaszer felé tartottak.'),
    ('Árpás', 'Árpás Magyarország északnyugati részén, a Rába mentén fekszik, a 83-as, 85-ös és 86-os főutak között, Győrtől délnyugatra 32, Csornától délkeletre 18 kilométerre. Ma már a megyeszékhely vonzáskörzetéhez tartozik. Szomszédai: észak felől Bodonhely, kelet felől Mórichida, dél felől Sobor, nyugat felől Egyed, északnyugat felől pedig Rábapordány. Közigazgatási területe északkelet felől érintkezik még egy-egy rövid szakaszon Kisbabot és Rábaszentmiklós határszélével is.'),
    ('Ártánd', 'A Bihari-síkon, a magyar-román határ mellett fekszik, Biharkeresztes város keleti szomszédságában, utóbbihoz olyan közel, hogy belterületeik összeérnek. További szomszédai: észak felől Nagykereki, északkelet felől ez előbbi Nagyzomlin nevű, különálló településrésze, északnyugat felől pedig Bedő. Kelet és dél felől a romániai Nagyvárad agglomerációjához tartozó települések határolják, a legközelebbi szomszédja Bors.'),
    ('Ásotthalom', 'A Duna–Tisza közi homokhátságon, a Bácskai-síkvidéken helyezkedik el, Szegedtől mintegy 30 kilométerre nyugatra, a magyar-szerb határ közelében. A környék tanyavilágának központja. Környéke erdős, homokos, gazdaságát a szőlészet és a vadászat jellemzi. Balla Antal 1778. évi szegedi határtérképén és a vele egykorú városi iratokban bukkant föl először az Ásotthalom, mint helynév, amely az „Ásott Halom” elnevezésű homokdomb körüli szállásokat jelölte.'),
    ('Ásványráró', 'Ásványráró a Szigetköz középső részén, a Duna jobb partján fekszik, Győrtől 20, Mosonmagyaróvártól 22 kilométerre. A vágott pajzs felső részén Ásvány címere. Kék mezőben ezüst pólya. Rajta ezüst csónak melyben egymásnak támasztva (Szent András-kereszt alakban) ezüst evező és ezüst csáklya áll. A jobbharánt álló evező szára takarja a balharánt álló csáklya szárát.'),
    ('Ászár', 'Közvetlen szomszédjai: észak felől Tárkány (légvonalban 9, közúton 10 kilométerre), északkelet felől Ete (légvonalban 6, közúton 8 kilométerre), délkelet felől Kisbér (mellyel a belterületei mára teljesen összenőttek), délnyugat felől Bakonyszombathely, nyugat felől pedig Kerékteleki (mindkét utóbbi légvonalban 5, közúton körülbelül 7 kilométerre).'),
    ('Áta', 'A török Háta névből származik, amely az 1840-es évekre változott Áta névre. A kis falu Pécstől 22 kilométerre délre, a Villányi-hegység északi lábánál fekszik, településszerkezete szerint dombvidéki sorfalu. A szomszédos települések: észak felől Szőkéd, délkelet felől Vokány, dél felől Kistótfalu, délnyugat felől Bisse, nyugat felől pedig Szalánta.'),
    ('Átány', 'A település neve a világ néprajzában jól ismert, köszönhetően a Fél Edit által kezdeményezett, és világszerte ismertté vált kutatási programnak, amelynek keretében Hofer Tamással közösen az 1970-es évek végéig módszeresen kutatták a falu társadalmi viszonyait, az ott élők életmódját, szokásait a napirendtől az öltözködésen, a munkán és a jeles ünnepeken át egészen a temetkezési szokásokig.'),
    ('Écs', 'A Sokorói-dombság (Pannonhalmi-dombvidék) ravazd-csanaki vonulata északi részének kelet-északkeleti oldalán helyezkedik el. Határának nagy része mély vízmosásokkal szabdalt dombvonulat. A település ősi magja a Szentmártoni-völgynek is nevezett völgyben épült. Mindössze három településsel határos közvetlenül: kelet és dél felől Pannonhalma külterületei övezik, nyugati szomszédja Tényő, északnyugat felől pedig Nyúl.'),
    ('Égerszög', 'Szendrőtől 17, Miskolctól közúton 50 kilométerre északra fekszik. A közvetlenül határos települések: észak és északkelet felől Teresztenye (3 kilométer), kelet felől Szőlősardó (3 kilométer), dél felől Kánó (3 kilométer), nyugat felől pedig Aggtelek. A legközelebbi város Szendrő. Belterületének délkeleti részét érinti még a 2628-as út is. Neve az éger fanév és a „sarok, szeglet, zug” jelentésű -szög utótag összetételeként arra utal, hogy a falu az Éger-völgy (Henc-völgy, Rét-völgy) fölső szakaszán (szögében) épült.'),
    ('Érd', 'A település 1979 óta város, 2006 óta megyei jogú város. Budapest központjától kb. 21 kilométer-re található délnyugati irányban, közel a Dunához, közvetlenül érintkezve a XXII. kerület gyártelepével. Történelmi központja a Duna ölelésében lévő Ófalu nevű városrész. A város leghíresebb nevezetessége a török korból megmaradt Hamza bég minaret, amely egyike a Török hódoltság idejéből Magyarországon megmaradt néhány minaretnek.'),
    ('Érpatak', 'Különálló településrésze a mintegy 69 lakosú Zsindelyes, mely a község központjától 5 kilométerre északnyugatra található, nem messze Újfehértó vasútállomástól. Geszteréddel és Nagykállóval számozatlan, alsóbbrendű utak kötik össze. A Nyírség szélére települt község az írott forrásokban a 12. század…'),
    ('Érsekcsanád', 'Budapesttől 151 kilométerre délre fekszik a Duna mellett, Baja északi szomszédságában, a várostól 8 kilométerre. Területének túlnyomó része a folyó bal parti oldalán helyezkedik el, de hozzá tartozik a túlparthoz sokkal közelebb fekvő Veránka-sziget is. További települési szomszédai: észak felől Sükösd, délkelet felől Csávoly, nyugat felől Decs, északnyugat felől pedig Őcsény (e két utóbbi a Duna túlpartján).'),
    ('Érsekvadkert', 'A Nyugat-Nógrád térségében fekszik, a Nógrádi-medencében, a Börzsöny hegység lábánál, Rétság és Balassagyarmat között. A közvetlenül határos települések: észak felől Ipolyszög, északkelet felől Csesztve, kelet felől Mohora, délkelet felől Debercsény és Szente, dél felől Szátok és Tereske, délnyugat felől Pusztaberki, nyugat felől Horpács, északnyugat felől pedig Patak és Dejtár.'),
    ('Értény', 'A Dunántúli-dombság Somogyi-dombságában, a Kánya-ér és a Jégveremi-árok találkozásánál fekszik. Szomszédos települések: Koppányszántó, Nagykónyi. Közigazgatási területén a Nagykónyi-Somogyacsa között húzódó, a 61-es főutat a 6505-ös úttal összekötő 6508-as út halad végig. Központja azonban zsákfalunak tekinthető, közúton csak az előbbi útból északnyugat felé kiágazó, mintegy 4 kilométer hosszú 65 154-es számú bekötőúton érhető el.'),
    ('Óbarok', 'A közeli települések közül Bicske és Újbarok 3-3, Felcsút 8,5, Szárliget pedig 12 kilométer távolságra található. Déli határszélét érinti a 8126-os út és ott ágazik ki utóbbiból Újbarok, Szár és Szárliget irányába a 8113-as út is. A település a Gerecse hegység délnyugati, sziklákkal csipkézett dombjainak tövében, gyönyörű természeti környezetben helyezkedik el.'),
    ('Óbudavár', 'Óbudavár a Balatontól 8 kilométerre, a festői Nivegy-völgy bejáratánál fekszik. A völgy szerkezetileg a Balaton-felvidék Balatonfüred és Badacsony közti szakaszára jellemző, a tóparti hegysor mögött kialakult márgás kőzetű medencék egyikének tekinthető, nevezik Csicsói-medence néven is. A közeli városok közül Tapolcától illetve Balatonfüredtől is kb. 25-25 kilométer választja el.'),
    ('Óbánya', 'A természeti és épített környezet szépsége miatt Óbányát néha „magyar Svájc” néven is említik. A két domb közt fekvő kis község a Kelet-Mecsek Tájvédelmi Körzet egyik szűk völgykatlanában fekszik. A 6-os főútról Mecseknádasdnál kb. 3,5 kilométer-es letéréssel találhatjuk meg. A zsáktelepülés egyetlen utcájának házai mellett gyors folyású hegyi patak, az Öreg-patak fut végig.'),
    ('Ócsa', 'Közigazgatási területéhez tartozik: Felsőbabád, Alsópakony, Czirják tanya, az Öregszőlők, Székes, Újerdő. A szomszédos települések: észak felől Felsőpakony, északkelet felől Üllő, kelet felől Csévharaszt, délkelet felől Inárcs, dél felől Dabas, délnyugat felől Bugyi, nyugat felől Alsónémedi, északnyugat felől pedig Gyál. A sztrádáról a 30-as kilométerénél lévő Ócsa–Üllő-csomópontnál kell letérni, ahonnan a 4603-as út vezet be a település központjába.'),
    ('Ócsárd', 'Pécs déli vonzáskörzetében fekszik, a megyeszékhelytől mintegy 18 kilométerre. A szomszédos települések: észak felől Görcsöny és Regenye, északkelet felől Szőke, dél felől Szava, délnyugat felől Babarcszőlős, nyugat felől pedig Kisdér. Ócsárd első lakói valószínűleg szolganépek, juhászok voltak. Ez azt is jelentheti, hogy adóikat juhokkal, vagy a juhokból készített termékekkel rótták le.'),
    ('Ófalu', 'Bonyhádtól kb. 15 kilométer-re délre fekszik, 5 kilométer-re a 6-os főútttól. Keskeny völgyben található zsáktelepülés. Ófalu a Kelet-Mecsek határán a 6-os főközlekedési úttól 5 kilométer-re fekvő sváb község, tagja a Kelet-Mecsek Gyöngyei turisztikai egyesületnek. Különleges természeti szépségét a települést övező 7 domboldal karéjban elhelyezkedő egymásra torlódó koszorúja adja.'),
    ('Óföldeák', 'Hármuk közül földrajzilag a középső: Földeák keletről, Maroslele nyugatról határolja. Lakott területe a közigazgatási terület keleti része közelében helyezkedik el, legjelentősebb külterületi településrésze, Gencshát pedig a nyugati határszélen. Gencshát ugyancsak a 4416-os út mellett fekszik, az út a községrész északi széle mellett halad el. Ellenben a 4416-os mindkét végpontjának csatlakozó útja, a 4414-es és a 4415…'),
    ('Óhíd', 'A falu egy részének első említése 1406-ból való. A XV. században teljesen nemesi település volt. A törökök ellen erődítmény létesült a településen, de mindezek ellenére többször behódolt, ám mindig csak pár évig fizethetett adót. A törökellenes harcban Óhíd teljesen függetlenül működött, ezért Szentgrót kapitánya többször panaszt is emelt a település ellen.'),
    ('Ólmod', 'A Kőszeghegyalja északi részén fekszik, Kőszegtől 4 kilométerre északkeletre, közvetlenül az osztrák határ mellett. A határ magyar oldalán csak három települési szomszédja van: északkelet felől Peresznye, kelet felől Horvátzsidány, délnyugat felől pedig Kőszeg. Nyugati irányból ausztriai területek határolják, a legközelebbi település abban az irányban Borsmonostor (Klostermarienberg).'),
    ('Ónod', 'Miskolctól 22 kilométerre délkeletre található, a környező települések közül Muhitól 3 kilométerre északra, Sajópetritől pedig 4 kilométerre délre. A legközelebbi város a nyugati szomszédságában, 7 kilométerre fekvő Nyékládháza. Legfontosabb folyóvize a Sajó, mely észak-déli irányban folyik végig a határai között, belterületétől kevesebb, mint egy kilométerre.'),
    ('Ópusztaszer', 'A Pusztaszeri Tájvédelmi Körzet közepén, a Tiszától nyugatra található. Az ország távolabbi részei felől az 5-ös főúton közelíthető meg a legegyszerűbben, kisteleki letéréssel. Ópusztaszer nevét 1200 körül említette először oklevél Scerii néven. 1233-ban Zerr, 1266-ban Scer, 1283-ban Zeer néven írták.'),
    ('Ópályi', 'Mátészalkától 4 kilométerre északra, a Kraszna partján helyezkedik el. A szomszédos települések: észak felől Nagydobos, északkelet felől Szamosszeg, dél felől Mátészalka, nyugat felől Papos, északnyugat felől pedig Nyírparasznya. Csak kevés híja van annak, hogy nem határos délnyugat felől még Jármival is. Vajával a 4116-os út köti össze. Ópályit 1294-ben említi először írásban III.'),
    ('Ózd', 'Elnevezése az úz népnévből ered. Az úzok a türkökkel rokon nép volt, akik a 11. század második felében az Al-Duna tájékán és az orosz sztyeppéken éltek. Szétszóródtak, egy részük ebbe a völgybe került, és ebből a névből alakult ki – a „d” kicsinyítő képző hozzáadásával – az Ózd név. Ez persze csak az egyik lehetséges magyarázat a név eredetére. 1325-ben Ouz formában találkozhatunk a település nevével.'),
    ('Ózdfalu', 'Az Ormánság északi részén fekszik, Pécs és Vajszló között nagyjából félúton. Kisasszonyfa felől 2022 óta műúton is érhető el. Írott dokumentum először 1296-ban említi a nevét, Owzd alakban. 1296-ban Ózdi Pál nemes a boszniai háborúban foglyul ejtett szolganőjének fiát, Balázst, 1 M-ért felszabadította. 1332-ben papja 15 báni pápai tizedet fizetett.'),
    ('Öcs', 'Ajkától 14 kilométerre délre található. Az Öcsi Nagy-tó és szép gyertyános-tölgyes erdővel borított környéke kellemes kirándulóhely. Emellett a szakembereknek botanikai szempontból is izgalmas kutatóhelye, mert több ritka faj élőhelye. A tó a Kab-hegy délnyugati lábánál kb. 330 méter tengerszint feletti magasságban egy természetes mélyedésben fekszik.'),
    ('Öcsöd', 'Határa gyengén tagolt, alacsony, ármentes síkság, melybe a Körös elhagyott-kiszáradt folyómedrei és a tájból kiemelkedő kunhalmok visznek változatosságot. Eredetileg élővíz mellett, a Körös egyik éles kanyarulata mentén települt, amely a folyó szabályozása óta holtág. A Körös hullámtere természetvédelmi terület, a Körös-Maros Nemzeti Park része. Háborítatlan erdői, ártéri legelői, lefűződött, levágott holtága nemcsak tájképileg festőiek, hanem biztonságos élőhelyet jelentenek számos védett és ritka növénynek és állatnak is.'),
    ('Ököritófülpös', 'Ma a település egésze a Szamos bal partján fekszik, a folyó szabályozása előtt azonban csak a mai Ököritó és Mácsa településrészek estek a bal parti oldalra, Fülpös a túlparton terült el. A jelenkori települést különálló részekre tagoló egykori folyószakasz ma már holtág, ami Cégénydányádtől majdnem egészen Nábrád határszéléig kanyarog, körülbelül 25 kilométer hosszúságban helyezkedik el.'),
    ('Ölbő', 'A község a Kisalföld déli széle közelében, a Rába árterületén fekszik, a Kőris-patak mentén. A szomszédos települések: észak felől Pósfa, kelet felől Rábapaty, délkelet felől Sárvár-Rábasömjén, dél felől Csénye, nyugat felől Vát, északnyugat felől pedig Szeleste. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. Ölbő ősi neve Egyházas-Ölbő volt (régi írásmóddal…'),
    ('Ömböly', 'A megyeszékhely, Nyíregyháza 68, a környező kisebb települések közül Nyírbátor 21, Bátorliget 9, Nyírvasvári 16, Penészlek pedig 10 kilométer távolságra található. A közvetlen szomszédos települések a határ magyar oldalán: észak felől Bátorliget, északnyugat felől Piricse, nyugat felől Nyírbéltek, délnyugat felől pedig Penészlek. Határszéle keleten és délkeleten, összesen több mint 12 kilométer hosszan egybeesik az államhatárral, a legközelebbi település a határ túloldalán Károlyipuszta (Horea).'),
    ('Öregcsertő', 'Kalocsa vonzáskörzetében, a várostól mintegy 10 kilométerre keletre fekszik. A szomszédos települések: észak felől Szakmár, kelet felől Kecel, dél felől pedig Homokmégy. Öregcsertővel kapcsolatos utalások legelőször a 13. század elején tűnnek fel. A falu elnevezése minden bizonnyal személynévből, a település egykori tulajdonosának nevéből ered.'),
    ('Öreglak', 'A legközelebbi városok: 8 kilométerre Lengyeltóti és 15 kilométerre Fonyód. Közúton a Lengyeltótiból Marcaliba vezető úton, amely út az elkészültekor, 1890-ben, fontos hadiútnak számított Szerbia felé. A közlekedés busszal és vonattal egyaránt jó. Előbbiből kilenc járat, utóbbiból nyolc érinti naponta Öreglakot. Cím: 8697 Öreglak, Fő u. 14.'),
    ('Örményes', 'Szomszédos települések: észak felől Fegyvernek, kelet felől Kisújszállás, dél felől Kuncsorba, nyugat felől pedig Törökszentmiklós. Közigazgatási határa északkeleten egy pontban érintkezik még Kenderes területével is.'),
    ('Örménykút', 'Határát semmilyen jelentősebb folyóvíz nem érinti. A szomszéd települések: északkelet felől Gyomaendrőd, délkelet felől Hunya és Kondoros, dél felől Kardos, nyugatról pedig Szarvas. Gyomaendrőd felől előbb a 4642-es, majd a 4641-es, végül ugyancsak a 4645-ös utakon közelíthető meg. A település nevét a török időkben Magyarországra menekült örmény kereskedők emlékét őrzi, aki a terület egykori bérlői voltak, és az itt található egykori kútnál itatták állataikat.'),
    ('Örvényes', 'A Balaton északi partján, a Tihanyi-félsziget közelében fekszik. Mindössze négy települési szomszédja van: északkelet felől Aszófő, kelet-délkelet felől Tihany, délnyugat felől Balatonudvari, észak-északnyugat felől pedig Pécsely. Csak kevés híja van annak, hogy nem határos északnyugat felől még Vászollyal is.'),
    ('Öskü', 'Öskü Veszprémtől 15 kilométerre, Várpalotától 8 kilométerre, a Keleti-Bakony délkeleti lejtőin helyezkedik el. A községtől északra, az Északi-Bakony déli lejtőjén Márkó és Bakonykúti között kilométereken át elterülő, fűfélékkel és elszórtan kisebb cserjékkel borított dolomitsziklás mezőt régen legelőként használták, 1968-tól a Magyar Néphadsereg, majd 1990 óta Magyar Honvédség Böszörményi Géza Csapatgyakorlótér Parancsnokság Nullponti lő- és gyakorlótere.'),
    ('Öttevény', 'Magyarország északnyugati részén, a történeti-földrajzi Tóköz területén, a Mosoni-Duna jobb partján, a folyóág és a Rábca folyó kiöntése között helyezkedik el, Győrtől 14 kilométer-re északnyugat-nyugati irányban. A közvetlenül határos települések: észak felől a Mosoni-Duna túlsó partján fekvő Dunaszentpál, északkelet felől Kunsziget, délkelet felől Abda, dél felől Börcs, nyugat felől Mosonszentmiklós, északnyugat felől pedig Mecsér.'),
    ('Öttömös', 'Jellegzetes dél-alföldi tájon fekszik: homoki legelők, homokpuszták, telepített erdők, növénykultúrák veszik körül. A szomszédos települések: észak felől Pusztamérges, kelet felől Ruzsa, délkelet felől Ásotthalom, délnyugat felől Kelebia, nyugat felől Kisszállás, északnyugat felől pedig Balotaszállás. Központja a főútról letérve az 5413-as úton érhető el, ugyanez az út köti össze az 53-as főúttal és Balotaszállással is.'),
    ('Ötvöskónyi', 'Nagyatád északi szomszédságában fekszik, a város központjától 6 kilométerre. A mai települést két, korábban különálló egykori község alkotja, melyek közül Ötvös a jelenkori belterület déli felének felel meg, míg Kónyi a belterület északkeleti részén helyezkedik el. A további határos települések: észak felől Segesd, északkelet felől Beleg, kelet-délkelet felől Szabás, nyugat felől pedig Somogyszob.'),
    ('Újbarok', 'A Gerecse, a Vértes peremvidéke és a Zsámbéki-medence határán helyezkedik el, Bicskétől mintegy 5 kilométerre nyugatra. A közvetlenül határos települések: északkelet felől Óbarok, délkelet felől Felcsút, délnyugat felől Bodmér, északnyugat felől pedig Szár. A környező községek már a rómaiak idejében is lakott helyek voltak, Bárokról azonban csak a 15. századból van írásos okmányunk, a későbbi adatokban is mint puszta fordul elő, így valószínűleg lakatlan terület volt.'),
    ('Újcsanálos', 'A Hernád folyó völgyében, annak bal partján helyezkedik el, a megyeszékhely Miskolctól és Szerencstől is nagyjából azonos távolságra. A történelmi Zemplén, ezen belül a Harangod-vidék része. A település ősi helyén már az Árpád korban is éltek, erre utalnak a mai Ócsanálos területén 2013-ban végzett ásatások leletei: nyílhegyeket, pénzérméket, pénzváltó mérleget, épületmaradványokat, kemencéket találtak a Herman Ottó Múzeum munkatársai.'),
    ('Újdombrád', 'Három irányból, nyugatról, északról és keletről is dombrádi külterületekkel határos. A további közvetlen szomszédai: délkelet felől Demecser, dél felől Kék, délnyugat felől pedig Beszterec. Korábban érintette a Nyírvidéki Kisvasút 119-es számú dombrádi vonala is, de 2009 óta azon a vonalon szünetel a vonatközlekedés. A dombrádi határ délnyugati részén a mocsaras tájból kiemelkedően, két, a környezetéhez viszonyítva magasabb fekvésű terület volt Borgászka és Karkhalom tanya.'),
    ('Újfehértó', 'A Közép-Nyírségben, Nyíregyházától körülbelül 16 kilométerrel délre, Debrecentől 35 kilométerrel északra, a Nyírség Hajdúság felé eső peremén fekszik. Különálló településrésze Kisszegegyháza, mely a nyugati határa közelében terül el, a várost Hajdúdoroggal összekötő út mentén. A 19. század nyolcvanas évtizedéig a települést szikes tavak övezték, majd ezeket a tavakat – a termőföld reményében – lecsapolták.'),
    ('Újhartyán', 'A legközelebbi települések: északnyugatra Kakucs, északkeletre pedig Újlengyel. Budapest központjának távolsága 43 kilométer közúton helyezkedik el. Újhartyán Duna–Tisza közi homokhátságon, a Kiskunsági-homokhát északi széle és a Pilis–Alpári-homokhát találkozásánál helyezkedik el. Területén a Duna–Tisza közi homokhátságra és a Pesti-síkságra jellemző adottságok váltakoznak.'),
    ('Újireg', 'A legközelebbi települések Iregszemcse, Nagykónyi és Tamási, de nincs messze a Balaton sem: Siófok alig 30 kilométerre található. A település 1949-ben alakult Iregszemcsének Muthpuszta és Nagykónyinak Kulcsármajor nevű részeiből, először Jásztelepszállás, majd Újireg néven helyezkedik el. A középkori Muth szerepel az 1333-as pápai tizedjegyzékben helyezkedik el.'),
    ('Újiráz', 'Természetföldrajzi szempontból a Kis-Sárrét északi részén, a Sebes-Körös jobb partján fekszik. Kelet felől Komádihoz, dél felől Vésztőhöz, délnyugat felől Szeghalomhoz, északnyugat felől pedig Csökmőhöz tartozó területek határolják. A legfiatalabb bihari település. Iráz története reményteljesen indult, de 1598-ban úgy tűnt, a tatárdúlás végleg megpecsételte a település sorsát. 1912-ben a nagyváradi káptalan településfejlesztésbe fogott, és 12 év alatt a semmiből új falu jött létre.'),
    ('Újkenéz', 'A megye és egyben a Nyírség északkeleti részén fekszik, a Tisza bal partján. A szomszédos települések: észak felől Mezőladány, kelet felől a folyó túlsó partján fekvő Tiszakerecseny, délkelet felől a szintén túlparti Tiszaadony, dél-délkelet felől Aranyosapáti, nyugat felől pedig Tornyospálca. A térség fontosabb települései közül Kisvárda 21, Aranyosapáti 7,5, Nagyvarsány 14,5, Vásárosnamény pedig 19,5 kilométer távolságra található.'),
    ('Újkér', 'Központjától többé-kevésbé elkülönülő településrészei Alszopor, Felszopor és Makkoshetye. Utóbbi a Nyugat-Magyarországi-peremvidék és a Kisalföld határán, a Sopron-Vasi-síkság középtájban található. A síkságot délről a Répce határolja, kelet felől a Kisalföld (azon belül is a Kapuvári-sík). Délnyugatról a Kőszegi-hegység, észak felől pedig az Ikva és annak síkja jelenti a természetes határokat.'),
    ('Újkígyós', 'A Maros hordalékhátán helyezkedik el, Békéscsaba délnyugati szomszédságában, a városközponttól körülbelül 15 kilométerre. A térség másik nagyobb városától, Gyulától nyugatra terül el, bő 20 kilométerre. Szomszédai: észak felől Békéscsaba, kelet felől Szabadkígyós, délkelet felől Kétegyháza, dél felől Medgyesegyháza és Pusztaottlaka, nyugat felől pedig Csabaszabadi.'),
    ('Újlengyel', 'Mindössze 6 kilométerre van Pusztavacstól, amely már a megyehatáron fekszik (egyben ott van Magyarország földrajzi középpontja is). A község a Kiskunság északi szegletének erdői között búvik meg. Lakói precíz rendben tartják településük nyugalmat sugárzó utcáit, tereit. Határának tanyáiban még érezhető e régi alföldi életforma máig tartó büszkesége.'),
    ('Újléta', 'A szomszédos települések: észak felől Vámospércs, kelet felől Bagamér, délkelet felől Álmosd és Kokad, dél felől Létavértes, délnyugat felől Monostorpályi, nyugat-északnyugat felől pedig Debrecen helyezkedik el. Első okleveles említése IV. A települést sorra érték a nagyobbnál nagyobb csapások, Abd el Rahin Hanan török szpáhi szinte az egész települést kiirtotta, ráadásul a Habsburg és Török Birodalom közötti államrész révén állandó csaták…'),
    ('Újlőrincfalva', 'A Tisza folyó jobb partján fekszik, a Tisza-tó közelében. Közigazgatásilag a határai között terül el az egykori Kiskörei-víztározó területének közel egynegyede, mely területnek nagy része a Hortobágyi Nemzeti Park oltalma alá esik. Északnyugati határai között viszont két másik, nagyobbacska terület egy egészen más, védelemre érdemes élőhelytípusba tartozik: ezek a Hevesi Füves Puszták Tájvédelmi Körzet részei.'),
    ('Újpetre', 'Villánytól északnyugatra, Siklóstól északkeletre helyezkedik el. A szomszédos települések: észak felől Peterd és Pécsdevecser, kelet felől Kiskassa, délkelet felől Palkonya, délnyugat felől Vokány, északnyugat felől pedig Kisherend. Az Árpád-kori település nevét már 1296-ban említették az oklevelek Petre néven, mint a Győr nemzetségbeli Konrád ispán (comes Corradus de Ovari) birtokát, aki a Győr nemzetség Óvári-Kéméndi ágából származott.'),
    ('Újrónafő', 'Az északi-Hanság szélén fekszik, Mosonmagyaróvártól 8 kilométerre délnyugatra. A faluból kivezető út mellett a déli határrész már védett a hansági erdők miatt. Termőföld területét is a ’Hany’ határozza meg. A régi lápterület-becsúszás rossz vízgazdálkodású, hideg, kötött talajú. Közigazgatási határszélét északon érinti még a 8506-os út is. A település élete szorosan összefonódott a tőle mintegy 6 kilométerre északra fekvő Mosonszolnokéval.'),
    ('Újsolt', 'A megélhetés java részét a mezőgazdaság, állattenyésztés adja. Mindössze hat utcából áll, melyekben száz ház található, lakosainak száma 159. A település 1950-ben vált ki Soltból, azóta önálló község, bár 1981 és 1990 között az anyaközséggel közös tanácsa volt.'),
    ('Újszalonta', 'Természetföldrajzi szempontból a Kis-Sárrét délkeleti peremén fekszik. Szomszédai: észak felől Mezőgyán, délnyugat felől Méhkerék, nyugat felől pedig Sarkadkeresztúr. Keleti irányból Romániához, ezen belül jobbára Nagyszalontához tartozó területek határolják.'),
    ('Újszentiván', 'Első ismert írásos említése 1411-ből maradt fenn. A Bánság Magyarországon maradt területén, Szeged központjától 10 kilométerre helyezkedik el. Dél-délkeleti irányban Szeged Szőreg városrészével határos, attól kevesebb, mint egy kilométer választja el. Közigazgatási területe nyugat, észak és kelet felől is szegedi területekkel határos, csak délnyugat felől van más szomszédja, Tiszasziget, illetve délkeleti határszéle mintegy 3-4 kilométernyi hosszon a déli országhatárral esik egybe, amin túl már szerbiai területek nyúlnak el.'),
    ('Újszentmargita', 'Legnyugatibb pontja a folyótól kevesebb, mint 1 kilométerre esik, de belterülete mintegy 8 kilométer távolságra fekszik a Tiszától. A közvetlenül határos települések: észak felől Folyás, északkelet felől Görbeháza, kelet felől Bagota (Görbeháza különálló településrésze), délkelet felől Balmazújváros, délnyugat felől Tiszacsege, nyugat felől Ároktő, északnyugat felől pedig Tiszakeszi (utóbbi kettő már a túlparton, a Tisza borsodi oldalán található).'),
    ('Újszilvás', 'Néprajzilag a Tápiómentéhez tartozik. A község 1950-ben alakult, az akkor Tápiószeléhez és Tápiógyörgyéhez tartozó Jeges, Újföld, Szőlősparcella részekből. Az Újszilvás elnevezést az akkoriban igen bőségesen termő szilvafákról kapta. Mezőgazdasági szempontból igen előnyös a község fekvése, hisz a szőlő- és gyümölcsültetvények mellett a termőföld is igen gazdag értékeket rejt magában, például itt termesztik az országban szinte egyedülálló módon a sörgyártás alapanyagaként szolgáló komlót.'),
    ('Újszász', 'Határában ömlik bele a Tápió folyó a Zagyvába. A megyeszékhely, Szolnok kb. 15 kilométerre található. A közvetlen szomszédos települések: északkelet felől Szászberek, délkelet felől Zagyvarékas, dél felől Abony, délnyugat felől Újszilvás, nyugat felől Tápiógyörgye, északnyugat felől pedig Jászboldogháza.'),
    ('Újtelek', 'A Kalocsai Sárköz nevű mélyfekvésű területen fekszik, a névadó várostól, Kalocsától légvonalban mintegy 8,5, közúton nagyjából 14 kilométerre, az 5308-as út mentén. Két, egykor elkülönülő településrész alkotja, a délebben elhelyezkedő Keserűtelek és az északabbi fekvésű Résztelek, melyek mára lényegében összenőttek.'),
    ('Újtikos', 'Újtikos tájföldrajzilag a Hortobágy északnyugati szélén helyezkedik el, nyugati határa kissé átnyúlik a Közép-tiszai ártérhez tartozó Borsodi-ártérbe is. Domborzatát tekintve a terület egyhangú felszínű, ártéri szintű síkság. Felszíni és felszín közeli földtani képződményei kizárólag pleisztocén és holocén időszakiak. Ma ezek a rétegek kb. 30 méter mélyen a felszín alatt helyezkednek el, a fiatalabb pleisztocén és holocén üledékek alatt.'),
    ('Újudvar', 'A településen polgárőrség működik. A település első okleveles említése 1193-ból származik Ojvduor írásmóddal III. Béla oklevelében, a fehérvári keresztesek birtokainak összeírásakor. Feltételezhetően Eufrozina királynő, II. Géza magyar király felesége adományozhatta a székesfehérvári Szent István monostoregyháznak. 1256-ban neve…'),
    ('Újvárfalva', 'Marcalitól délkeletre, Somogysárd és Nagybajom közt fekszik. Az okmányokban 1909-től szerepel Újvárfalva néven, korábban Korotna, Nadalos és Vrácsik településekből állt, ezek ma Újvárfalva részei. Ebből 616 római katolikus, 12 református, 6 evangélikus volt 1497-ben Warachyk alakban írva említették először az oklevelek, az 1537. és az 1550. évi adólajstromokban Weracsik alakban fordult elő. 1550-ben Zewrényi János birtoka volt.'),
    ('Úny', 'Úny a Dunántúl északkeleti szögletében elhelyezkedő Dunazug-hegyvidékhez tartozó Gerecse hegység Gete csoportjának délkeletre húzódó löszborította dombsági tájának déli szegélyén, az Únyi-patak egyik ágát, a diósi ágat vezető völgyben húzódik meg. A község Esztergomtól déli irányban 19 kilométerre, Budapesttől északnyugatra 35 kilométerre, a megyeszékhelytől, Tatabányától keletre 45 kilométerre, Dorogtól délre 11 kilométerre fekszik.'),
    ('Úrhida', 'Székesfehérvár agglomerációjában található, ezért az utóbbi években jelentősen megnőtt a község népessége a szuburbanizációnak köszönhetően. Völgyekkel tagolt halmon fekvő település, mely a tengerszint felett 123-191 méteres magasságban fekszik, Székesfehérvártól nagyjából 3,5 kilométerre nyugatra. Északról Sárszentmihály, Sárkeszi és Nádasdladány, nyugatról Jenő, délről pedig Polgárdi illetve Szabadbattyán határolja.'),
    ('Úri', 'Budapesttől mintegy 40 kilométer-re délkeletre fekszik, a Gödöllői-dombság nyúlványainak végénél. Felszíne dombos, a Gödöllői-dombság kistájához a Monor–Irsai-dombsághoz tartozik. Dombjai északnyugat-délkeleti irányúak. A Tápió völgyéből kiemelkedve a Mende és Sülysáp közötti határrészből 13 dombsor húzódik a község felé. A dombok széles hátán a csapadékvíz és a szél eróziós tevékenysége erősen meglátszik.'),
    ('Úrkút', 'A Déli-Bakonyban, a Kab-hegytől északra, egy hosszanti völgyben terül el, 400 méterrel a tengerszint felett. Keleti irányból Herend és Szentgál, nyugatról Ajka felől, délről Tótvázsonyról és Nagyvázsonyról érhető el. Az Úrkút helynév valószínűleg 1335 óta ismert, első említésekor a tihanyi apátság birtokrészei közé tartozóként jelölte a települést.'),
    ('Üllés', 'Szegedtől északnyugatra helyezkedik el. A szomszédos települések: északkelet felől Forráskút, kelet felől Bordány, dél felől Zákányszék, délnyugat felől Ruzsa, nyugat felől Pusztamérges, északnyugat felől pedig Kiskunmajsa és Csólyospálos. A településen végighalad, annak főutcájaként a Kiskunhalastól Szegedig húzódó 5408-as út, ez a legfontosabb közúti elérési útvonala.'),
    ('Üllő', 'A Liszt Ferenc nemzetközi repülőtér, az M0-s és az M4-es autóutak közelsége miatt kiváló logisztikai övezetbe esik. Budapest agglomerációjában fekszik, a Pesti-síkság szélén. Átlagos tengerszint feletti magassága 125 méter. A főváros központjától 25 kilométerre délkeletre, a Liszt Ferenc repülőtértől 5 kilométer távolságra található. A település mellett haladnak el az M0-s és M4-es autóutak.'),
    ('Üröm', 'Közvetlenül határos Budapest III. kerületének több városrészével, legfontosabb útvonala az 1108-as út. Budapest közvetlen szomszédságában helyezkedik el, a várostól északnyugatra. További szomszédai észak felől Budakalász, nyugat felől pedig Pilisborosjenő, illetve közigazgatási területének délnyugati részén, egy kisebb szakaszon határos Solymárral is.'),
    ('Őcsény', 'Nagy múltú és népi emlékekben gazdag település, melyet fekvése miatt a Sárköz kapujának is neveznek. Lakosainak száma 2022-ben 2148 fő volt. A településen található a megye egyetlen reptere, az őcsényi repülőtér, emellett a négy falu alkotta Őcsényi Közös Önkormányzati Hivatal székhelyeként is szolgál. A település a Sárköz északi felében, a Duna, a Sió és a Szekszárdi-dombság által közrefogott síksági területen helyezkedik el.'),
    ('Őr', 'A Nyírség északkeleti részén fekszik. A két legközelebbi város a 4 kilométerre fekvő Vaja és a 10 kilométerre lévő Mátészalka. A közvetlen szomszédos települések: északkelet felől Papos, kelet felől Jármi, dél felől Hodász, délnyugat felől Kántorjánosi, északnyugat felől pedig Vaja.'),
    ('Őrbottyán', 'Alakja: középen hasított pajzs, melynek bal oldalán az Árpád-ház címere, jobb felén kék színben arany harang látható. A címert balról arany búzakalász, jobbról szőlővessző veszi körül. A budapesti agglomeráció külső övezetében, a fővárostól mintegy 30 kilométerre északkeletre fekszik, a Nyugati-Cserháthoz kapcsolódó Gödöllői-dombság vonulatában, a Bara-patak és a Sződ–Rákos-patak sekély völgyei között.'),
    ('Őrhalom', 'Az Ipoly völgyében fekszik, közvetlenül a szlovák határ mellett. A közvetlenül határos települések a határ magyarországi oldalán: kelet felől Hugyag, délkelet felől Csitár, dél felől Nógrádmarcal, délnyugat felől Szügy, nyugat felől pedig Patvarc. A határ szlovák oldalán a legközelebbi település az Ipoly túlpartján fekvő Ipolyvarbó (Vrbovka). A két legközelebbi város Balassagyarmat és Szécsény, mindkettő 8–9 kilométerre nyugatra illetve keletre helyezkedik el.'),
    ('Őrimagyarósd', 'Első írásos említése 1270-ből való Monorosd alakban, amikor V. István király örök kiváltságlevelet adott a településnek és az őreinek (speculatores regales). 1270-ben V. István magyar király megerősítette a IV. A kiváltságai között szerepelt, hogy ezek a szabad őrök az adózástól és a magán-földesúri bíráskodástól mentesek voltak. A későbbi időkben nem tartozott a szorosan vett Őrséghez.'),
    ('Őriszentpéter', 'A megye és a Dunántúl legkevesebb lakosú városa. A település az Őrség dombjain terül el. Kelet felé végigfolyik rajta a Zala folyó, amely innen mintegy 10 kilométerre ered. A város szeres elrendezésű, kilenc szerből áll. A központi magot a Zala folyó déli partján lévő Városszer és az ettől délkeletre fekvő Baksaszer, valamint az északi oldalon fekvő Alszer adja.'),
    ('Őrtilos', 'Őrtilos a Dráva folyó bal partján fekszik: a községközpont a folyótól 1–2 kilométer-re, Szentmihályhegy településrész közvetlenül a folyó mellett: a Mura itt ömlik bele a Drávába. A legközelebbi városok Csurgó és Nagykanizsa, előbbitől mintegy 20, utóbbitól 22 kilométerre terül el. Őrtilos nevét először az 1400-as évek legelején említik oklevelek Ewr formában helyezkedik el.'),
    ('Ősagárd', 'A középkorban a királyi vadászatokon alkalmazott agarakat itt tenyésztették, az „ős-” jelzőt 1906-ban kapta megkülönböztetésképpen. A terület arculatát a Naszály és a Cserhát dombjai határozzák meg. Budapesttől 52, Váctól 21, Rétságtól 15 kilométerre található. A közvetlenül határos települések: észak felől Felsőpetény, északkelet felől Alsópetény, délkelet felől Keszeg, délnyugat felől Kosd, nyugat felől Szendehely, északnyugat felől pedig Nőtincs.'),
    ('Ősi', 'A falu északról Várpalotával, keletről Nádasdladánnyal, délnyugatról Berhidával határos. Határainak északi harmadát a hajdani Sárrét tőzeges része alkotja, dél felé enyhén dombos, foltokban szőlő, szántóföld és ligetes erdő borítja. A falu északi részén a Séd patak, délen pedig a Buhin-patak folyik át. A település déli részének nagy részét a Buhin-völgy teszi ki, mely enyhén dombos, illetve erdővel borított, helyenként mocsaras terület.')
) AS v(name, panel_leiras)
WHERE c.name = v.name;

-- 4/4. fájl kész.
